UPDATE `trans_words` SET `content_loc11`=' Oh, you\'re not Conacher. What have you got there? Oh for pity\'s sake. Yowler? AGAIN?' WHERE `word_id` = 181300; -- locales_quest - offerrewardtext : entry=26505
UPDATE `trans_words` SET `content_loc11`=' Oooh, very nice. Shiny. Loud. Now we\'re talkin\'. Not much left to do but close the deal...' WHERE `word_id` = 173204; -- locales_quest - offerrewardtext : entry=14057
