UPDATE `trans_words` SET `content_loc11`='Abbey bell rung' WHERE `word_id` = 159316; -- locales_quest - ObjectiveText1 : entry=12274
UPDATE `trans_words` SET `content_loc11`='Ably done, $N. Now we see if my suspicions are correct.' WHERE `word_id` = 178465; -- locales_quest - offerrewardtext : entry=25716
UPDATE `trans_words` SET `content_loc11`='Abominations... strong. $N... stronger.' WHERE `word_id` = 183680; -- locales_quest - offerrewardtext : entry=27160
UPDATE `trans_words` SET `content_loc11`='About bloody time! Pulroy and Zedd are dead.$B$BAnd Daegarn...$B$B<Glorenfeld shakes his head.>$B$BTaken by the Dragonflayer chieftain into the depths of these catacombs. I overheard that oversized mongrel mention something \'bout a sacrifice to the "Dread King."$B$BThe cipher is hidden away in Daegarn\'s grimy beard.$B$BWhat? Dwarves hide things in their beards all the time!' WHERE `word_id` = 156149; -- locales_quest - offerrewardtext : entry=11276
UPDATE `trans_words` SET `content_loc11`='About damn time you sissies showed up. My arms were gettin\' tired.' WHERE `word_id` = 181508; -- locales_quest - offerrewardtext : entry=26562
UPDATE `trans_words` SET `content_loc11`='About time someone put a stop to that filthy beast\'s killing spree! A job well done, $N.' WHERE `word_id` = 158489; -- locales_quest - offerrewardtext : entry=12091
UPDATE `trans_words` SET `content_loc11`='About time you woke up. We were ready to toss you into the fire with the others, but it looks like you made it.$B$BI am Mordo, the caretaker of the crypt of Deathknell. And you are the Lich King\'s slave no more.$B$BSpeak with Shadow Priest Sarvis in the chapel at the base of the hill, he will tell you more of what you must know.' WHERE `word_id` = 337433; -- locales_quest - details : entry=363
UPDATE `trans_words` SET `content_loc11`='About time! I\'ve got customers waiting.$B$BGive those here and pay attention. You\'re going to take the first step in your career as a weaponsmith.' WHERE `word_id` = 140243; -- locales_quest - offerrewardtext : entry=5284
UPDATE `trans_words` SET `content_loc11`='Above the stale, unwashed stench, you catch a whiff of a familiar smell!  It appears as if this once-mighty adventurer has a real love for kungaloosh.$B$BPeeking through the bars, you can barely make out the recipe written on his arm....' WHERE `word_id` = 163895; -- locales_quest - offerrewardtext : entry=13571
UPDATE `trans_words` SET `content_loc11`='Abyssion\'s underlings defeated' WHERE `word_id` = 182574; -- locales_quest - ObjectiveText1 : entry=26857
UPDATE `trans_words` SET `content_loc11`='Accept Redpath\'s Forgiveness' WHERE `word_id` = 140633; -- locales_quest - ObjectiveText1 : entry=27390
UPDATE `trans_words` SET `content_loc11`='Accept this quest to find archaeology points on your map!' WHERE `word_id` = 181098; -- locales_quest - details : entry=26431
UPDATE `trans_words` SET `content_loc11`='Accept this talisman as a token of our appreciation, $C.$B$BThe Eye of Zuldazar will grow in power as your bond with the trolls of Zandalar strengthens. Return to me periodically and I shall imbue the jewel.' WHERE `word_id` = 142750; -- locales_quest - offerrewardtext : entry=8049
UPDATE `trans_words` SET `content_loc11`='Accept this talisman, $C. Accept it and use its power to strike down our mutual enemies.$B$BKnow that around your neck you carry a piece of history. Kezan was once a grand territory of the Zandalar Empire. Alas, the taint of goblin trade princes would force out my proud brothers and sisters.$B$BKezan is now home to the goblin capital of the Undermine; but know that before the taint, it held greatness. Still to this day Kezan is considered sacred land to my people.' WHERE `word_id` = 142914; -- locales_quest - offerrewardtext : entry=8106
