UPDATE `trans_words` SET `content_loc11`='Bishop Lazaril wants you to bring the Light-infused Artifact to King Magni Bronzebeard in Ironforge.' WHERE `word_id` = 161172; -- locales_quest - objectives : entry=12771
UPDATE `trans_words` SET `content_loc11`='Bishop Lazaril wants you to bring the Light-infused Artifact to King Varian Wrynn in Stormwind.' WHERE `word_id` = 161181; -- locales_quest - objectives : entry=12774
