UPDATE `trans_words` SET `content_loc11`='Bites of Murkgill meat' WHERE `word_id` = 180690; -- locales_quest - ObjectiveText1 : entry=26321
UPDATE `trans_words` SET `content_loc11`='Bitterness flows through my veins like a cold river. My grandson, Mac, was such a good boy. A mere 14 years old. When the army was sent off to the front, Mac took up arms to defend the city. He was a guard in The Stockade, where the Defias gang is locked up. Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang. For that Mac was stabbed in the back.$B$BI want revenge. Bring me 10 of their precious Wool Bandanas. They are the color of blood.' WHERE `word_id` = 131796; -- locales_quest - details : entry=388
UPDATE `trans_words` SET `content_loc11`='Bjorn Halgurdsson defeated' WHERE `word_id` = 159869; -- locales_quest - ObjectiveText2 : entry=12481
UPDATE `trans_words` SET `content_loc11`='Bjorn Halgurdsson insulted' WHERE `word_id` = 159868; -- locales_quest - ObjectiveText1 : entry=12481
UPDATE `trans_words` SET `content_loc11`='Black Knight\'s Gryphon taken' WHERE `word_id` = 164024; -- locales_quest - ObjectiveText1 : entry=13663
UPDATE `trans_words` SET `content_loc11`='Blackfathom Tide Priestesses slain' WHERE `word_id` = 172762; -- locales_quest - ObjectiveText1 : entry=13901
UPDATE `trans_words` SET `content_loc11`='Blackhorn Persuaded' WHERE `word_id` = 177359; -- locales_quest - ObjectiveText1 : entry=25404
UPDATE `trans_words` SET `content_loc11`='Blackrock minions cudgeled' WHERE `word_id` = 187633; -- locales_quest - ObjectiveText1 : entry=28278
UPDATE `trans_words` SET `content_loc11`='Blackrock Orcs of Alther\'s Mill or Render\'s Camp slain' WHERE `word_id` = 181541; -- locales_quest - ObjectiveText1 : entry=26570
UPDATE `trans_words` SET `content_loc11`='Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep. The leader of the Outrunners is an orc named Tharil\'zun--we want this orc. Bring me the head of Tharil\'zun!' WHERE `word_id` = 130219; -- locales_quest - details : entry=19
UPDATE `trans_words` SET `content_loc11`='Blackrock Sergeant slain' WHERE `word_id` = 187638; -- locales_quest - ObjectiveText1 : entry=28279
UPDATE `trans_words` SET `content_loc11`='Blackrock troop slain' WHERE `word_id` = 187241; -- locales_quest - ObjectiveText1 : entry=28184
