UPDATE `trans_words` SET `content_loc11`='Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 5 Bloodspore Moth Pollen.' WHERE `word_id` = 274125; -- locales_quest - details : entry=11717
UPDATE `trans_words` SET `content_loc11`='Bloodmaul Dire Wolf weakened' WHERE `word_id` = 151277; -- locales_quest - ObjectiveText1 : entry=10506
