UPDATE `trans_words` SET `content_loc11`='Bloodtalon Hatchlings rescued' WHERE `word_id` = 175095; -- locales_quest - ObjectiveText1 : entry=24623
UPDATE `trans_words` SET `content_loc11`='Bloody well done! Right-o! Congratulations, $N, for succeeding where others have failed.$B$BI am honored to count you as a comrade of our great hunting party here. No one will ever doubt your expertise in hunting and tracking!$B$BCheers to you, I say! Cheers!' WHERE `word_id` = 131026; -- locales_quest - offerrewardtext : entry=208
UPDATE `trans_words` SET `content_loc11`='Blow the horn' WHERE `word_id` = 178816; -- locales_quest - ObjectiveText1 : entry=25813
UPDATE `trans_words` SET `content_loc11`='Blown up by lightning?$B$B<Rakjak breaks out laughing for a moment.>$B$BYou good hunter. Rakjak like you. Maybe one day you can be honorary Frenzyheart!$B$BOnly maybe though!' WHERE `word_id` = 160120; -- locales_quest - offerrewardtext : entry=12539
