UPDATE `trans_words` SET `content_loc11`='Boldrich Stonerender defeated' WHERE `word_id` = 182483; -- locales_quest - ObjectiveText1 : entry=26832
UPDATE `trans_words` SET `content_loc11`='Bolvar is a fool. I was gathering his precious \'proof\' so that I could shove it down his throat.$B$BHe is a blind buffoon. Proof stands two feet away from him and he does not see.$B$BAs for my data, it\'s lost. Gone. Unrecoverable.$B$BShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile\'s eyes.$B$BLeave me, $N.' WHERE `word_id` = 138912; -- locales_quest - details : entry=4242
UPDATE `trans_words` SET `content_loc11`='Bomb Delivered to Saurboz' WHERE `word_id` = 173037; -- locales_quest - ObjectiveText1 : entry=13993
UPDATE `trans_words` SET `content_loc11`='Bomb parts. So my suspicions were true. That\'s not something that I wanted to be right about.$B$BOkay, you and I have some grim business ahead of us then.' WHERE `word_id` = 151081; -- locales_quest - offerrewardtext : entry=10444
UPDATE `trans_words` SET `content_loc11`='Bombs Dropped' WHERE `word_id` = 189686; -- locales_quest - ObjectiveText1 : entry=29054
