UPDATE `trans_words` SET `content_loc11`='Bonded with Tarecgosa\'s Essence' WHERE `word_id` = 190566; -- locales_quest - ObjectiveText1 : entry=29269
UPDATE `trans_words` SET `content_loc11`='Bonechewers!  They should all die!  The sight of their red skin and depravity makes my blood boil!$B$BI have a mission for you, $N. Kill bonechewer orcs and collect their vile blood. There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves.$B$BBonechewers scavenge near the ruined battlements along the Path of Glory, to the south. Return to me when your mission is complete.' WHERE `word_id` = 151104; -- locales_quest - details : entry=10450
UPDATE `trans_words` SET `content_loc11`='Bonker Togglevolt escorted to safety.' WHERE `word_id` = 157309; -- locales_quest - EndText : entry=11673
UPDATE `trans_words` SET `content_loc11`='Boog and Minx Freed' WHERE `word_id` = 172797; -- locales_quest - EndText : entry=13913
UPDATE `trans_words` SET `content_loc11`='Book of the dead? Never heard of it... What\'s this about anyway? Who sent you?' WHERE `word_id` = 150170; -- locales_quest - offerrewardtext : entry=10228
UPDATE `trans_words` SET `content_loc11`='Boom baby, boom! What? You killed the Fathom-Lord already? I suppose we should stop shelling his corpse, then.' WHERE `word_id` = 185085; -- locales_quest - offerrewardtext : entry=27606
UPDATE `trans_words` SET `content_loc11`='Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.' WHERE `word_id` = 143397; -- locales_quest - objectives : entry=8361
