UPDATE `trans_words` SET `content_loc11`='Captain Edward Hanes on Wyrmscar Island wants you to kill 10 Bloodcursed Naga.' WHERE `word_id` = 272594; -- locales_quest - details : entry=9674
UPDATE `trans_words` SET `content_loc11`='Captain Elendilad slain' WHERE `word_id` = 172362; -- locales_quest - ObjectiveText1 : entry=13621
UPDATE `trans_words` SET `content_loc11`='Captain Ellis aboard the Sister Mercy in the Howling Fjord has asked that you recover 5 Barrels of Blasting Powder from the ship\'s hold.' WHERE `word_id` = 273992; -- locales_quest - details : entry=11527
UPDATE `trans_words` SET `content_loc11`='Captain Grondel wants you to kill 7 Mossy Rampagers in Drak\'Agal.' WHERE `word_id` = 160377; -- locales_quest - objectives : entry=12594
