UPDATE `trans_words` SET `content_loc11`='Captain Margun Killed' WHERE `word_id` = 187290; -- locales_quest - ObjectiveText1 : entry=28195
UPDATE `trans_words` SET `content_loc11`='Captain Nials sent you? I haven\'t seen her in ages! How is she? Did she get my letter? Oh, you\'re not here for that. Well then, let\'s get down to business!' WHERE `word_id` = 183028; -- locales_quest - offerrewardtext : entry=26982
UPDATE `trans_words` SET `content_loc11`='Captain Perrine\'s death will undoubtedly please The Dark Lady. You have performed your duty well, $C.' WHERE `word_id` = 131713; -- locales_quest - offerrewardtext : entry=370
UPDATE `trans_words` SET `content_loc11`='Captain Regulfuss at Thelsamar wants you to locate Mountaineer Gravelgaw.' WHERE `word_id` = 172408; -- locales_quest - objectives : entry=13638
UPDATE `trans_words` SET `content_loc11`='Captain Rupert at Drak\'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters.' WHERE `word_id` = 160363; -- locales_quest - objectives : entry=12591
UPDATE `trans_words` SET `content_loc11`='Captain Rupert\'s Task' WHERE `word_id` = 159936; -- locales_quest - ObjectiveText2 : entry=12501
UPDATE `trans_words` SET `content_loc11`='Captain Saynna has requested your presence at Ragnaros\' Reach. A Lieutenant of Flame has shown himself and she thinks you are our greatest chance at striking against him.$B$BMake your way there as soon as you\'re able.' WHERE `word_id` = 190496; -- locales_quest - details : entry=29244
UPDATE `trans_words` SET `content_loc11`='Captain Saynna Stormrunner is launching an attack against the Forlorn Spire. If you head to the northeast, you\'ll find her at the bottom of the ramp leading up towards that rise.$B$BI\'ve assigned her a large number of our men, but her chances of success would be greatly increased if you join her cause. It\'s your decision, $N.' WHERE `word_id` = 190431; -- locales_quest - details : entry=29204
UPDATE `trans_words` SET `content_loc11`='Captain Skyshatter Defeated' WHERE `word_id` = 153549; -- locales_quest - EndText : entry=11071
UPDATE `trans_words` SET `content_loc11`='Captain Tarkan at Silverwind Refuge wants you to defeat Tideress and 12 Befouled Water Elementals at Mystral Lake.' WHERE `word_id` = 165538; -- locales_quest - objectives : entry=25
UPDATE `trans_words` SET `content_loc11`='Captain Tyralius Freed' WHERE `word_id` = 150980; -- locales_quest - ObjectiveText1 : entry=10422
UPDATE `trans_words` SET `content_loc11`='Captain Vachon\'s death will slow down the Scarlet Crusade\'s advancement in Tirisfal quite a bit. But other threats loom.' WHERE `word_id` = 131717; -- locales_quest - offerrewardtext : entry=371
UPDATE `trans_words` SET `content_loc11`='Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn\'t have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we\'re always glad to have the extra help.' WHERE `word_id` = 153812; -- locales_quest - offerrewardtext : entry=11143
