UPDATE `trans_words` SET `content_loc11`='Dat will slow their assault a bit while Norsala be findin\' a way to calm\'m. We\'ve no desire ta be remainin\' enemies of Therazane the Stonemother.' WHERE `word_id` = 180657; -- locales_quest - offerrewardtext : entry=26314
UPDATE `trans_words` SET `content_loc11`='Dat\'s de stuff, mon! Now can you hear dem? De spirits, dey be talkin\', but dey say nothing nice. Let us bring dem to de light.' WHERE `word_id` = 187085; -- locales_quest - offerrewardtext : entry=28149
UPDATE `trans_words` SET `content_loc11`='David Wayne at Wayne\'s Retreat wants you to bring him an Overcharged Manacell.' WHERE `word_id` = 151911; -- locales_quest - objectives : entry=10665
UPDATE `trans_words` SET `content_loc11`='Dawnhearth thought we were dead? Hah!$B$BI haven\'t sent a report because we haven\'t made any progress past this point.$B$BPerhaps you can help us change that?' WHERE `word_id` = 191324; -- locales_quest - offerrewardtext : entry=29682
UPDATE `trans_words` SET `content_loc11`='Dawnwatcher Shaedlass was good to send you. There is indeed a wicked plot underway in this corrupted place.' WHERE `word_id` = 135124; -- locales_quest - offerrewardtext : entry=1198
UPDATE `trans_words` SET `content_loc11`='D-Block is all clear?  Good work, $N. We will send down a crew to start cleaning up right away.' WHERE `word_id` = 187153; -- locales_quest - offerrewardtext : entry=28165
