UPDATE `trans_words` SET `content_loc11`='Dead Zin\'jatar Raiders disposed of' WHERE `word_id` = 176775; -- locales_quest - ObjectiveText1 : entry=25215
UPDATE `trans_words` SET `content_loc11`='Dead? All of them, around the altar? And you found these spider idols on them... A mass sacrifice. They threw their lives to Shadra.' WHERE `word_id` = 180843; -- locales_quest - offerrewardtext : entry=26363
UPDATE `trans_words` SET `content_loc11`='Dead? All of them, around the altar? And you found these spider idols on them... It\'s Shadra. The Spider Loa! They\'re trying to tap her power!' WHERE `word_id` = 181345; -- locales_quest - offerrewardtext : entry=26517
UPDATE `trans_words` SET `content_loc11`='Dead? By the dozen? It\'s a start, $C. It\'s a start.' WHERE `word_id` = 184244; -- locales_quest - offerrewardtext : entry=27366
UPDATE `trans_words` SET `content_loc11`='Dead? Good! But it seems there\'s still so much to be done... fires to quench... and the soil to heal... I hope you\'ll stay close and help us reclaim Hyjal!' WHERE `word_id` = 177282; -- locales_quest - offerrewardtext : entry=25382
UPDATE `trans_words` SET `content_loc11`='Dead? Good. Let word of this deed spread, and with it, terror. The Horde will feel the consequences of their attack on Bael\'dun, and they\'ll rue the day they ever crossed us, $N.' WHERE `word_id` = 176629; -- locales_quest - offerrewardtext : entry=25182
UPDATE `trans_words` SET `content_loc11`='Dead? Good. They sealed their fate when they threw their lot in with Ragnaros and his kingdom of flame. Leave their bodies down here to crumble into ash.' WHERE `word_id` = 177900; -- locales_quest - offerrewardtext : entry=25576
UPDATE `trans_words` SET `content_loc11`='Dead?$B$B<The hexxer\'s spirit is visibly lowered at the news you bring.>$B$BThey\'ve killed Sseratus and drunk deeply of his mojo; the prophet especially!$B$BWe must figure out a way to put an end to him before he drinks too much more!' WHERE `word_id` = 159966; -- locales_quest - offerrewardtext : entry=12506
