UPDATE `trans_words` SET `content_loc11`='Feel free to read the book, "The Feast of Winter Veil", to learn more about the holiday. When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge.' WHERE `word_id` = 141815; -- locales_quest - objectives : entry=7063
UPDATE `trans_words` SET `content_loc11`='Feels good to get a little blood on your hands, doesn\'t it? Especially when that blood belongs to such self-deluded fools.' WHERE `word_id` = 185278; -- locales_quest - offerrewardtext : entry=27655
UPDATE `trans_words` SET `content_loc11`='Fel Cannonball Stacks destroyed' WHERE `word_id` = 153300; -- locales_quest - ObjectiveText1 : entry=11010
