UPDATE `trans_words` SET `content_loc11`='For 110 Insignias of the Dawn and 110 Insignias of the Crusade you may choose an item from the Argent Dawn\'s treasure cache.' WHERE `word_id` = 145203; -- locales_quest - objectives : entry=9222
