UPDATE `trans_words` SET `content_loc11`='Gann Stonespire wants you to kill 15 Bael\'dun Excavators and 5 Bael\'dun Foremen.$B$BBring Khazgorm\'s Journal to Gann Stonespire.' WHERE `word_id` = 133694; -- locales_quest - objectives : entry=843
