UPDATE `trans_words` SET `content_loc11`='Go to Stone of Inner Binding at Circle of Inner Binding in Arathi Highlands.' WHERE `word_id` = 337677; -- locales_quest - CompletedText : entry=651
UPDATE `trans_words` SET `content_loc11`='Go to Stormwind\'s Old Town and either speak to a Doomsayer or take a robe from the crate near a Doomsayer to join the doomsday cult, then equip the Doomsday Recruit\'s Robe you receive.' WHERE `word_id` = 171822; -- locales_quest - objectives : entry=25290
UPDATE `trans_words` SET `content_loc11`='Go to Sven\'s Farm and find what was buried behind the old stump.' WHERE `word_id` = 130526; -- locales_quest - objectives : entry=95
UPDATE `trans_words` SET `content_loc11`='Go to Tarren Mill and find out the status of the party sent by Thrall.' WHERE `word_id` = 171299; -- locales_quest - objectives : entry=497
UPDATE `trans_words` SET `content_loc11`='Go to the bank in Darnassus, otherwise known as the Bough of the Eternals.' WHERE `word_id` = 135759; -- locales_quest - EndText : entry=1479
UPDATE `trans_words` SET `content_loc11`='Go to the Black Morass in the Caverns of Time and obtain 10 Essences of Infinity from Rift Lords and Rift Keepers. Bring these along with  5 Elixirs of Major Defense, 5 Elixirs of Mastery and 5 Elixirs of Major Agility to Lorokeem in Shattrath\'s Lower City.$B$B*WARNING!* You can only select one alchemy specialization.' WHERE `word_id` = 152841; -- locales_quest - objectives : entry=10902
UPDATE `trans_words` SET `content_loc11`='Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light. Give him Jitters\' journal and tell him you mean to face Morbent Fel.$B$BAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise. He may help you on your quest to save us.$B$BYour mission is perilous, but hurry, $N. With each passing hour, the shadows of Duskwood grow ever darker.' WHERE `word_id` = 131272; -- locales_quest - details : entry=269
UPDATE `trans_words` SET `content_loc11`='Go to the Decrepit Ferry.$B$BSearch for the reason the Scourge are there.' WHERE `word_id` = 132007; -- locales_quest - objectives : entry=438
UPDATE `trans_words` SET `content_loc11`='Go to the docks of Ratchet in the Barrens.' WHERE `word_id` = 133980; -- locales_quest - EndText : entry=910
UPDATE `trans_words` SET `content_loc11`='Go to the front gates of Orgrimmar, read the Warchief\'s Proclamation and search 5 Orgrimmar Citizens. Keep anything suspicious that you find.' WHERE `word_id` = 171986; -- locales_quest - objectives : entry=27801
UPDATE `trans_words` SET `content_loc11`='Go to the front gates of Stormwind, read King Wrynn\'s Proclamation and search 5 Stormwind Citizens. Keep anything suspicious that you find.' WHERE `word_id` = 171952; -- locales_quest - objectives : entry=27741
UPDATE `trans_words` SET `content_loc11`='Go to the Fusion Core on top of the M.A.C. Diver in Uldum.' WHERE `word_id` = 337678; -- locales_quest - CompletedText : entry=27778
UPDATE `trans_words` SET `content_loc11`='Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova\'s instructions to find Gaeriyan.' WHERE `word_id` = 138609; -- locales_quest - objectives : entry=3912
UPDATE `trans_words` SET `content_loc11`='Go to the Gyrochoppa at the Alliance Beachhead on the Lost Isles.' WHERE `word_id` = 337679; -- locales_quest - CompletedText : entry=14241
UPDATE `trans_words` SET `content_loc11`='Go to the Howling Vale and study the Tome of Mel\'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.' WHERE `word_id` = 134411; -- locales_quest - objectives : entry=1022
UPDATE `trans_words` SET `content_loc11`='Go to The Lion\'s Pride Inn to see if anyone there has heard of the name Stalvan.' WHERE `word_id` = 130413; -- locales_quest - objectives : entry=69
UPDATE `trans_words` SET `content_loc11`='Go to the Master\'s Terrace in Karazhan and read Medivh\'s Journal. Return to Archmage Alturus with Medivh\'s Journal after completing this task.' WHERE `word_id` = 147829; -- locales_quest - objectives : entry=9645
UPDATE `trans_words` SET `content_loc11`='Go to the Master\'s Terrace in Karazhan and use Kalynna\'s Urn to summon Nightbane. Retrieve the Faint Arcane Essence from Nightbane\'s corpse and bring it to Archmage Alturus.' WHERE `word_id` = 147824; -- locales_quest - objectives : entry=9644
UPDATE `trans_words` SET `content_loc11`='Go to the Mor\'shan Rampart in the Barrens.' WHERE `word_id` = 133985; -- locales_quest - EndText : entry=911
UPDATE `trans_words` SET `content_loc11`='Go to the old Lordaeron Throne Room that lies just before descending into the Undercity.' WHERE `word_id` = 136299; -- locales_quest - EndText : entry=1800
UPDATE `trans_words` SET `content_loc11`='Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf. He can find for you the book on metallurgy that Brother Kristoff needs for his speech.' WHERE `word_id` = 131592; -- locales_quest - objectives : entry=343
UPDATE `trans_words` SET `content_loc11`='Go to the Shards of Myzrael, summon her and defeat her.$B$BGather her Eldritch Shackles and bind them to the Shards of Myzrael.' WHERE `word_id` = 132947; -- locales_quest - objectives : entry=656
UPDATE `trans_words` SET `content_loc11`='Go to the Silver Stream Mine and collect 4 loads of Miners\' Gear.$B$BReturn to Mountaineer Stormpike.' WHERE `word_id` = 131440; -- locales_quest - objectives : entry=307
UPDATE `trans_words` SET `content_loc11`='Go to the Stone of Inner Binding at the Circle of Inner Binding in Arathi Highlands.' WHERE `word_id` = 337680; -- locales_quest - CompletedText : entry=26041
UPDATE `trans_words` SET `content_loc11`='Go to the top of the Atam\'al Terrace in Shadowmoon Valley and obtain the Heart of Fury. Return to Akama at the Warden\'s Cage in Shadowmoon Valley when you\'ve completed this task.' WHERE `word_id` = 152045; -- locales_quest - objectives : entry=10707
