UPDATE `trans_words` SET `content_loc11`='Go to the Westfall Lighthouse.' WHERE `word_id` = 136117; -- locales_quest - EndText : entry=1687
UPDATE `trans_words` SET `content_loc11`='Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.' WHERE `word_id` = 140105; -- locales_quest - objectives : entry=5222
UPDATE `trans_words` SET `content_loc11`='Go to the zeppelin tower outside Orgrimmar and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.' WHERE `word_id` = 165263; -- locales_quest - objectives : entry=24576
UPDATE `trans_words` SET `content_loc11`='Go to Tortolla, the turtle ancient, at the Ashen Lake in Mount Hyjal.' WHERE `word_id` = 337681; -- locales_quest - CompletedText : entry=25510
UPDATE `trans_words` SET `content_loc11`='Go to war, $R.' WHERE `word_id` = 139701; -- locales_quest - offerrewardtext : entry=5046
UPDATE `trans_words` SET `content_loc11`='Go to where the World Pillar fragment is buried' WHERE `word_id` = 182548; -- locales_quest - ObjectiveText1 : entry=26848
UPDATE `trans_words` SET `content_loc11`='Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.' WHERE `word_id` = 135299; -- locales_quest - objectives : entry=1273
UPDATE `trans_words` SET `content_loc11`='Gobber picked up' WHERE `word_id` = 173247; -- locales_quest - ObjectiveText4 : entry=14071
UPDATE `trans_words` SET `content_loc11`='Gobbles\' Transformation Ritual Witnessed' WHERE `word_id` = 186349; -- locales_quest - ObjectiveText1 : entry=27950
UPDATE `trans_words` SET `content_loc11`='Goblin Captives freed' WHERE `word_id` = 175647; -- locales_quest - ObjectiveText1 : entry=24925
UPDATE `trans_words` SET `content_loc11`='Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.$B$BThe manual also covered our ages old oath of secrecy on our schemata. Once you become a goblin engineer, that\'s that. There is no access to gnome engineering at all.$B$BIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again. Think about it carefully, $N.' WHERE `word_id` = 138384; -- locales_quest - details : entry=3638
UPDATE `trans_words` SET `content_loc11`='Goblin Prisoner freed' WHERE `word_id` = 161466; -- locales_quest - ObjectiveText1 : entry=12843
UPDATE `trans_words` SET `content_loc11`='Goblin Survivors Rescued' WHERE `word_id` = 173066; -- locales_quest - ObjectiveText1 : entry=14001
UPDATE `trans_words` SET `content_loc11`='Goblin Zombies slain' WHERE `word_id` = 175720; -- locales_quest - ObjectiveText1 : entry=24942
UPDATE `trans_words` SET `content_loc11`='Goblins and their servants have tainted our sacred water wells!  We cannot allow this.$B$BTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.$B$BFirst we will create a cleansing totem for the Winterhoof Water Well. To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons. They are to the southwest.$B$BReturn to me with the paws and talons, $N.' WHERE `word_id` = 133345; -- locales_quest - details : entry=748
UPDATE `trans_words` SET `content_loc11`='Goblins rescued' WHERE `word_id` = 176241; -- locales_quest - ObjectiveText1 : entry=25072
UPDATE `trans_words` SET `content_loc11`='Goggath wants you to bring the Battle Triage Kit to Thagg at Raynewood Retreat.' WHERE `word_id` = 172906; -- locales_quest - objectives : entry=13958
UPDATE `trans_words` SET `content_loc11`='Going toe to toe with ogres is impressive, $N. I\'m glad I\'ve got soldiers like you out here.' WHERE `word_id` = 185809; -- locales_quest - offerrewardtext : entry=27795
UPDATE `trans_words` SET `content_loc11`='Goldark Snipehunter has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be intoxicated to see them.' WHERE `word_id` = 153701; -- locales_quest - objectives : entry=11117
UPDATE `trans_words` SET `content_loc11`='Goldrinn assisted' WHERE `word_id` = 190814; -- locales_quest - ObjectiveText1 : entry=29391
UPDATE `trans_words` SET `content_loc11`='Goliathon?  Pathaleon the Calculator?$B$BKAEL\'THAS!?$B$BPrince Kael\'thas has a hand in this?$B$B<The earthbinder fumes.>$B$BIt is insanity what he has done!  Dropping giant crystals from the sky and decimating the land can only be the work of a madman!$B$BI can assure you, the Cenarion Expedition will counter any further attempts by their forces to do this ever again.$B$BWe owe you a great debt, $N.' WHERE `word_id` = 150749; -- locales_quest - offerrewardtext : entry=10351
UPDATE `trans_words` SET `content_loc11`='Golly, that sure is a lot of medium leather that you\'ve brought round, sir! I\'m gonna make sure that all of that gets put to proper use, yes indeed. With your help we\'ll have filled our estimation for medium leather in no time!$B$BThanks, $N!' WHERE `word_id` = 143719; -- locales_quest - offerrewardtext : entry=8514
UPDATE `trans_words` SET `content_loc11`='Good - it pleases me to be working with someone who takes pride in not wasting my time.$B$BAfter I make some adjustments to this kit, you\'ll be ready to head out into the field. You\'ll be using it to collect some vital data to the task at hand.$B$BIt will take just a moment for me to finish the modifications. While you are waiting, you should probably start thinking about what you\'d like to bring to the desert with you.$B$BYes, I said the desert.' WHERE `word_id` = 131155; -- locales_quest - offerrewardtext : entry=238
UPDATE `trans_words` SET `content_loc11`='Good $R! Okay, all ready.' WHERE `word_id` = 160097; -- locales_quest - offerrewardtext : entry=12535
UPDATE `trans_words` SET `content_loc11`='Good clean fun.' WHERE `word_id` = 174567; -- locales_quest - offerrewardtext : entry=24435
UPDATE `trans_words` SET `content_loc11`='Good day to you! You were sent by Mr. Flint in Menethil Harbor? Well Mr. Flint is a strong judge of character. If he sent you, then there\'s no doubt you belong here in Kalimdor!' WHERE `word_id` = 134884; -- locales_quest - offerrewardtext : entry=1132
UPDATE `trans_words` SET `content_loc11`='Good day, $N. It was a pleasure doing business with you.' WHERE `word_id` = 145199; -- locales_quest - offerrewardtext : entry=9221
UPDATE `trans_words` SET `content_loc11`='Good day, $N. The Light is with you, I trust?$B$BWhat\'s that? You were sent by Duthorian!? My wife, how is she? I knew there was going to be trouble if I left.$B$BPlease tell me she\'s... oh, thank goodness. I\'m so glad that she\'s safe. The Defias were a threat long before these attacks, but now the King\'s advisors cannot deny it.$B$BWhat else did Duthorian have to say? You\'re the one that was sent to protect my wife? Then I thank you again, $N. I couldn\'t think of a better test of valor than that.' WHERE `word_id` = 136041; -- locales_quest - offerrewardtext : entry=1653
UPDATE `trans_words` SET `content_loc11`='Good enough for me. Don\'t get too complacent, $N. The hard part\'s about to come.' WHERE `word_id` = 179781; -- locales_quest - offerrewardtext : entry=26070
UPDATE `trans_words` SET `content_loc11`='Good fortune be with you, young one.$B$BTroll messengers arrived in the Undercity not more than a day or so ago. They spoke of young priests returning to the Valley of Spirits to speak to Ur\'kyo. I would suggest you investigate the matter on your own in case his business pertains to you. I am sure you remember the way back to Orgrimmar.' WHERE `word_id` = 171433; -- locales_quest - details : entry=5712
UPDATE `trans_words` SET `content_loc11`='Good fortune to you, comrade.$B$BThe reinforcements are here, and they are bringink food, and men, and fresh mounts. The problem is that our mounts are highly immobile when placed under the water.$B$BDirectly above this cave, you vill find tall pillars with red, leafy kelp on their tops. Seahorses hide in the kelp. Throw this lasso into the kelp and catch us some mounts for usink in the water.' WHERE `word_id` = 179916; -- locales_quest - details : entry=26104
UPDATE `trans_words` SET `content_loc11`='Good going. Doesn\'t look like much, does it?' WHERE `word_id` = 186843; -- locales_quest - offerrewardtext : entry=28090
UPDATE `trans_words` SET `content_loc11`='Good good, $N. Not sure if these are of any good quality, but if Leftwitch wanted a specific type, he should have specified before sending the Reclaimers out here to begin with.$B$BWhat say you to getting on with the next item on his list?' WHERE `word_id` = 135687; -- locales_quest - offerrewardtext : entry=1458
UPDATE `trans_words` SET `content_loc11`='Good grub. Soon we\'ll be back to fighting strength.' WHERE `word_id` = 179363; -- locales_quest - offerrewardtext : entry=25943
UPDATE `trans_words` SET `content_loc11`='Good hunting, $N! Besseleth is an old predator in these parts... I will miss her not. Take this reward as a token for being the forest champion.$B$B<Maggran rubs the wound caused by Besseleth.>$B$BPerhaps now many more will travel to Sun Rock Retreat without fearing what lurks in the dark.' WHERE `word_id` = 141175; -- locales_quest - offerrewardtext : entry=6284
UPDATE `trans_words` SET `content_loc11`='Good job getting those tonks back online. Here are those tickets I promised.' WHERE `word_id` = 191047; -- locales_quest - offerrewardtext : entry=29511
UPDATE `trans_words` SET `content_loc11`='Good job on the recovery effort $N. These cannonballs should last us a while.' WHERE `word_id` = 186499; -- locales_quest - offerrewardtext : entry=27987
UPDATE `trans_words` SET `content_loc11`='Good job with Schnottz\'s men. Sounds like you gave them something to think about. Hopefully it bought us the time we need.' WHERE `word_id` = 187600; -- locales_quest - offerrewardtext : entry=28271
UPDATE `trans_words` SET `content_loc11`='Good job! That\'ll show those arrogant Barleybrews.$B$BWell we promised you a reward and here it is. We Thunderbrew reward you with prizes, the Barleybrew reward you with foul odors and false promises.$B$BYou chose wisely.$B$BIf you want to keep making the right choice, stop by another day and help us spread the word.' WHERE `word_id` = 154110; -- locales_quest - offerrewardtext : entry=11294
UPDATE `trans_words` SET `content_loc11`='Good job! We\'re really cleaning up around here!' WHERE `word_id` = 176157; -- locales_quest - offerrewardtext : entry=25052
UPDATE `trans_words` SET `content_loc11`='Good job, $N. Here\'s your next assignment.' WHERE `word_id` = 143809; -- locales_quest - offerrewardtext : entry=8535
UPDATE `trans_words` SET `content_loc11`='Good job, $N. Thanks to you, many Gilneans will live to see another day.' WHERE `word_id` = 173283; -- locales_quest - offerrewardtext : entry=14098
UPDATE `trans_words` SET `content_loc11`='Good job, $N. That should teach the rock flayers to stay far away from us.' WHERE `word_id` = 146680; -- locales_quest - offerrewardtext : entry=9340
UPDATE `trans_words` SET `content_loc11`='Good job, $N. That\'ll slow down the burial process a little.' WHERE `word_id` = 156718; -- locales_quest - offerrewardtext : entry=11477
UPDATE `trans_words` SET `content_loc11`='Good job, $N. That\'s one less filthy, useless, Alliance scum-bag that we\'ll have to provide for...$B$BIf you\'re lookin\' for more work, the tauren and blood elf nearby need some help.$B$B\'Course we\'ve got our own set of problems to deal with out here as well...' WHERE `word_id` = 276486; -- locales_quest - offerrewardtext : entry=11711
UPDATE `trans_words` SET `content_loc11`='Good job, $N. The sanctum will be ours in no time!' WHERE `word_id` = 154483; -- locales_quest - offerrewardtext : entry=11524
UPDATE `trans_words` SET `content_loc11`='Good job, $N. You\'d do well to shed any feelings of remorse you might harbor. These naga are vicious creatures - even more so than the Azerothian ones.' WHERE `word_id` = 148137; -- locales_quest - offerrewardtext : entry=9728
UPDATE `trans_words` SET `content_loc11`='Good job, $N... you\'ve won the trust of the festival\'s brewers, earning the right to purchase a Brewfest riding ram.' WHERE `word_id` = 154304; -- locales_quest - offerrewardtext : entry=11400
UPDATE `trans_words` SET `content_loc11`='Good job, ace. I\'ve a feeling you\'re going to fit in well with us.' WHERE `word_id` = 153656; -- locales_quest - offerrewardtext : entry=11096
UPDATE `trans_words` SET `content_loc11`='Good job, kid. You deserve a little somethin\'. And hey, come back tomorrow if you get the time; I might have a job for ya.' WHERE `word_id` = 165338; -- locales_quest - offerrewardtext : entry=24638
UPDATE `trans_words` SET `content_loc11`='Good job, though I think ye might be wanting a refresher course in basic piloting.$B$BWell, no matter, one warm body\'s as good as another. Here\'s yer haul for the day.' WHERE `word_id` = 156464; -- locales_quest - offerrewardtext : entry=11390
UPDATE `trans_words` SET `content_loc11`='Good job, you\'ve taught half the ogres here to fear and respect anything vaguely $R-shaped. It\'s amazing what a little reward will do to keep people under your thumb, isn\'t it? Here\'s your payment, by the way. ...what\'s with that look?' WHERE `word_id` = 175822; -- locales_quest - offerrewardtext : entry=24963
UPDATE `trans_words` SET `content_loc11`='Good job. I wouldn\'t be surprised if the horrid things had eggs in there somewhere, but it\'ll do for now.' WHERE `word_id` = 178540; -- locales_quest - offerrewardtext : entry=25733
UPDATE `trans_words` SET `content_loc11`='Good job. Murp wish he was there to help.' WHERE `word_id` = 162960; -- locales_quest - offerrewardtext : entry=13185
UPDATE `trans_words` SET `content_loc11`='Good luck, $N. I hope you find the chap, and I hope you find him alive.$B$BIf he\'s left the safety of Darkshire then he could be prey to the beasts of the wilds.' WHERE `word_id` = 132075; -- locales_quest - details : entry=453
UPDATE `trans_words` SET `content_loc11`='Good luck, $N. I look forward to seeing you in the future.' WHERE `word_id` = 138371; -- locales_quest - offerrewardtext : entry=3631
UPDATE `trans_words` SET `content_loc11`='Good luck, mighty hero. May your victories continue to bring you fame and power as you lay waste to Scholomance!' WHERE `word_id` = 140390; -- locales_quest - offerrewardtext : entry=5505
UPDATE `trans_words` SET `content_loc11`='Good Messenger, you have served your master well.' WHERE `word_id` = 130733; -- locales_quest - offerrewardtext : entry=143
UPDATE `trans_words` SET `content_loc11`='Good news!$B$BI\'ve managed to reproduce the solution - hardly an accomplishment, of course.$B$BDoubt I\'ll live to see the day those neanderthal goblins cook up somethin\' a gnome can\'t recreate in his sleep!' WHERE `word_id` = 163405; -- locales_quest - offerrewardtext : entry=13291
UPDATE `trans_words` SET `content_loc11`='Good of you to return. As you can see, we have our hands full here.' WHERE `word_id` = 161712; -- locales_quest - offerrewardtext : entry=12898
UPDATE `trans_words` SET `content_loc11`='Good ol\' Nolen. How is he doing?  Hopefully better than I am...' WHERE `word_id` = 175292; -- locales_quest - offerrewardtext : entry=24698
UPDATE `trans_words` SET `content_loc11`='Good on you. I always feel like a part of me is missing when my gryphon isn\'t nearby. I can\'t speak for Duglas or the rest of the clan, but I\'ll be ready to ride at Firebeard\'s call.' WHERE `word_id` = 185857; -- locales_quest - offerrewardtext : entry=27811
UPDATE `trans_words` SET `content_loc11`='Good quality cocoons, these. I can see you\'ve gotten the hang of harvesting them.$B$BWe have experimented with trying to raise our own silkwing larva, but unfortunately the small ones do not produce enough silk to be of use to us.' WHERE `word_id` = 151723; -- locales_quest - offerrewardtext : entry=10617
UPDATE `trans_words` SET `content_loc11`='Good riddance to bad rubbish! I\'ll burn the foul thing later so it doesn\'t stink up the camp.' WHERE `word_id` = 178513; -- locales_quest - offerrewardtext : entry=25727
UPDATE `trans_words` SET `content_loc11`='Good riddance to foul creatures. May the naga slither back into the sea and never return.$B$BYou\'ve proven yourself on the battlefield, $N. I would ask more assistance of you in defending our lands here.' WHERE `word_id` = 177512; -- locales_quest - offerrewardtext : entry=25458
UPDATE `trans_words` SET `content_loc11`='Good riddance to him! Thank you for putting an end to their macabre twisting of magic and technology.$B$BAs a true hero of gnomes everywhere, I hereby bequeath unto you our highest honor... some power converters and your pick of any of these.$B$BI know that you\'ll put them to good use!' WHERE `word_id` = 151962; -- locales_quest - offerrewardtext : entry=10675
UPDATE `trans_words` SET `content_loc11`='Good riddance to them; that\'s what I say. Filthy creatures!$B$BSo, if you\'re certain that you eliminated those pests, then I have a little research project for you. I think you\'ll like it.' WHERE `word_id` = 151692; -- locales_quest - offerrewardtext : entry=10608
UPDATE `trans_words` SET `content_loc11`='Good riddance! Those filthy pests are more trouble than they\'re worth.' WHERE `word_id` = 189749; -- locales_quest - offerrewardtext : entry=29088
UPDATE `trans_words` SET `content_loc11`='Good riddance, mon.' WHERE `word_id` = 158720; -- locales_quest - offerrewardtext : entry=12144
UPDATE `trans_words` SET `content_loc11`='Good riddance. Another source of corruption in this world put to rest. I thank you for your bravery, $N.' WHERE `word_id` = 185466; -- locales_quest - offerrewardtext : entry=27705
UPDATE `trans_words` SET `content_loc11`='Good riddance. May those horrid things never walk these lands again.' WHERE `word_id` = 181365; -- locales_quest - offerrewardtext : entry=26525
UPDATE `trans_words` SET `content_loc11`='Good riddance.' WHERE `word_id` = 158710; -- locales_quest - offerrewardtext : entry=12142
UPDATE `trans_words` SET `content_loc11`='Good show! Good show indeed. You\'re turning into a regular wyrmslayer!$B$BCome back when you\'re ready to thin their numbers even further.' WHERE `word_id` = 163409; -- locales_quest - offerrewardtext : entry=13292
UPDATE `trans_words` SET `content_loc11`='Good show, $N! And just before I need to ship out too! Can\'t thank you enough, old friend.' WHERE `word_id` = 132667; -- locales_quest - offerrewardtext : entry=26613
UPDATE `trans_words` SET `content_loc11`='Good show, lad, but we\'ve no time to celebrate. Thandol Span\'s in danger!' WHERE `word_id` = 179996; -- locales_quest - offerrewardtext : entry=26127
UPDATE `trans_words` SET `content_loc11`='Good stuff, lad. You\'re making fast friends.$B$BIf you stop back by soon, I\'m sure we can find one that will let you ride... they should know that you\'re trustworthy now.' WHERE `word_id` = 161583; -- locales_quest - offerrewardtext : entry=12867
UPDATE `trans_words` SET `content_loc11`='Good stuff, that stormstout, huh?$B$BI have another recipe that I learned from Chen. Would you be interested? It won\'t take long to make, and it might be useful if you plan on adventuring some more.$B$BBring me 5 lightning glands from any stormhide, 1 thunderhawk saliva gland from greater thunderhawks, and a kodo liver from any of the Barrens\' kodos.$B$BLike I said, this stuff has kick; it\'s the trogg ale that I mentioned to you before.' WHERE `word_id` = 133600; -- locales_quest - details : entry=822
UPDATE `trans_words` SET `content_loc11`='Good that the ethereal filth and their leader are dead. I wish a thousand plagues upon their brethren!$B$BYou are to be rewarded for you actions on behalf of all of the Mok\'Nathal, $N! You are truly one of our heroes.$B$BLet us now release the souls of our ancestors to the cleansing fire.' WHERE `word_id` = 152693; -- locales_quest - offerrewardtext : entry=10867
UPDATE `trans_words` SET `content_loc11`='Good that you\'re alive, $N. Bad that the water still exists. I was hoping to find at least one pure source of water here in Felwood. It looks like my search has failed. The process of healing the land could have been made much easier with its existence.$B$BI will have to concern myself with saving what forest creatures I can while destroying those that have become so corrupt that they endanger themselves as much as travelers through this once-mighty forest.' WHERE `word_id` = 139956; -- locales_quest - offerrewardtext : entry=5156
UPDATE `trans_words` SET `content_loc11`='Good thing that I just happen to be a grand master of all things explosively alchemical. This won\'t ignite on its own, though.' WHERE `word_id` = 181035; -- locales_quest - offerrewardtext : entry=26410
UPDATE `trans_words` SET `content_loc11`='Good thing that you and Warlord Krogg made friends with the red dragons.' WHERE `word_id` = 185457; -- locales_quest - offerrewardtext : entry=27703
UPDATE `trans_words` SET `content_loc11`='Good thing you\'re here! I\'m gonna need a lot of help if we want to beat these gnomes to the punch.' WHERE `word_id` = 175742; -- locales_quest - offerrewardtext : entry=24947
UPDATE `trans_words` SET `content_loc11`='Good tidings you bring bearing the Sign, $N. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing\'s ruthless lieutenants, the twins Blacklash and Hematus.' WHERE `word_id` = 133282; -- locales_quest - offerrewardtext : entry=732
UPDATE `trans_words` SET `content_loc11`='Good timing, $C. We were just about to unleash a counter-attack.' WHERE `word_id` = 185089; -- locales_quest - offerrewardtext : entry=27607
UPDATE `trans_words` SET `content_loc11`='Good to finally meet you, $N. I\'ve heard all about what you\'ve been up to and let me just say that I\'m impressed! Think you can lend us your expertise?' WHERE `word_id` = 172927; -- locales_quest - offerrewardtext : entry=13964
UPDATE `trans_words` SET `content_loc11`='Good to have a real warrior at my side. Too often, my shaman brethren can\'t seem to stomach the work.' WHERE `word_id` = 177466; -- locales_quest - offerrewardtext : entry=25439
UPDATE `trans_words` SET `content_loc11`='Good to have ya, brotha. Vol\'jin makes us all proud in dese moments. It feels good ta be tacklin\' threats head on.' WHERE `word_id` = 176096; -- locales_quest - offerrewardtext : entry=25035
UPDATE `trans_words` SET `content_loc11`='Good to have you fighting at my side again, $N! And I see the Firebeards have come as well. I suppose they\'ll provide a distraction while me and my boys do the heavy lifting.' WHERE `word_id` = 188032; -- locales_quest - offerrewardtext : entry=28377
UPDATE `trans_words` SET `content_loc11`='Good to have you, $N. Ready to sew some chaos?' WHERE `word_id` = 188686; -- locales_quest - offerrewardtext : entry=28590
UPDATE `trans_words` SET `content_loc11`='Good to hear that Lethvalin made it to safety. and that he was smart enough to ask you for help instead of just waiting there.$B$BI hope that Ranger Salissa made it safely to Farstrider Enclave.' WHERE `word_id` = 146304; -- locales_quest - offerrewardtext : entry=9145
UPDATE `trans_words` SET `content_loc11`='Good to see a new face around here! The forest crawls with Horde, but my assignment requires that I keep this outpost safe. I could really use someone who might be up for a good fight.' WHERE `word_id` = 181028; -- locales_quest - offerrewardtext : entry=26408
UPDATE `trans_words` SET `content_loc11`='Good to see that you survived that impact. Quite the explosion!$B$BWe can\'t afford for the Horde to make off with all that lumber.$B$BWell done, $C.' WHERE `word_id` = 159680; -- locales_quest - offerrewardtext : entry=12437
UPDATE `trans_words` SET `content_loc11`='Good to see ya, kid. Would\'ve been even better if you\'d have been here to help me take care of these little savages...' WHERE `word_id` = 186527; -- locales_quest - offerrewardtext : entry=27993
UPDATE `trans_words` SET `content_loc11`='Good to see you again $N. It does appear that we need more light leather for the creation of the various war materiel. If you could bring me a stack of ten that would be just perfect.' WHERE `word_id` = 143707; -- locales_quest - details : entry=8512
UPDATE `trans_words` SET `content_loc11`='Good to see you again! We worried when you not come back right away.$B$BJaloot beat you back - lot of energy in Jaloot, he pretty fast. He told me how you save him from lich thing. Moodle told me how you save mosswalkers too. You really nice.$B$BI hope you stay with us for while. Always something need doing.' WHERE `word_id` = 160843; -- locales_quest - offerrewardtext : entry=12695
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $C! So you had a medallion made? Good -- you\'ll need that for your next quest...' WHERE `word_id` = 143352; -- locales_quest - offerrewardtext : entry=8349
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $C. I almost thought we\'d lost you to the Wavespeaker\'s fool errand.$B$BDid anything come of it?' WHERE `word_id` = 179413; -- locales_quest - offerrewardtext : entry=25747
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $C. We are still working on preparations here for the war effort, and I can still use all of the help that you can give in gathering up wool bandaging. Any assistance at all will be greatly appreciated. I only hope that our efforts will be good enough. I\'ve lost too many noble souls on the battlefields of yesterday to not do everything in my power to see to it that doesn\'t happen again.' WHERE `word_id` = 144006; -- locales_quest - details : entry=8605
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $N! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another?$B$BTo the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera\'s tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.' WHERE `word_id` = 272585; -- locales_quest - details : entry=9649
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $N. But I\'m gonna have to cut our reunion short--Aelthalyste sent word that you were to return to her in the Undercity. She\'s still in the War Quarter.$B$BDon\'t worry though--I think it\'s a good thing. It was mentioned that she was pleased with your progress, so don\'t fret too much.' WHERE `word_id` = 171425; -- locales_quest - details : entry=5706
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $N. I have some news from Mirkfallon Lake.' WHERE `word_id` = 178696; -- locales_quest - offerrewardtext : entry=25769
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $N. Let us put the fear of the Goddess into the Grimtotem.' WHERE `word_id` = 183969; -- locales_quest - offerrewardtext : entry=27275
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $N. Now we\'ll get somewhere.' WHERE `word_id` = 182492; -- locales_quest - offerrewardtext : entry=26834
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $N. Thanks for the rescue in Ashenvale. Damn shame about all the gnomes we lost. You ready to get down to business?' WHERE `word_id` = 178124; -- locales_quest - offerrewardtext : entry=25640
UPDATE `trans_words` SET `content_loc11`='Good to see you again, $N. Your Lasher here has invented a new game - hide and seek!$B$BIt looks like he wants to play with you.$B$BWait until he hides himself, then look for him somewhere in the camp.$B$BIf he\'s too well-hidden, I\'ve created this special mist that will reveal his general direction. Don\'t tell him I gave it ito you.' WHERE `word_id` = 190540; -- locales_quest - details : entry=29259
UPDATE `trans_words` SET `content_loc11`='Good to see you alive!$B$BNo, of course I don\'t have that gold I owe you. Now\'s not really the time to bring that up is it?$B$BListen, maybe I can teach you a trick or two that might save your skin with all the carnage going on. I\'d call it more than even then. What do you say?$B$BAfter your lesson is over, try using your new technique against the Bloodfang Worgen to our west.' WHERE `word_id` = 173768; -- locales_quest - details : entry=14272
UPDATE `trans_words` SET `content_loc11`='Good to see you back in one piece, $N! You\'re quite a piece of work. I\'ll be tellin\' Captain Stoutfist how you took care of those orcs!' WHERE `word_id` = 180190; -- locales_quest - offerrewardtext : entry=26189
UPDATE `trans_words` SET `content_loc11`='Good to see you here. Estulan is being...difficult. We\'re going to have to deal with these ogres for Lady Shandris on our own until he decides to deal with us.' WHERE `word_id` = 177531; -- locales_quest - offerrewardtext : entry=25463
UPDATE `trans_words` SET `content_loc11`='Good to see you out here! Let\'s get to it.' WHERE `word_id` = 181456; -- locales_quest - offerrewardtext : entry=26548
UPDATE `trans_words` SET `content_loc11`='Good to see you safe and sound, $N. I hope things weren\'t too tough for you.$B$BI\'ll get these to Tymor right away. He\'ll be thrilled to take a look at these things.$B$BGo ahead and toss the flare gun... probably won\'t be any good to you anymore anyway, and I already got a new one.' WHERE `word_id` = 138113; -- locales_quest - offerrewardtext : entry=3449
UPDATE `trans_words` SET `content_loc11`='Good to see you\'re still alive, $N. So, it went well with Dashel then, huh?$B$BI\'ve been reading up more on this plan of theirs, and although it doesn\'t state the name of the diplomat they were after, it does talk about this plan B they enacted after failing on their first attempt to capture him.$B$BThis Slim that Dashel mentioned doesn\'t have any other name written here, but if you say he\'s in Menethil, then that\'s a start.' WHERE `word_id` = 135227; -- locales_quest - offerrewardtext : entry=1247
UPDATE `trans_words` SET `content_loc11`='Good to see you\'re still in one piece, $N.' WHERE `word_id` = 185615; -- locales_quest - offerrewardtext : entry=27748
UPDATE `trans_words` SET `content_loc11`='Good work - I\'ll start my analysis on these now! I can tell you right from the start though... these are nothing like any insect form I have ever seen. It\'s almost as if these bugs are being controlled by an outside force or something.$B$BYou need to go talk to Fizzledowser right away; apparently there is an emergency that he needs your help with on the double! I\'m not sure, but I think it involves more of the bugs in the Tanaris desert!' WHERE `word_id` = 275438; -- locales_quest - offerrewardtext : entry=82
UPDATE `trans_words` SET `content_loc11`='Good work back there, $N. Looks like we\'ve lost them, for now at least.' WHERE `word_id` = 186177; -- locales_quest - offerrewardtext : entry=27905
UPDATE `trans_words` SET `content_loc11`='Good work getting those runestones. To be honest, I only needed one, but the thought of so many night elves slain for such useless baubles fills me with a dark, giddy joy. Please hold one of those runes up to the scrying stone to let me see. Hmmm. As I suspected, an amateur effort at best.' WHERE `word_id` = 174344; -- locales_quest - offerrewardtext : entry=14429
UPDATE `trans_words` SET `content_loc11`='Good work!  This will do nicely to replenish our depleted healing crystals.$B$BBut now that you\'re here, I think I have another use for you, if you\'re willing?' WHERE `word_id` = 146901; -- locales_quest - offerrewardtext : entry=9409
UPDATE `trans_words` SET `content_loc11`='Good work! I just know the Light shines favorably upon us for our work. Our cause is righteous!' WHERE `word_id` = 182990; -- locales_quest - offerrewardtext : entry=26973
UPDATE `trans_words` SET `content_loc11`='Good work! Keep practicing your charge and you\'ll have an instant advantage at the start of battle.' WHERE `word_id` = 180247; -- locales_quest - offerrewardtext : entry=26204
UPDATE `trans_words` SET `content_loc11`='Good work! Pink elekks... what a preposterous notion!' WHERE `word_id` = 153707; -- locales_quest - offerrewardtext : entry=11118
UPDATE `trans_words` SET `content_loc11`='Good work! With any luck at all, the destruction of their egg clutches and whelps should drive off those fiery beasts and prevent that magical blaze from spreading.$B$BWait... what\'s that sound? It sounds like the beating of wings.' WHERE `word_id` = 155462; -- locales_quest - offerrewardtext : entry=11157
UPDATE `trans_words` SET `content_loc11`='Good work!$B$BLet me have a look at those code sheets. I\'ve got an idea and it might just be crazy enough to work!' WHERE `word_id` = 149312; -- locales_quest - offerrewardtext : entry=10015
UPDATE `trans_words` SET `content_loc11`='Good work, $C! You\'ve done the Horde proud by stopping the Scourge from setting down roots on our soil. An act like that deserves a reward, and the Forsaken have enough lying around that I\'m sure they can spare a few things. We may not know everything they\'ve done in the Downs, but we\'ll find out. They can\'t slink around in the dark forever.' WHERE `word_id` = 275189; -- locales_quest - offerrewardtext : entry=14353
UPDATE `trans_words` SET `content_loc11`='Good work, $C! Your efforts will help keep the enemy on their heels while our forces sweep across the land!' WHERE `word_id` = 172327; -- locales_quest - offerrewardtext : entry=13612
UPDATE `trans_words` SET `content_loc11`='Good work, $C. I must say that I\'m pleasantly surprised. You would not believe the number of people that have come by, offering to help, but never returning. Let me just get those into a crate and tallied with your name on it, and then we can talk again about whether I need anymore of those plants.' WHERE `word_id` = 143697; -- locales_quest - offerrewardtext : entry=8509
UPDATE `trans_words` SET `content_loc11`='Good work, $C. I\'m sure that these thick leather skins will be put to use reinforcing zeppelins and making all manner of armor and weaponry. You have my thanks, and that of the Horde. Come back again if you come across more thick leather in your travels, and luck be with you.' WHERE `word_id` = 143966; -- locales_quest - offerrewardtext : entry=8590
UPDATE `trans_words` SET `content_loc11`='Good work, $C. Now you know the lay of the land. If you\'re ever having difficulty fighting here on the Twilight Shores, remember that capturing and holding the Beach Head will give all Horde forces here a combat advantage!' WHERE `word_id` = 185093; -- locales_quest - offerrewardtext : entry=27610
UPDATE `trans_words` SET `content_loc11`='Good work, $C. That tunnel is our lifeline to the swamp.' WHERE `word_id` = 152954; -- locales_quest - offerrewardtext : entry=10927
UPDATE `trans_words` SET `content_loc11`='Good work, $C. We\'re that much closer to the secrets of Uldum.' WHERE `word_id` = 177406; -- locales_quest - offerrewardtext : entry=25420
UPDATE `trans_words` SET `content_loc11`='Good work, $C.$B$BThis should help ensure that the wildlife in these parts ends up where it should - roasting over our fires.' WHERE `word_id` = 159027; -- locales_quest - offerrewardtext : entry=12215
UPDATE `trans_words` SET `content_loc11`='Good work, $N!  Your latest actions in Arathi Basin were quite difficult, and so their successes are quite praiseworthy. The League of Arathor must be reeling from the last skirmishes in the basin, licking their wounds and, let us hope, rethinking their choice to fight here.' WHERE `word_id` = 271899; -- locales_quest - offerrewardtext : entry=8121
UPDATE `trans_words` SET `content_loc11`='Good work, $N! Kormok wasn\'t all that bad for an ogre, at least not while he was still alive, so I hope he gets the rest that he deserves. And now we have the completed amulet! But we still have the hardest test ahead of us.$B$BIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.' WHERE `word_id` = 144755; -- locales_quest - offerrewardtext : entry=8992
UPDATE `trans_words` SET `content_loc11`='Good work, $N! Kormok wasn\'t all that bad for an ogre, at least not while he was still alive, so I hope he gets the rest that he deserves. But, there is more work ahead of us.$B$BUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.' WHERE `word_id` = 144696; -- locales_quest - offerrewardtext : entry=8969
UPDATE `trans_words` SET `content_loc11`='Good work, $N, and good riddance.$B$BBut, what you say about that place troubles me still, and I think our culling is not quite at an end!' WHERE `word_id` = 155322; -- locales_quest - offerrewardtext : entry=11235
UPDATE `trans_words` SET `content_loc11`='Good work, $N. Did you look through these? They\'re barely legible - more like angry graffiti than war plans. Hatred, jealousy, rage, personal conflicts - it\'s a wonder Verog can keep these centaur from killing each other, much less form them into an army. We can use this to our advantage.' WHERE `word_id` = 173251; -- locales_quest - offerrewardtext : entry=14072
UPDATE `trans_words` SET `content_loc11`='Good work, $N. I doubt any of the woodsmen would\'ve wanted to take a crack at the proto-drake, but we couldn\'t afford to let the Dragonflayers build a base of power in Grizzly Hills. If only the Horde was so easily dealt with...' WHERE `word_id` = 159215; -- locales_quest - offerrewardtext : entry=12255
UPDATE `trans_words` SET `content_loc11`='Good work, $N. Issuing that challenge to the Foulwealds and defeating their leader sends them a strong message:$B$BThe Horde is not to be trifled with.$B$BI don\'t believe that tribe will giving us much trouble for a long time.' WHERE `word_id` = 141545; -- locales_quest - offerrewardtext : entry=6621
UPDATE `trans_words` SET `content_loc11`='Good work, $N. It\'s up to all of Thunder Bluff\'s fishers to keep this vicious creature out of Mulgore\'s waters.' WHERE `word_id` = 190281; -- locales_quest - offerrewardtext : entry=29345
UPDATE `trans_words` SET `content_loc11`='Good work, $N. Now let\'s see if we can make our way up there before they\'re able to recover.' WHERE `word_id` = 188355; -- locales_quest - offerrewardtext : entry=28497
UPDATE `trans_words` SET `content_loc11`='Good work, $N. Our agent, Marg Nighteye, was stationed outside Theramore. He was charged to spy on the city. $B$BThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...' WHERE `word_id` = 135191; -- locales_quest - offerrewardtext : entry=1238
UPDATE `trans_words` SET `content_loc11`='Good work, $N. Outland\'s secrets will not stay hidden from us for very long.$B$BIt\'s our destiny to become the masters of this world.' WHERE `word_id` = 146840; -- locales_quest - offerrewardtext : entry=9396
UPDATE `trans_words` SET `content_loc11`='Good work, $N. The wards are slowly regaining their power. Sun\'s Reach will be ours in no time!' WHERE `word_id` = 154478; -- locales_quest - offerrewardtext : entry=11523
UPDATE `trans_words` SET `content_loc11`='Good work, $N. The wards are slowly regaining their power. The sanctum will be ours in no time!' WHERE `word_id` = 154405; -- locales_quest - offerrewardtext : entry=11496
UPDATE `trans_words` SET `content_loc11`='Good work, $N. There\'s a chance the forest will recover from this yet. Now, there\'s something else I need you to take care of for me...' WHERE `word_id` = 177617; -- locales_quest - offerrewardtext : entry=25492
UPDATE `trans_words` SET `content_loc11`='Good work, $N. These weapons will ensure our Deathguards don\'t get caught unprepared.$B$BYou have done a valuable service for our Dark Lady.' WHERE `word_id` = 141204; -- locales_quest - offerrewardtext : entry=6324
UPDATE `trans_words` SET `content_loc11`='Good work, $N. These will do nicely.' WHERE `word_id` = 180300; -- locales_quest - offerrewardtext : entry=26220
UPDATE `trans_words` SET `content_loc11`='Good work, $N. Those beasts could have been a greater threat than the quilboar themselves, if we had not taken action now.' WHERE `word_id` = 174415; -- locales_quest - offerrewardtext : entry=14459
UPDATE `trans_words` SET `content_loc11`='Good work, $N. With more people like you we\'ll soon restore our lands to their former glory.' WHERE `word_id` = 146023; -- locales_quest - offerrewardtext : entry=8476
UPDATE `trans_words` SET `content_loc11`='Good work, $N. With this, it\'s only a matter of time until the orcs are fleeing for the portal or begging for surrender.' WHERE `word_id` = 186013; -- locales_quest - offerrewardtext : entry=27851
UPDATE `trans_words` SET `content_loc11`='Good work, $N. You have a natural talent for our arts.' WHERE `word_id` = 180232; -- locales_quest - offerrewardtext : entry=26200
UPDATE `trans_words` SET `content_loc11`='Good work, $R. I\'ll show them how an armored ship should be built!' WHERE `word_id` = 172694; -- locales_quest - offerrewardtext : entry=13883
UPDATE `trans_words` SET `content_loc11`='Good work, $R. One less thing we have to worry about!' WHERE `word_id` = 172560; -- locales_quest - offerrewardtext : entry=13806
UPDATE `trans_words` SET `content_loc11`='Good work, $R. This should keep them licking their wounds for a time.' WHERE `word_id` = 172935; -- locales_quest - offerrewardtext : entry=13967
UPDATE `trans_words` SET `content_loc11`='Good work, and good riddance. I hope we never have to see another ogre here again!' WHERE `word_id` = 177451; -- locales_quest - offerrewardtext : entry=25434
UPDATE `trans_words` SET `content_loc11`='Good work, boy. Good to have another capable set of hands about.' WHERE `word_id` = 185822; -- locales_quest - offerrewardtext : entry=27803
UPDATE `trans_words` SET `content_loc11`='Good work, friend. You have earned your pay well. Who knows, perhaps Westfall will prosper once again.' WHERE `word_id` = 130177; -- locales_quest - offerrewardtext : entry=9
UPDATE `trans_words` SET `content_loc11`='Good work, friend.$B$BAmazing what a little of one\'s colors do for a battleground.$B$BYou\'ll want to head on over to Captain Rupert next. He\'s stationed at the wall, just northeast of here.' WHERE `word_id` = 159942; -- locales_quest - offerrewardtext : entry=12502
UPDATE `trans_words` SET `content_loc11`='Good work, hero. You done good for Sen\'jin today. No... you done good for all of Durotar.' WHERE `word_id` = 176581; -- locales_quest - offerrewardtext : entry=25169
UPDATE `trans_words` SET `content_loc11`='Good work, kid. All of the pain is worth it if even one of my soldiers\' lives is saved by your efforts.$B$BI think you should benefit from your sweat and tears, too. Since we\'re going to have a new batch of weapons soon, why don\'t you take one of mine?' WHERE `word_id` = 151783; -- locales_quest - offerrewardtext : entry=10632
UPDATE `trans_words` SET `content_loc11`='Good work, mon! Dis stuff come easy to ya.' WHERE `word_id` = 175149; -- locales_quest - offerrewardtext : entry=24640
UPDATE `trans_words` SET `content_loc11`='Good work, soldier!$B$BNow take this key and get yourself down to Venture Bay. It\'ll let you use one of the refurbished shredders to unleash chaos on our enemies.$B$BOh yes, and talk to Darrok if you want to take the shortcut!' WHERE `word_id` = 159290; -- locales_quest - offerrewardtext : entry=12270
UPDATE `trans_words` SET `content_loc11`='Good work, treasure hunter!' WHERE `word_id` = 130715; -- locales_quest - offerrewardtext : entry=138
UPDATE `trans_words` SET `content_loc11`='Good work. Gaines passed through here not long ago on his way to Northwatch and a warm bath. The mission wasn\'t a total loss, though. We\'ve learned a good deal about these quilboar and their leadership structure. Now we can handle things ... MY way.' WHERE `word_id` = 176046; -- locales_quest - offerrewardtext : entry=25022
UPDATE `trans_words` SET `content_loc11`='Good work. Honestly, I\'m amazed you were able to find this many. With each clutch, they seem fewer in number.$B$BI\'ll let you raise one of the freshly-hatched venomhides. It shouldn\'t be shy about letting you know what it needs.' WHERE `word_id` = 164450; -- locales_quest - offerrewardtext : entry=13887
UPDATE `trans_words` SET `content_loc11`='Good work. One moment please... Yes, this appears to be the same corruption that is affecting the wildlife. With this knowledge, and with your combat expertise, we may have the power to stop this.' WHERE `word_id` = 183324; -- locales_quest - offerrewardtext : entry=27057
UPDATE `trans_words` SET `content_loc11`='Good work. Thank you, $C.' WHERE `word_id` = 171997; -- locales_quest - offerrewardtext : entry=13504
UPDATE `trans_words` SET `content_loc11`='Good work. Their infiltrators are skilled, but they\'re not good enough to escape the watchful eye of the Horde!' WHERE `word_id` = 135138; -- locales_quest - offerrewardtext : entry=1201
UPDATE `trans_words` SET `content_loc11`='Good work. This should keep us for another few hours before we have to go back for more. He doesn\'t seem to be the brightest of giants. I expect we\'ll be able to keep doing this for a while before he catches on.' WHERE `word_id` = 173674; -- locales_quest - offerrewardtext : entry=14250
UPDATE `trans_words` SET `content_loc11`='Good work.$B$BIf you ask me, all that we have to do is kill enough of those colossi, and then we won\'t have to worry any longer about the ridge or that strange crystal in the middle of it.$B$BHere, take one of these as a gift from the Cenarion Expedition.' WHERE `word_id` = 149780; -- locales_quest - offerrewardtext : entry=10132
UPDATE `trans_words` SET `content_loc11`='Good!  Those marsh beasts have no right to invade the home of the sporeloks!$B$BIt would be better if these creatures would learn to live in harmony, but when that\'s not possible, we\'ll be here to take care of the situation!$B$BHere, please take one of these as thanks for your help.' WHERE `word_id` = 149623; -- locales_quest - offerrewardtext : entry=10096
UPDATE `trans_words` SET `content_loc11`='Good! I was worried about foodstuffs. I already pretty hungry.$B$BThank you, $R.' WHERE `word_id` = 160082; -- locales_quest - offerrewardtext : entry=12532
UPDATE `trans_words` SET `content_loc11`='Good! Without heavy equipment, the Horde will have to pull back to regroup. We\'ve bought ourselves some time to re-secure the fortress. Well done!' WHERE `word_id` = 175746; -- locales_quest - offerrewardtext : entry=24948
UPDATE `trans_words` SET `content_loc11`='Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.$B$BAt the very ends of Westfall\'s Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he\'s gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.$B$BReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there.' WHERE `word_id` = 136029; -- locales_quest - details : entry=1650
UPDATE `trans_words` SET `content_loc11`='Good, $C. The enemy may be tough, but you have proven today that you are tougher.' WHERE `word_id` = 190700; -- locales_quest - offerrewardtext : entry=29304
UPDATE `trans_words` SET `content_loc11`='Good, $C. You have done well in serving the Dark Lady. Your continued perseverance and ambition will be of great use to the Lady\'s subjects. Return to me again in the future. Perhaps I will have other tasks for you that will aid the Dark Lady in her attempts at overtaking the Lich King and completely freeing the Scourge.' WHERE `word_id` = 140651; -- locales_quest - offerrewardtext : entry=5725
UPDATE `trans_words` SET `content_loc11`='Good, $C. You\'ve done well. I\'ll keep these safe from prying eyes; the last thing we need is a strong Shadow Council rising up again.$B$BCheck back with me in the future; there\'s always something that needs doing around here, apparently, and I might need another able body.' WHERE `word_id` = 164916; -- locales_quest - offerrewardtext : entry=14356
UPDATE `trans_words` SET `content_loc11`='Good, $N! The spirits be praised, perhaps you are the one who will finally put my greatest fears to rest! Who would suspect someone so young and so brave would rise up and champion our cause? You remind me of myself when I was younger. I will ensure that you are justly rewarded for your efforts if we both survive the coming storm.$B$BBut there is time for more praise later. You\'ve not accomplished anything in comparison to what you will face... but this is a good start.' WHERE `word_id` = 334684; -- locales_quest - offerrewardtext : entry=5726
UPDATE `trans_words` SET `content_loc11`='Good, $N! With their numbers weakened, we can soon begin our assault on their forces deep within Shadow Hold.' WHERE `word_id` = 186961; -- locales_quest - offerrewardtext : entry=28121
UPDATE `trans_words` SET `content_loc11`='Good, $N! With their numbers weakening, we can further press them.$B$BHow was your first taste of their power? Were they as strong as you thought they would be? Stronger? Or perhaps they were no challenge for you at all. Wouldn\'t that be something?$B$BWe can discuss the details of your exploits later. There are other things we must focus on now.' WHERE `word_id` = 139951; -- locales_quest - offerrewardtext : entry=5155
UPDATE `trans_words` SET `content_loc11`='Good, $N. Your return here signifies that you are indeed prepared for the next step.$B$BOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. The Earth Mother will protect you, but only if you show her proper respect. She is the basis for life, and by observing her laws, you will gain a greater wisdom. Never forget the secrets she shares with you.$B$BI shall make your sapta for you now, and by accepting it, a new path will open before you.' WHERE `word_id` = 135888; -- locales_quest - offerrewardtext : entry=1519
UPDATE `trans_words` SET `content_loc11`='Good, $R, you\'re here. We\'ll have to act fast if we\'re to prevent Therazane\'s forces from attacking.' WHERE `word_id` = 186280; -- locales_quest - offerrewardtext : entry=27931
UPDATE `trans_words` SET `content_loc11`='Good, good! You handled that very well! Let\'s see if you\'re up to something a little more difficult now.' WHERE `word_id` = 146575; -- locales_quest - offerrewardtext : entry=9276
UPDATE `trans_words` SET `content_loc11`='Good, good. I like nothing more than to see the works of our enemy destroyed.' WHERE `word_id` = 177895; -- locales_quest - offerrewardtext : entry=25575
UPDATE `trans_words` SET `content_loc11`='Good, good. It\'ll take them many sleepless nights to figure out where we came from and where we disappeared to after the kills...' WHERE `word_id` = 176993; -- locales_quest - offerrewardtext : entry=25284
UPDATE `trans_words` SET `content_loc11`='Good, good. Just put them over there, I\'ve got my hands full.' WHERE `word_id` = 180925; -- locales_quest - offerrewardtext : entry=26382
UPDATE `trans_words` SET `content_loc11`='Good, good. Let them reap what they sow!' WHERE `word_id` = 185097; -- locales_quest - offerrewardtext : entry=27611
UPDATE `trans_words` SET `content_loc11`='Good, good. Let\'s hope the ogres are at least smart enough to realize we\'re sending a message!' WHERE `word_id` = 177259; -- locales_quest - offerrewardtext : entry=25375
UPDATE `trans_words` SET `content_loc11`='Good, good. Maybe they\'ll think twice before slacking next time!  Thanks for the help!' WHERE `word_id` = 167846; -- locales_quest - offerrewardtext : entry=25134
UPDATE `trans_words` SET `content_loc11`='Good, good. Now we can see what\'s going on down in that mine.' WHERE `word_id` = 182532; -- locales_quest - offerrewardtext : entry=26844
UPDATE `trans_words` SET `content_loc11`='Good, good. One less nuisance to worry about.' WHERE `word_id` = 173433; -- locales_quest - offerrewardtext : entry=14161
UPDATE `trans_words` SET `content_loc11`='Good, good. These barracks are as good as fallen.' WHERE `word_id` = 185129; -- locales_quest - offerrewardtext : entry=27619
UPDATE `trans_words` SET `content_loc11`='Good, good. We\'ve got to keep Honor\'s Stand isolated.$B$BAlone ... afraid ... $N, if we keep up the pressure, maybe someday they\'ll simply surrender the pass.' WHERE `word_id` = 174858; -- locales_quest - offerrewardtext : entry=24519
UPDATE `trans_words` SET `content_loc11`='Good, good.$B$BIf there are no other delays, how about we get started?' WHERE `word_id` = 133117; -- locales_quest - offerrewardtext : entry=695
UPDATE `trans_words` SET `content_loc11`='Good, I see Ageron managed to find you, $N. Let us waste little time with small talk and pleasantries and focus on your training. There is still much you have to learn.' WHERE `word_id` = 135754; -- locales_quest - offerrewardtext : entry=1478
UPDATE `trans_words` SET `content_loc11`='Good, that\'s a start. The birds who laid these eggs will never accept them again, so we\'ll have to raise these birds as orphans in the shrine here. Were Aviana here, she never would\'ve let this travesty happen. But, on to business...' WHERE `word_id` = 178191; -- locales_quest - offerrewardtext : entry=25656
UPDATE `trans_words` SET `content_loc11`='Good, the abbey is ours. I never doubted Eligor\'s ability for a moment.' WHERE `word_id` = 185122; -- locales_quest - offerrewardtext : entry=27617
UPDATE `trans_words` SET `content_loc11`='Good, then Kor\'ja lives and goes off to defend our town from those malicious humans. I often wish to remember days of battle; where power was shown in combat and it was the wise who often destroyed those who relied on just their strength.$B$BYou done good by me, $N. You take this robe now. Maybe it help, maybe you not care, but you earned it and I\'m proud to call you brother.' WHERE `word_id` = 140579; -- locales_quest - offerrewardtext : entry=5648
UPDATE `trans_words` SET `content_loc11`='Good, then we shall begin.$B$BThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.$B$BSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.$B$BAgain, do not come back until you have done both things I\'ve asked.' WHERE `word_id` = 136291; -- locales_quest - details : entry=1799
UPDATE `trans_words` SET `content_loc11`='Good, these should do. Now, to create a kit to pass you off as a convincing iron dwarf.' WHERE `word_id` = 158899; -- locales_quest - offerrewardtext : entry=12184
UPDATE `trans_words` SET `content_loc11`='Good, we\'re making progress. That puts us one step closer to shutting down this facility and returning safely to Shadowmoon Village.' WHERE `word_id` = 151664; -- locales_quest - offerrewardtext : entry=10602
UPDATE `trans_words` SET `content_loc11`='Good, you finally made it back! Okay, what did you figure out? Who are they?' WHERE `word_id` = 149420; -- locales_quest - offerrewardtext : entry=10040
UPDATE `trans_words` SET `content_loc11`='Good, you got the rot blossoms. And I\'ll tell Althea Ebonlocke of the Night Watch that you were killing skeletons.$B$BKeeping the people of Darkshire safe is a grim burden for the Night Watch, and news that others are helping stem the tide of fiends in Duskwood is welcome news indeed.' WHERE `word_id` = 130794; -- locales_quest - offerrewardtext : entry=156
UPDATE `trans_words` SET `content_loc11`='Good, you got the rot blossoms. I\'ll whip up the zombie juice... it\'s strong stuff, I warn you.' WHERE `word_id` = 181885; -- locales_quest - offerrewardtext : entry=26661
UPDATE `trans_words` SET `content_loc11`='Good, you have come. My task is not an easy one, but vital to the society of mages. If you aid me, I am sure you will find it worthwhile.' WHERE `word_id` = 136482; -- locales_quest - offerrewardtext : entry=1943
UPDATE `trans_words` SET `content_loc11`='Good, you have gathered the essential amount of Incendia agave. This rare herb found only in Thousand Needles will help light the dormant sacred fire of life.$B$B<Magatha begins to enchant the Incendia agave.>' WHERE `word_id` = 139762; -- locales_quest - offerrewardtext : entry=5062
UPDATE `trans_words` SET `content_loc11`='Good, you here already. Stick around for a bit, little $R. We gonna mess with the Alliance. I love my job, mon.' WHERE `word_id` = 178297; -- locales_quest - offerrewardtext : entry=25679
UPDATE `trans_words` SET `content_loc11`='Good, you\'re back. I hope you\'ve still got that disguise. You\'re going back undercover, $N.' WHERE `word_id` = 187819; -- locales_quest - offerrewardtext : entry=28326
UPDATE `trans_words` SET `content_loc11`='Good, you\'re back. It\'s about time. We know where Cho\'gall\'s ultimate weapon is located!' WHERE `word_id` = 185759; -- locales_quest - offerrewardtext : entry=27783
UPDATE `trans_words` SET `content_loc11`='Good, you\'re back. We know where Cho\'gall\'s ultimate weapon is located!' WHERE `word_id` = 185755; -- locales_quest - offerrewardtext : entry=27782
UPDATE `trans_words` SET `content_loc11`='Good, you\'re here. Let\'s get started.' WHERE `word_id` = 183980; -- locales_quest - offerrewardtext : entry=27278
UPDATE `trans_words` SET `content_loc11`='Good, you\'re here. Welcome to Azshara, the stage for the next act of the Horde\'s glorious future. Now get to work.' WHERE `word_id` = 178157; -- locales_quest - offerrewardtext : entry=25648
UPDATE `trans_words` SET `content_loc11`='Good, you\'ve returned, $N. And where is the thread?$B$BAh, I understand. That is acceptable. The goblin and his brother have not failed us yet--I suppose it is understandable that he did not have it prepared right then. So be it... we have other things we can attend to in the meantime.$B$BAre you prepared for the next step?' WHERE `word_id` = 139417; -- locales_quest - offerrewardtext : entry=4782
UPDATE `trans_words` SET `content_loc11`='Good, you\'ve returned, and not a moment too late. We have great things to discuss, $N. Your abilities are growing stronger, and we must make sure you are ready.' WHERE `word_id` = 140574; -- locales_quest - offerrewardtext : entry=5646
UPDATE `trans_words` SET `content_loc11`='Good. $N, I know of you. You\'ll be perfect for these tasks.$B$BWe\'ve been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we\'re to avoid Arthas\' notice.' WHERE `word_id` = 165003; -- locales_quest - offerrewardtext : entry=24506
UPDATE `trans_words` SET `content_loc11`='Good. Fewer Alliance pests to stand in our way. We\'ll show them what true warriors look like.' WHERE `word_id` = 163488; -- locales_quest - offerrewardtext : entry=13313
UPDATE `trans_words` SET `content_loc11`='Good. Go with Agamaggan\'s spirit as your guide, $R. Return to me if you desire more of Agamaggan\'s magics.' WHERE `word_id` = 133890; -- locales_quest - offerrewardtext : entry=889
UPDATE `trans_words` SET `content_loc11`='Good. Good! They will all die!  Their chieftains, and their women, and their children, and their foul pets!' WHERE `word_id` = 175058; -- locales_quest - offerrewardtext : entry=24608
UPDATE `trans_words` SET `content_loc11`='Good. Hiding within these collars is the secret behind the Burning Blade. And I will uncover that secret...' WHERE `word_id` = 166514; -- locales_quest - offerrewardtext : entry=25262
UPDATE `trans_words` SET `content_loc11`='Good. I can hear the loud Magram bellies grumble from their village, far away!$B$BI will give this meat to the Gelkis. And we will fight for many days without rest.$B$BWhat you did is good for the Gelkis, $N.' WHERE `word_id` = 135430; -- locales_quest - offerrewardtext : entry=1370
UPDATE `trans_words` SET `content_loc11`='Good. I can use all the help you can offer. My first priority is to get that lamp re-lit.' WHERE `word_id` = 153986; -- locales_quest - offerrewardtext : entry=11191
UPDATE `trans_words` SET `content_loc11`='Good. I hope you inflicted some other losses on the Burning Blade when you went to retrieve this.$B$BThey have been a source of great annoyance for the Warchief, and a great blight upon warlocks as a whole.' WHERE `word_id` = 135821; -- locales_quest - offerrewardtext : entry=1501
UPDATE `trans_words` SET `content_loc11`='Good. I know this probably wasn\'t very pleasant work, but we greatly appreciate it. I fear for our dear Teldrassil... it seems it is becoming more corrupt by the day, and our ignorance to the cause is plaguing me greatly.' WHERE `word_id` = 172882; -- locales_quest - offerrewardtext : entry=13946
UPDATE `trans_words` SET `content_loc11`='Good. I was afraid Ophek wouldn\'t reach you.$B$BIt is time that I further your warlock training. Any business you have currently will have to wait.$B$BI trust there will not be a problem with this?' WHERE `word_id` = 135842; -- locales_quest - offerrewardtext : entry=1506
UPDATE `trans_words` SET `content_loc11`='Good. I\'ll see if I can fashion something useful from these tails.$B$BNo doubt that the Horde will find a way to replenish the numbers of their wolf pack, but for now we can breathe a little easier.$B$B$N, if you are willing there\'s something else that I would ask of you in defense of Sylvanaar and the Living Grove.' WHERE `word_id` = 151123; -- locales_quest - offerrewardtext : entry=10456
UPDATE `trans_words` SET `content_loc11`='Good. It is just as Jaron described it.' WHERE `word_id` = 189369; -- locales_quest - offerrewardtext : entry=28838
UPDATE `trans_words` SET `content_loc11`='Good. Murgut sold his own tribe out to the Horde, allying with them when they took your precious Silverwind Refuge in order to \'save\' his people. He sold them into slavery, or worse. And now he has gotten what he deserved! Let us speak now of a different traitor, one whom I believe has something that will make that rod of yours even more powerful.' WHERE `word_id` = 173024; -- locales_quest - offerrewardtext : entry=13989
UPDATE `trans_words` SET `content_loc11`='Good. Now there\'s only one thing left to do.' WHERE `word_id` = 187042; -- locales_quest - offerrewardtext : entry=28139
UPDATE `trans_words` SET `content_loc11`='Good. Now we practice.' WHERE `word_id` = 176505; -- locales_quest - offerrewardtext : entry=25149
UPDATE `trans_words` SET `content_loc11`='Good. Now, we must act swiftly, before the sons of iron realize that their runes have been rendered harmless.' WHERE `word_id` = 158499; -- locales_quest - offerrewardtext : entry=12093
UPDATE `trans_words` SET `content_loc11`='Good. Our enemies now know that our strength is to be feared.' WHERE `word_id` = 189946; -- locales_quest - offerrewardtext : entry=29142
UPDATE `trans_words` SET `content_loc11`='Good. Take your reward; this is only a prelude.' WHERE `word_id` = 175041; -- locales_quest - offerrewardtext : entry=24603
UPDATE `trans_words` SET `content_loc11`='Good. Their blood is on Hellscream\'s hands. Send enough of them back to Orgrimmar in a body bag and the populace of the Horde might react. Who am I kidding? They\'re monsters!' WHERE `word_id` = 178261; -- locales_quest - offerrewardtext : entry=25671
UPDATE `trans_words` SET `content_loc11`='Good. There is more to be done.' WHERE `word_id` = 159265; -- locales_quest - offerrewardtext : entry=12265
UPDATE `trans_words` SET `content_loc11`='Good. These will do just fine.$B$BI will have the potion ready for you in no time at all.' WHERE `word_id` = 159553; -- locales_quest - offerrewardtext : entry=12328
UPDATE `trans_words` SET `content_loc11`='Good. Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against all of the enemies of Ashenvale.' WHERE `word_id` = 181155; -- locales_quest - offerrewardtext : entry=26446
UPDATE `trans_words` SET `content_loc11`='Good. Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against the demons at Felfire Hill.$B$BGo in peace, little $Gbrother:sister;.' WHERE `word_id` = 147344; -- locales_quest - offerrewardtext : entry=9526
UPDATE `trans_words` SET `content_loc11`='Good. We march on.' WHERE `word_id` = 191510; -- locales_quest - offerrewardtext : entry=30099
UPDATE `trans_words` SET `content_loc11`='Good. We\'ll need all the help we can get. Olakin here is the Argent Crusade\'s contribution to our effort. Let\'s cut the chatter and get down to the business of denying the Scourge their armies of the flesh.' WHERE `word_id` = 162577; -- locales_quest - offerrewardtext : entry=13106
UPDATE `trans_words` SET `content_loc11`='Good. Well done, $C.$B$BNow that Malcin is dead, we can at least know that the Scourges advances will be halted. The Dark Lady thanks you for your efforts and wishes to reward you with a gift.$B$BAlthough we do not know the extent of the Scourges influence within the Downs, I am sure we will discover their plots soon enough.' WHERE `word_id` = 141384; -- locales_quest - offerrewardtext : entry=6521
UPDATE `trans_words` SET `content_loc11`='Good... good... these should do fine. The shrapnel bombs are almost finished. $B$BWait... what happened to my ice shards?  Narf told me shards from those elementals should be enchanted, but they\'re melting just like the one\'s hanging from Narf\'s grumpy chin!' WHERE `word_id` = 158288; -- locales_quest - offerrewardtext : entry=12046
UPDATE `trans_words` SET `content_loc11`='Gor\'drek has asked you to slay 12 Bladewing Bloodletters. Return to him at Thunderlord Stronghold in the Blade\'s Edge Mountains once you have accomplished that.' WHERE `word_id` = 151223; -- locales_quest - objectives : entry=10486
UPDATE `trans_words` SET `content_loc11`='Gor\'drek wants you to gather 4 Dusts of the Fey Drake. After doing so, return to him at Thunderlord Stronghold in the Blade\'s Edge Mountains.' WHERE `word_id` = 151228; -- locales_quest - objectives : entry=10487
UPDATE `trans_words` SET `content_loc11`='Gor\'tesh Head Planted' WHERE `word_id` = 138518; -- locales_quest - ObjectiveText1 : entry=3825
UPDATE `trans_words` SET `content_loc11`='Gordawg at the Throne of the Elements in Nagrand has asked that you bring him 15 Enraged Crusher Cores.' WHERE `word_id` = 148524; -- locales_quest - objectives : entry=9821
UPDATE `trans_words` SET `content_loc11`='Gordawg at the Throne of the Elements in Nagrand has asked that you destroy 15 Tortured Earth Spirits.' WHERE `word_id` = 148514; -- locales_quest - objectives : entry=9819
UPDATE `trans_words` SET `content_loc11`='Gordok Ogre Mage Captured' WHERE `word_id` = 177174; -- locales_quest - ObjectiveText1 : entry=25344
UPDATE `trans_words` SET `content_loc11`='Gordok Ogre-Mage Captured' WHERE `word_id` = 177354; -- locales_quest - ObjectiveText1 : entry=25403
UPDATE `trans_words` SET `content_loc11`='Gordul told me that you would be bringing a variety of unusual materials, but I didn\'t expect anything like this. Moonsteel is said to be very rare and there\'s only one place I know to get it. You have risked much for this weapon, $N, and I\'ll see to it that you receive a fitting reward.' WHERE `word_id` = 184352; -- locales_quest - offerrewardtext : entry=27396
UPDATE `trans_words` SET `content_loc11`='Gordunni Ogre Slain' WHERE `word_id` = 176751; -- locales_quest - ObjectiveText1 : entry=25209
UPDATE `trans_words` SET `content_loc11`='Gordunni Ogre' WHERE `word_id` = 76518; -- locales_quest - ObjectiveText1 : entry=11096
UPDATE `trans_words` SET `content_loc11`='Gorefiend? T... Teron Gorefiend? But... How?$B$BHow could Gorefiend be here? This is impossible!$B$BThe legend of Teron Gorefiend is one that causes even the Forsaken to tremble in fear. By all accounts, Gorefiend was a warlock of Gul\'dan' WHERE `word_id` = 151758; -- locales_quest - offerrewardtext : entry=10625
UPDATE `trans_words` SET `content_loc11`='Gorefiend? Why, I have not heard that name in ages!$B$BAfter the Second War, Gorefiend returned here, along with his death knights. Unable to cope with the terrible nature of his new form and without the support of his beloved leader, Gul\'dan, Gorefiend killed himself.$B$BIf he walks these lands now as a spirit, it is news to me. Yet, perhaps I can divine such knowledge with your assistance.' WHERE `word_id` = 276319; -- locales_quest - offerrewardtext : entry=10633
UPDATE `trans_words` SET `content_loc11`='Goregek show silly $R slave how it done.' WHERE `word_id` = 160067; -- locales_quest - offerrewardtext : entry=12529
UPDATE `trans_words` SET `content_loc11`='Goregek take you to kill big mom of hardknuckles, eh? You lucky!$B$BDumb softknuckles squeal good!$B$B<Rakjak squeals loudly and breaks out laughing.>' WHERE `word_id` = 160072; -- locales_quest - offerrewardtext : entry=12530
UPDATE `trans_words` SET `content_loc11`='Gorka accompanied to Mor\'shan Ramparts' WHERE `word_id` = 172461; -- locales_quest - ObjectiveText1 : entry=13653
UPDATE `trans_words` SET `content_loc11`='Gorka... We must always be prepared for losses. Her honorable service to the Horde will not be forgotten. And her sacrifice shall not be in vain!' WHERE `word_id` = 172460; -- locales_quest - offerrewardtext : entry=13653
UPDATE `trans_words` SET `content_loc11`='Gorka\'s death was not in vain, $N. Splintertree would have certainly fallen if we hadn\'t come when we did. Now we must get to work shoring up her defenses. This isn\'t over....' WHERE `word_id` = 172497; -- locales_quest - offerrewardtext : entry=13712
UPDATE `trans_words` SET `content_loc11`='Gorkan said good things about you. They\'re all turning out to be true.$B$BThanks for your help.' WHERE `word_id` = 147021; -- locales_quest - offerrewardtext : entry=9442
UPDATE `trans_words` SET `content_loc11`='Gormungan Scared' WHERE `word_id` = 174198; -- locales_quest - ObjectiveText1 : entry=14388
UPDATE `trans_words` SET `content_loc11`='Gorsik has arrived. All of the pieces of the World Pillar are here, thanks to you. What you have done for us is immeasurable. These final moments shall be the most crucial. I hesitate to ask more of you, but I\'d like you to stay with us and see this through. The Twilight\'s Hammer was devastated by your attacks, but not destroyed. It\'s no stretch to assume they will try to stop us from completing our ritual.' WHERE `word_id` = 182488; -- locales_quest - offerrewardtext : entry=26833
UPDATE `trans_words` SET `content_loc11`='Gory defeated' WHERE `word_id` = 183730; -- locales_quest - ObjectiveText1 : entry=27174
UPDATE `trans_words` SET `content_loc11`='Got some time to spare?  Kill me some Murlocs and I\'ll give you something shiny!' WHERE `word_id` = 170565; -- locales_quest - details : entry=8274
UPDATE `trans_words` SET `content_loc11`='Grab a Crate with Holes.$BGrab a Snufflenose Command Stick.$BGrab and read the Snufflenose Owner\'s Manual.$B$BIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.$B$BBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.' WHERE `word_id` = 135179; -- locales_quest - objectives : entry=1221
UPDATE `trans_words` SET `content_loc11`='Grab a Flawed Power Stone. Bring it to the Altar of Fire before the stone expires, then return to Ak\'Zeloth.' WHERE `word_id` = 134039; -- locales_quest - objectives : entry=924
UPDATE `trans_words` SET `content_loc11`='Grah... very well. I\'ll remove the bounty I had placed upon your head. Though I am sorely tempted to end your life anyway, just on principle. Be sure that you never raise my ire again, $N. Now, get out of my sight...' WHERE `word_id` = 172583; -- locales_quest - offerrewardtext : entry=13842
UPDATE `trans_words` SET `content_loc11`='Grand Admiral Westwind dealt with' WHERE `word_id` = 161505; -- locales_quest - ObjectiveText1 : entry=12852
UPDATE `trans_words` SET `content_loc11`='Grand Apothecary Putress wants you to give the Dual-plagued Brain to Apothecary Chaney in Thunder Bluff.' WHERE `word_id` = 161216; -- locales_quest - objectives : entry=12786
UPDATE `trans_words` SET `content_loc11`='Grand Magus Doane confronted' WHERE `word_id` = 182004; -- locales_quest - ObjectiveText1 : entry=26694
UPDATE `trans_words` SET `content_loc11`='Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.' WHERE `word_id` = 133087; -- locales_quest - objectives : entry=689
UPDATE `trans_words` SET `content_loc11`='Grandma Wahl at the Wahl cottage wants you to retrieve Chance the Cat.' WHERE `word_id` = 177137; -- locales_quest - objectives : entry=25331
UPDATE `trans_words` SET `content_loc11`='Grasses and shrubs cover an unnatural bulge in the earth.$B$BA few minutes spent digging reveals an old box, almost certainly the one mentioned in Nolkai\'s journal.' WHERE `word_id` = 147483; -- locales_quest - offerrewardtext : entry=9561
UPDATE `trans_words` SET `content_loc11`='Graveyard Assaulted' WHERE `word_id` = 141849; -- locales_quest - ObjectiveText1 : entry=7081
UPDATE `trans_words` SET `content_loc11`='Grazle wants you to prove yourself by killing 5 Deadwood Warriors, 5 Deadwood Pathfinders, and 5 Deadwood Gardeners.' WHERE `word_id` = 145792; -- locales_quest - objectives : entry=6131
UPDATE `trans_words` SET `content_loc11`='Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done.' WHERE `word_id` = 143568; -- locales_quest - objectives : entry=8460
UPDATE `trans_words` SET `content_loc11`='Great job! That should drastically cut down on the number of demons trying to creep up our backsides. I can\'t thank you enough for your help out here, $N.' WHERE `word_id` = 150875; -- locales_quest - offerrewardtext : entry=10397
UPDATE `trans_words` SET `content_loc11`='Great job, $N!  Thanks a lot!  I\'m going to make paint from this blood and turn all kinds of cheap junk into glowing treasure!$B$BHere are your tickets, and thanks again!' WHERE `word_id` = 143036; -- locales_quest - offerrewardtext : entry=8222
UPDATE `trans_words` SET `content_loc11`='Great job, $N! I hereby proclaim you an honorary Longbeard.$B$BStick around and have a drink with us, won\'t you?' WHERE `word_id` = 146911; -- locales_quest - offerrewardtext : entry=9417
UPDATE `trans_words` SET `content_loc11`='Great job, $N. Let\'s show the Wretched what we\'re made of!' WHERE `word_id` = 146039; -- locales_quest - offerrewardtext : entry=8480
UPDATE `trans_words` SET `content_loc11`='Great job, $N. Say, you wouldn\'t be looking for something more... permanent, would ya? I could sure use some help around these parts!' WHERE `word_id` = 156305; -- locales_quest - offerrewardtext : entry=11310
UPDATE `trans_words` SET `content_loc11`='Great job, $N. We\'ve heard rumors of survivors further in the mountains. Now we\'ll be able to send scouts there.' WHERE `word_id` = 174808; -- locales_quest - offerrewardtext : entry=24501
UPDATE `trans_words` SET `content_loc11`='Great job, but that\'s not even half of the hostages that they took from town. Darn it all! They must have taken the rest of the captives to their other villages up in the volcano!' WHERE `word_id` = 175646; -- locales_quest - offerrewardtext : entry=24925
UPDATE `trans_words` SET `content_loc11`='Great job, Champion. The fight continues, but now the Kvaldir know that we do not tolerate such attacks.' WHERE `word_id` = 164767; -- locales_quest - offerrewardtext : entry=14136
UPDATE `trans_words` SET `content_loc11`='Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don\'t think being ready would have helped my cause much. One swipe and poof! Darkness. They say I\'m lucky to walk now...$B$BWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $N, if you\'d like to try yourself against her, the Lady of the Loch,' WHERE `word_id` = 171293; -- locales_quest - details : entry=352
UPDATE `trans_words` SET `content_loc11`='Great news, $N. I\'ve sent the remaining militia to the shore to meet the Forsaken force head on.' WHERE `word_id` = 174105; -- locales_quest - offerrewardtext : entry=14366
UPDATE `trans_words` SET `content_loc11`='Great Spirit Totem! This is dire news indeed. I must begin to plan for whatever may come.$B$B$N, as promised, here is your reward for your brave service.' WHERE `word_id` = 139771; -- locales_quest - offerrewardtext : entry=5064
UPDATE `trans_words` SET `content_loc11`='Great to see you again! Thank you for finding Azuregos and sending him to me. I do feel I owe you an apology - I may have undersold how difficult it would be to accomplish the task I gave you. You performed quite admirably, $N.' WHERE `word_id` = 174212; -- locales_quest - offerrewardtext : entry=14391
UPDATE `trans_words` SET `content_loc11`='Great work $N, I knew you weren\'t useless. Here - have one of the better items I\'ve found out of the lots that have been collected so far.' WHERE `word_id` = 138575; -- locales_quest - offerrewardtext : entry=3902
UPDATE `trans_words` SET `content_loc11`='Great work $N. I knew you weren\'t useless. Here, take one of these. We deathguards have piles of these things just sitting around.' WHERE `word_id` = 182370; -- locales_quest - offerrewardtext : entry=26800
UPDATE `trans_words` SET `content_loc11`='Great work $N. I will report your efforts to our highest in command immediately.' WHERE `word_id` = 186452; -- locales_quest - offerrewardtext : entry=27975
UPDATE `trans_words` SET `content_loc11`='Great work on those supply ships, $N!  We knew you would be good for somethin\' around here.' WHERE `word_id` = 187618; -- locales_quest - offerrewardtext : entry=28275
UPDATE `trans_words` SET `content_loc11`='Great work! There was a time when adventurers would collect these cores in order to craft mediocre fire-resistant equipment. But for now, I\'m glad just to destroy these fiends once and for all.' WHERE `word_id` = 177904; -- locales_quest - offerrewardtext : entry=25577
UPDATE `trans_words` SET `content_loc11`='Great work! We\'ve knocked them on their heels, maybe long enough to shore up our defenses. Provided we find a way to take out their artillery...' WHERE `word_id` = 175724; -- locales_quest - offerrewardtext : entry=24943
UPDATE `trans_words` SET `content_loc11`='Great work, $C. Looks like we\'ll be keepin\' Budd around a little longer.$B$BWe\'ll have your cage picked up right away. Here\'s your share of the bounty.$B$BOh, and welcome to the camp. Stick around and I\'m sure we\'ll find a use for ya....' WHERE `word_id` = 158049; -- locales_quest - offerrewardtext : entry=11984
UPDATE `trans_words` SET `content_loc11`='Great work, $Gbuddy:lassy;! Now where\'d I put that pneumatic tank transjigamarig.' WHERE `word_id` = 157187; -- locales_quest - offerrewardtext : entry=11644
UPDATE `trans_words` SET `content_loc11`='Great work, $Gbuddy:lassy;! Now where\'d I put those spare parts...' WHERE `word_id` = 157182; -- locales_quest - offerrewardtext : entry=11643
UPDATE `trans_words` SET `content_loc11`='Great work, $N!  We should not hear from the ghosts again anytime soon.' WHERE `word_id` = 186462; -- locales_quest - offerrewardtext : entry=27978
UPDATE `trans_words` SET `content_loc11`='Great work, $N! People will come running to buy Crown perfumes now that they\'ve had a chance to sample their wonders. Here\'s a little something for helping us out.' WHERE `word_id` = 275257; -- locales_quest - offerrewardtext : entry=24629
UPDATE `trans_words` SET `content_loc11`='Great work, $N! That\'s how we took care of business back on Kezan.' WHERE `word_id` = 173396; -- locales_quest - offerrewardtext : entry=14135
UPDATE `trans_words` SET `content_loc11`='Great work, $N. Please accept this on behalf of the Cenarion Circle. You\'ve certainly earned it, friend!' WHERE `word_id` = 143850; -- locales_quest - offerrewardtext : entry=8548
UPDATE `trans_words` SET `content_loc11`='Great work, $N. These supplies will help the bridge effort immensely. We\'ll get this beauty shored up in no time.' WHERE `word_id` = 130499; -- locales_quest - offerrewardtext : entry=89
UPDATE `trans_words` SET `content_loc11`='Great work, $N. We need to move quickly before they send for reinforcements.' WHERE `word_id` = 181805; -- locales_quest - offerrewardtext : entry=26638
UPDATE `trans_words` SET `content_loc11`='Great work, $N. While you were out, I heard other gunners talking about you... I think you have a real future in air offense!' WHERE `word_id` = 163719; -- locales_quest - offerrewardtext : entry=13376
UPDATE `trans_words` SET `content_loc11`='Great!  These look... disgusting. But probably pretty valuable. Let\'s get to splitting these up. Some for me, some for Jasper, some for Chabal...' WHERE `word_id` = 181247; -- locales_quest - offerrewardtext : entry=26493
UPDATE `trans_words` SET `content_loc11`='Great!  Wonderful!  I can get a bundle for these!! That Venture Company sure picked the wrong jungle to mine in, didn\'t they?  We\'d all be in better shape if they moved out of here.' WHERE `word_id` = 181006; -- locales_quest - offerrewardtext : entry=26403
UPDATE `trans_words` SET `content_loc11`='Great!  You got the eyes!  I hope hunting those bats was frightening for you, because if it scared a brave $C like yourself, then those eyes will certainly scare our Faire visitors.$B$BTake these tickets, $N, and thank you for your service.' WHERE `word_id` = 142655; -- locales_quest - offerrewardtext : entry=7903
UPDATE `trans_words` SET `content_loc11`='Great! I can get a good price for these, especially for what\'s inside Maury\'s foot! Thanks much, $N!$B$BI hope those three learned their lesson: don\'t bet something you can\'t afford to lose.$B$BAnd maybe it\'s too late for them, but...they should be careful of who they gamble with.' WHERE `word_id` = 132762; -- locales_quest - offerrewardtext : entry=26595
UPDATE `trans_words` SET `content_loc11`='Great! I can get the crew working on this right away. Thanks, $N!' WHERE `word_id` = 135043; -- locales_quest - offerrewardtext : entry=1176
UPDATE `trans_words` SET `content_loc11`='Great! I can\'t wait to use these in some of my recipes. There\'s one in particular I think it\'ll work great in...' WHERE `word_id` = 131479; -- locales_quest - offerrewardtext : entry=315
UPDATE `trans_words` SET `content_loc11`='Great! Set the keg down right here. I\'ll measure out some charges once I\'ve donned my full-body protective gear.' WHERE `word_id` = 176266; -- locales_quest - offerrewardtext : entry=25079
UPDATE `trans_words` SET `content_loc11`='Great! Thanks to your help I\'ll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!$B$BFor all your hard work, here, I made some extras, so take a pair. It\'s on Drizzlik.$B$BAnd remember, there\'s no boot so fine as one of Drizzlik\'s Excelsior line!' WHERE `word_id` = 132831; -- locales_quest - offerrewardtext : entry=26345
UPDATE `trans_words` SET `content_loc11`='Great! These will work great! They\'re not too heavy, but not too light either. They\'re perfect for building muscle mass!$B$BThanks much, $N. Here\'s your Darkmoon Faire ticket!' WHERE `word_id` = 142621; -- locales_quest - offerrewardtext : entry=7889
UPDATE `trans_words` SET `content_loc11`='Great! This will work great! I just noticed a rip in a tent over yonder, and one of these armor kits is just what I need to patch it up!$B$BThank you very much, $N. These armor kits will save us a ton in repair costs. Here are your tickets - you deserve them!' WHERE `word_id` = 142615; -- locales_quest - offerrewardtext : entry=7885
UPDATE `trans_words` SET `content_loc11`='Great! Without a steady flow of their weapons, we\'ll win through attrition!' WHERE `word_id` = 183879; -- locales_quest - offerrewardtext : entry=27230
UPDATE `trans_words` SET `content_loc11`='Great! Wonderful! I can get a bundle for these!!$B$BThat Venture Company sure picked the wrong jungle to mine in, didn\'t they? We\'d all be in better shape if they moved out of here.$B$BThank you, $N. You\'ve done a good deed this day.' WHERE `word_id` = 132720; -- locales_quest - offerrewardtext : entry=600
UPDATE `trans_words` SET `content_loc11`='Great! You\'ve loaded the shredder to capacity. You\'re getting pretty handy with that thing...' WHERE `word_id` = 173391; -- locales_quest - offerrewardtext : entry=14134
UPDATE `trans_words` SET `content_loc11`='Great, just what I needed... more bones.$B$B<Ramdor sighs.>$B$BYes, yes, I will see to it that these remains of our honored ancestors are given a proper burial, have no fear.$B$BThere is something else that you can do if you\'re truly interested in aiding the dead.' WHERE `word_id` = 149379; -- locales_quest - offerrewardtext : entry=10030
UPDATE `trans_words` SET `content_loc11`='Great, mon! Let\'s try it out...' WHERE `word_id` = 143494; -- locales_quest - offerrewardtext : entry=8412
UPDATE `trans_words` SET `content_loc11`='Great, more ammo! Old Loslor\'s shipment finally came through! The ammo might be late, but just like my grand daddy used to tell me: late\'s better than never!$B$BThank you much, $N. I already have buyers eager for this stuff!' WHERE `word_id` = 140472; -- locales_quest - offerrewardtext : entry=5541
UPDATE `trans_words` SET `content_loc11`='Great, my package from Koalbeard! Thank you $N. This crate holds special-gauge ammunition, and it\'ll serve us well out in the jungle!$B$BHere\'s your pay, and tell me, how is crusty old Kravel these days? Still up to no good I\'d wager...' WHERE `word_id` = 140689; -- locales_quest - offerrewardtext : entry=5762
UPDATE `trans_words` SET `content_loc11`='Great, thanks for the shipment! Now MacKinley and I can finally settle our wager.' WHERE `word_id` = 137353; -- locales_quest - offerrewardtext : entry=2873
UPDATE `trans_words` SET `content_loc11`='Great, you brought the armor!  We\'ll get this divvied to those who need it immediately. Thank you, $N. Your efforts have been a great help to us. And now that you\'re no stranger to gryphons, I hope you\'ll come and lend your aid to Goldshire often!' WHERE `word_id` = 180977; -- locales_quest - offerrewardtext : entry=26396
UPDATE `trans_words` SET `content_loc11`='Great, you brought the armor! We\'ll get this divvied to those who need it immediately.$B$BThank you, $N. Your efforts have been a great help to us. And now that you\'re no stranger to gryphons, I hope you\'ll come and lend your aid to Sentinel Hill often!' WHERE `word_id` = 141180; -- locales_quest - offerrewardtext : entry=6285
UPDATE `trans_words` SET `content_loc11`='Great, you found it! I feared it was gone forever, used by the Defias to impersonate a Stormwind official. Well that won\'t happen now, thanks to you.$B$BHere are some weapons I used when I was a Marshal. I kept them in great shape--take your pick!' WHERE `word_id` = 136078; -- locales_quest - offerrewardtext : entry=1667
UPDATE `trans_words` SET `content_loc11`='Great, you got him!  And I hope you taught his gang a lesson too!' WHERE `word_id` = 155135; -- locales_quest - offerrewardtext : entry=27432
UPDATE `trans_words` SET `content_loc11`='Great, you got it! I can\'t wait to try it out. This is going to make me a fortune, I just know it!$B$BThank you, $N. Take this, and after I\'m rich I\'ll send you more, I promise!' WHERE `word_id` = 135806; -- locales_quest - offerrewardtext : entry=1491
UPDATE `trans_words` SET `content_loc11`='Great, you got it! Let\'s grind this up and mix it with some wine, and...' WHERE `word_id` = 166577; -- locales_quest - offerrewardtext : entry=865
UPDATE `trans_words` SET `content_loc11`='Great, you got it! Thanks a lot, $N. This is my favorite pick! Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!' WHERE `word_id` = 141306; -- locales_quest - offerrewardtext : entry=25135
UPDATE `trans_words` SET `content_loc11`='Great, you got them! I can sell these to my contacts for a bundle!$B$BThanks for the delivery, $N! You are a great partner.' WHERE `word_id` = 135180; -- locales_quest - offerrewardtext : entry=1221
UPDATE `trans_words` SET `content_loc11`='Great, you got them! Now I can get to work...' WHERE `word_id` = 138628; -- locales_quest - offerrewardtext : entry=29027
UPDATE `trans_words` SET `content_loc11`='Great, you got them! Now we need to get them to the gnomes. But first...$B$BLet\'s take out one small item...' WHERE `word_id` = 134802; -- locales_quest - offerrewardtext : entry=1112
UPDATE `trans_words` SET `content_loc11`='Great, you got them! We can use these to make toys and baubles, and those will attract more people to the Faire!$B$BHere\'s your ticket, $N. You earned it!' WHERE `word_id` = 142643; -- locales_quest - offerrewardtext : entry=7899
UPDATE `trans_words` SET `content_loc11`='Great, you made them!  These will do nicely... I just hope I won\'t be the one to clean the crocolisk cage when the time comes. Those beasts can be rather beastly, don\'t you think?$B$BHere are your tickets, $N. Enjoy them, and enjoy your stay at the Darkmoon Faire!' WHERE `word_id` = 142612; -- locales_quest - offerrewardtext : entry=7884
UPDATE `trans_words` SET `content_loc11`='Greater Felfire Diemetradon Tagged' WHERE `word_id` = 151948; -- locales_quest - ObjectiveText1 : entry=10672
UPDATE `trans_words` SET `content_loc11`='Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and destroy Exarch Maladaar.' WHERE `word_id` = 149891; -- locales_quest - objectives : entry=10164
UPDATE `trans_words` SET `content_loc11`='Greatmother Geyah at Garadar in Nagrand has asked that you collect 1 Olemba Root, 1 Marshberry, 1 Telaari Frond and 1 Dragonspine.' WHERE `word_id` = 272875; -- locales_quest - details : entry=10045
UPDATE `trans_words` SET `content_loc11`='Green Cauldron disturbed' WHERE `word_id` = 160509; -- locales_quest - ObjectiveText2 : entry=12627
UPDATE `trans_words` SET `content_loc11`='Green Moonstone deactivated' WHERE `word_id` = 172389; -- locales_quest - ObjectiveText2 : entry=13630
UPDATE `trans_words` SET `content_loc11`='Green Sample Collected' WHERE `word_id` = 163529; -- locales_quest - ObjectiveText2 : entry=13320
UPDATE `trans_words` SET `content_loc11`='Greengill Slave freed' WHERE `word_id` = 154542; -- locales_quest - ObjectiveText1 : entry=11541
UPDATE `trans_words` SET `content_loc11`='Greetin\'s, $G brotha:sista;! Have you too come to purify the waters here and prove your understandin\' to Islen?$B$BI\'ve just defeated the corrupt water spirit meself, and I\'m just \'bout to put da bracers and remaining drops o\' water on the brazier.$B$BWhat\'s dat? Ahhh. Tiev understan\' all too well when somethin\' goes wrong. Well, Tiev can help you plenty if you be needin\' to see the pure water spirit again.$B$BBring me a water sapta from Islen as proof that you be ready, an\' I\'ll wait to turn in me parts.' WHERE `word_id` = 134758; -- locales_quest - details : entry=1103
UPDATE `trans_words` SET `content_loc11`='Greetings $N - the name\'s Luglunket, and we\'ve got an important job for you if you\'re up for it!  Huzzah!$B$BNothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert. That\'s our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in. Most importantly though, you\'re helping Gadgetzan help itself!' WHERE `word_id` = 136179; -- locales_quest - details : entry=1707
UPDATE `trans_words` SET `content_loc11`='Greetings and salutations, friend. Welcome to Tanaris!' WHERE `word_id` = 184478; -- locales_quest - offerrewardtext : entry=27446
UPDATE `trans_words` SET `content_loc11`='Greetings to you, $C. I am glad to hear that Ubungo found someone that he could trust.$B$BWelcome to Zim\'Torga.' WHERE `word_id` = 160494; -- locales_quest - offerrewardtext : entry=12623
UPDATE `trans_words` SET `content_loc11`='Greetings to you, $R.$B$BThe concern is clear on your face. Please tell me what troubles you.' WHERE `word_id` = 162453; -- locales_quest - offerrewardtext : entry=13077
UPDATE `trans_words` SET `content_loc11`='Greetings young $C, I\'m glad to see you ready and eager to learn about the curing of poisons.$B$BWhile most druids in the past were put through pre-planned trials, your work will involve no such thing. There has been a rash of animal poisonings at the Crossroads in the Barrens, and they\'re unable to bring it under control. Someone there has requested Moonglade for aid, so we are sending you there to aid them. This is no exercise - the work you\'ll do is quite real. Bear this in mind.' WHERE `word_id` = 141027; -- locales_quest - offerrewardtext : entry=6126
UPDATE `trans_words` SET `content_loc11`='Greetings young $C, I\'m glad to see you ready and eager to learn about the curing of poisons.$B$BWhile most druids in the past were put through pre-planned trials, your work will involve no such thing. There has been a rash of animal poisonings in Auberdine, and the village there has been unable to cure it. To that end, a representative there has asked Moonglade for aid and we are sending you there to aid them. This is no exercise - the work you\'ll do is quite real. Bear this in mind.' WHERE `word_id` = 141006; -- locales_quest - offerrewardtext : entry=6121
UPDATE `trans_words` SET `content_loc11`='Greetings! As you can see, the Western Plaguelands is very nearly free of the last remnants of the scourge. However, their school of necromancy, Scholomance, still sits full of lost young souls training to become scourge sorcerers! Our work here will be for naught if we do not stop this flow of fresh, not to mention very powerful, necromancers.$B$BTravel southeast to Scholomance and find Weldon Barov. He is the last living member of the Barov line that once owned all these lands and is our current contact.' WHERE `word_id` = 183638; -- locales_quest - details : entry=27149
UPDATE `trans_words` SET `content_loc11`='Greetings, $C - I stand guard here as both a speaker for the Timbermaw here in Winterspring and as a defender of the tribe.$B$BOur Winterfall brethren here in this frigid land have fallen under the same corruptive sway as the furbolg of Felwood. If you\'ve come here offering the Timbermaw furbolgs aid, then we are ready to accept such an offer.' WHERE `word_id` = 143588; -- locales_quest - offerrewardtext : entry=28521
UPDATE `trans_words` SET `content_loc11`='Greetings, $C! You have a fresh look about you. You new to Darkshore?$B$BI could catch you up on the happenings--and there are quite a few--or I could just let you see for yourself. I have a Sentinel flying out on a scouring mission shortly. Why don\'t you join her and get aquatinted with things? I insist. You can stop by when you return at deliver her report yourself.$B$BSpeak to me again when you\'re ready to go.' WHERE `word_id` = 172321; -- locales_quest - details : entry=13608
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. Crusaders like you are a welcome sight in these desolate reaches.$B$BYour holy strength is needed to help fight the endless undead here. We need you to collect a large number of scourgestones and bring them to High Priest Thel\'danis. The high priest can be found guarding Uther\'s Tomb in Sorrow Hill, not far from here.$B$BOnly one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven\'t already.' WHERE `word_id` = 143502; -- locales_quest - details : entry=8414
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.$B$BWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.$B$BReturn here with sinew from an adult blue dragon and this quiver shall be yours.' WHERE `word_id` = 142249; -- locales_quest - details : entry=7634
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. I am Orm, and Thun\'grim tells me you wish a helm made?' WHERE `word_id` = 136363; -- locales_quest - offerrewardtext : entry=1840
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. I trust that you\'re journey here was uneventful?$B$BThese poor souls are beset upon all sides by the creatures of the night. It is our wish that you lend them what aid you can in pushing back the darkness.$B$BTravel about the town and get to know its inhabitants. Please, $N, help them in any way that you can.' WHERE `word_id` = 146955; -- locales_quest - offerrewardtext : entry=9429
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. It is good that you have finally arrived....' WHERE `word_id` = 174027; -- locales_quest - offerrewardtext : entry=14338
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. Say hello to Jir\'see here, too. Don\'t worry, he won\'t bite unless I tell him to.$B$B<Angela makes a cooing sound at the felhunter.>$B$BHe\'s so tiny in comparison to the warp hounds that live in Outland. But we\'re going to fix that right up, yes we are, aren\'t we, Jir\'see?$B$BI think I\'ve figured out a way to do it. I\'ll need plenty of blood from the warp hounds and that\'s where you come in. While you\'re hunting them in the southeast, I\'ll get ready for the experi... err, treatment.' WHERE `word_id` = 171500; -- locales_quest - details : entry=9379
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. The situation here is tense. The elements are restless and the people are scared and confused. The Warchief is trying to find a semblance of balance between leading the people and protecting Azeroth. Though it seems he will soon be leaving us to travel to Nagrand and gain insight about the elementals. Regardless of the Warchief\'s choice, we still must do what we can. Help calm the populace, scour the lands for rogue elementals. These tasks will surely help our cause.' WHERE `word_id` = 171946; -- locales_quest - offerrewardtext : entry=27570
UPDATE `trans_words` SET `content_loc11`='Greetings, $C. You bring news from Orgrimmar; that is good.$B$BThe demon infestation overwhelms this area even more than the smell of centaur dung. The horse-men claim this land as their own, but clearly there are influences out of their control that will crush them if not kept in check.$B$BIt does not please me that we aid the centaur indirectly, but it is for the good of the Horde, so I do my duty for the Warchief, even if it means helping the warlocks within the Horde.' WHERE `word_id` = 135588; -- locales_quest - offerrewardtext : entry=1432
UPDATE `trans_words` SET `content_loc11`='Greetings, $C.$B$BI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.$B$BOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well.' WHERE `word_id` = 134338; -- locales_quest - offerrewardtext : entry=1000
UPDATE `trans_words` SET `content_loc11`='Greetings, $C.$B$BI\'m certain your travels in Outland have shown you something of the corruption in this world. It is so pervasive that it has transformed the very creatures who dwell here - the ones that survived, that is.$B$BThe clefthoof to the south and west were once docile grazers, but the corruption has created an unquenchable rage in them. They only find release from their torment in death, though it grieves us to spill their blood. Will you help me end the suffering of the bristlehide clefthoof?' WHERE `word_id` = 146797; -- locales_quest - details : entry=9382
UPDATE `trans_words` SET `content_loc11`='Greetings, $C; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.' WHERE `word_id` = 134090; -- locales_quest - offerrewardtext : entry=3762
UPDATE `trans_words` SET `content_loc11`='Greetings, $Gbrother:sister;. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you\'ve performed thus far.$B$BIf I were you, I\'d head to Stormwind and speak to him when you have time. I\'m sure he\'s in the Cathedral of Light--that\'s where he spends most of his time.' WHERE `word_id` = 137698; -- locales_quest - details : entry=2998
UPDATE `trans_words` SET `content_loc11`='Greetings, $Gbrother:sister;. You may have come on behalf of the Argent Dawn, but that is not why you are here -- you are here to help your people earn the respect we so justly deserve. As any forsaken will agree, the end justifies the means, and our research into the zombie plague\'s cure is that proverb in practice...' WHERE `word_id` = 161099; -- locales_quest - offerrewardtext : entry=12752
UPDATE `trans_words` SET `content_loc11`='Greetings, $Gladdy:lass;. Good to see you here in our great halls. A blessing be on you and your kind.$B$BWhile you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I\'m sorry I can\'t tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.' WHERE `word_id` = 140551; -- locales_quest - details : entry=5633
UPDATE `trans_words` SET `content_loc11`='Greetings, $N, and welcome. Are you here to study near the Altar of Storms as I am, perhaps to harness its energy for some hidden purpose...$B$BOr... are you here to speak with me?  Yes, I believe you are.$B$BYou want to master a dreadsteed?  Such is no easy task. It will cost you no small amounts of blood, sweat... and of course gold. But a dreadsteed of Xoroth is a prize well worth winning so if interested, listen on...' WHERE `word_id` = 142153; -- locales_quest - offerrewardtext : entry=7562
UPDATE `trans_words` SET `content_loc11`='Greetings, $N, this is a test. Accept and kill stuff' WHERE `word_id` = 174328; -- locales_quest - details : entry=14425
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. Before I assign you to more involved tasks in the war, you\'ll need to do your share of field duty. $B$BYou will find Captain Blackanvil\'s Ironforge Brigade outside Hive\'Zora.$B$BReport to him or his lieutenant, Janela Stouthammer and come back to me. I shall have a more advanced assignment for you ready.$B$BOh and please do us a favor and stay away from the Orgrimmar Legion. We\'ve been forced to keep the two forces well apart from one another due to mutual animosity.' WHERE `word_id` = 143687; -- locales_quest - details : entry=8507
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. Before I assign you to more involved tasks in the war, you\'ll need to do your share of field duty. $B$BYou will find Captain Skullsplit\'s Orgrimmar Legion outside Hive\'Regal.$B$BReport to him and come back to me with proof of your field service. I shall have a more advanced assignment ready for you.$B$BOh, please do your best to stay away from the Ironforge Brigade. Tensions are high among our Alliance and Horde volunteers.' WHERE `word_id` = 144189; -- locales_quest - details : entry=8731
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained.$B$BThe spring rains were particularly heavy this year, causing some of the forest\'s beasts to flourish while others suffered.$B$BUnfortunately, the nightsaber and thistle boar populations grew too large. Shadowglen can only produce so much food for the beasts. Journey forth, young $C, and thin the boar and saber populations so that nature\'s harmony will be preserved.' WHERE `word_id` = 132090; -- locales_quest - details : entry=456
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.$B$BYou are probably wondering why I am here and what it is that I want from you - both valid questions.$B$BI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.' WHERE `word_id` = 138482; -- locales_quest - details : entry=3801
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. I am pleased to see you, and hope you have time to listen to an old man\'s words...' WHERE `word_id` = 136471; -- locales_quest - offerrewardtext : entry=1939
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. I see you wield a weapon. Can you fight?' WHERE `word_id` = 188931; -- locales_quest - offerrewardtext : entry=28653
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. Old Thun\'grim sent word to me of your coming, but had he kept silent your presence here would not have surprised me.$B$BThe spirits follow your progress, young $C, and they tell me that many foes have fallen before you.' WHERE `word_id` = 136359; -- locales_quest - offerrewardtext : entry=1839
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. Outland is a perilous place, as many of our expedition quickly learned. I\'m afraid young Grelag may have learned that lesson firsthand.$B$BGrelag is a promising student, but he lacks patience! He eagerly studies the history of his people, but he sometimes forgets the threats of the present day.$B$BHe departed for the Spinebreaker Post, ignorant of the Legion and fel orc presences. I fear something may have happened to him.' WHERE `word_id` = 146687; -- locales_quest - details : entry=9344
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. You have the look of an adventurer about you, and I have a task that needs some tending to.$B$BArchmage Trelane, my original master, fled Stromgarde in the Arathi Highlands not too long ago, and he\'s asked me to help him in recovering some of the items he left behind.$B$BThe city fell under siege, and he attempted to defend the Tower of Arathor, but to no avail. I have agents in the Highlands already, but they\'ve requested I send more aid. Are you interested?' WHERE `word_id` = 133091; -- locales_quest - details : entry=690
UPDATE `trans_words` SET `content_loc11`='Greetings, $N. You were wise to answer my call, and wiser still if you heed what I next say...' WHERE `word_id` = 136416; -- locales_quest - offerrewardtext : entry=1881
UPDATE `trans_words` SET `content_loc11`='Greetings, $R. Dese be desperate times. Da Zandalar trolls be ready to take back dere lands.' WHERE `word_id` = 190007; -- locales_quest - offerrewardtext : entry=29157
UPDATE `trans_words` SET `content_loc11`='Greetings, $R. I have been told of your coming. If you wish to aid me, then perhaps I can be of aid to you as well.' WHERE `word_id` = 181568; -- locales_quest - offerrewardtext : entry=26576
UPDATE `trans_words` SET `content_loc11`='Greetings, $R. Sent by Keegan?' WHERE `word_id` = 185836; -- locales_quest - offerrewardtext : entry=27806
UPDATE `trans_words` SET `content_loc11`='Greetings, adventurer! Are you interested in some work? I pay those under my employ with insignias. These insignias can be used at the Quartermaster to purchase items of power.$B$BAll I need you to do is bring me as many core of elements as you can carry. The more the better!$B$BYou\'ll find them on elementals of varying shapes and sizes that exist across our world.' WHERE `word_id` = 145064; -- locales_quest - details : entry=9128
UPDATE `trans_words` SET `content_loc11`='Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.$B$BAnd you will learn.$B$BThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.$B$BI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.' WHERE `word_id` = 135716; -- locales_quest - details : entry=1470
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?$B$BI must warn you; epic purchases made at revered reputation with the Dawn are still quite expensive. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.' WHERE `word_id` = 145211; -- locales_quest - details : entry=9225
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?$B$BI must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.' WHERE `word_id` = 272332; -- locales_quest - details : entry=9222
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?$B$BI must warn you; purchases made at honored reputation with the Dawn come with an extremely hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.' WHERE `word_id` = 145208; -- locales_quest - details : entry=9224
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?$B$BThose exalted amongst the Dawn receive our greatest discounts! I encourage you to make a purchase.' WHERE `word_id` = 145220; -- locales_quest - details : entry=9228
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?$B$BI must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.' WHERE `word_id` = 145197; -- locales_quest - details : entry=9221
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?$B$BI must warn you; purchases made at honored reputation with the Dawn come with a fairly prohibitive surcharge. I would advise that you gain a better reputation with the Dawn before moving forward with your plans.' WHERE `word_id` = 145205; -- locales_quest - details : entry=9223
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?$B$BItems offered to those exalted amongst the Dawn are discounted. I encourage you to make a purchase!' WHERE `word_id` = 145217; -- locales_quest - details : entry=9227
UPDATE `trans_words` SET `content_loc11`='Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power?$B$BItems offered to those revered amongst the Dawn are priced quite reasonably. I encourage you to make a purchase!' WHERE `word_id` = 145214; -- locales_quest - details : entry=9226
UPDATE `trans_words` SET `content_loc11`='Greetings, friend.$B$BOn behalf of the Earthen Ring I thank you for answering my call.$B$BYou are known to us by name, $N.$B$BYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.$B$BI am but a messenger. A familiar presence seeks audience with you.$B$BPeer into the Waters of Farseeing and behold the fate of our world.' WHERE `word_id` = 189287; -- locales_quest - details : entry=28805
UPDATE `trans_words` SET `content_loc11`='Greetings, hero of Azeroth.$B$BOn behalf of the Earthen Ring I thank you for answering my call.$B$BYou are known to us by name, $N.$B$BYour exploits and accomplishments are many. Azeroth already stands in your debt, and yet again she is in need of her heroes.$B$BI am but a messenger. A powerful presence seeks audience with you.$B$BPeer into the Waters of Farseeing and behold the dilemma of our world.' WHERE `word_id` = 189324; -- locales_quest - details : entry=28826
UPDATE `trans_words` SET `content_loc11`='Greetings, tiny $R. The birds in my boughs whispered to me that you were to be expected.$B$BYou are here to help free the trees of the woods from their possession?' WHERE `word_id` = 152507; -- locales_quest - offerrewardtext : entry=10829
UPDATE `trans_words` SET `content_loc11`='Greetings, traveler!$B$BDon\'t suppose you might be heading in the direction of Menethil, would you? If you\'re not, I\'d suggest you stop there, it\'s a good place to purchase goods and even have a pint and relax.$B$BNow, if it just so happens that you\'re heading in that direction, I don\'t suppose you\'d mind taking this bundle of crocolisk skins to James Halloran, the tanner?$B$BI\'d do it myself, but my wife\'s been in quite a mood lately, and I\'d like to put off facing her as long as possible.' WHERE `word_id` = 132144; -- locales_quest - details : entry=469
UPDATE `trans_words` SET `content_loc11`='Greetings, traveler. You seem to have an interest in my friend here. You\'re here on behalf of his friend Volcor then I imagine? If Volcor didn\'t come himself, he must be injured as well. I hope he recovers quickly. Gimclaw is too injured to be moved far and he\'s going to need some immediate treatment. I\'m afraid I can\'t let you take him back just yet, but perhaps you can help me while I tend to him.' WHERE `word_id` = 172171; -- locales_quest - offerrewardtext : entry=13564
UPDATE `trans_words` SET `content_loc11`='Greetings, warrior. Your skill grows, but there is more to your profession than you may believe. To further progress, you must soon find a teacher.$B$BThe warrior Elanaria dwells in Darnassus, at the Warrior\'s Terrace. She can instruct you.' WHERE `word_id` = 136101; -- locales_quest - details : entry=1684
UPDATE `trans_words` SET `content_loc11`='Greetings, young one. You are here to walk the hunter\'s path?$B$BVery good. Let us begin.' WHERE `word_id` = 137956; -- locales_quest - offerrewardtext : entry=3261
UPDATE `trans_words` SET `content_loc11`='Greetings. I unit A-Me 01. You... $R?$B$BA-Me\'s mission to study the local gorillas was success. A-Me has gathered data and now will bring to Karna.$B$BIt time for A-Me to return to Karna. You come with?  We embark right away, so make sure you ready first.' WHERE `word_id` = 175355; -- locales_quest - details : entry=24716
UPDATE `trans_words` SET `content_loc11`='Greetings. It is always heartening to meet a $R who is open to the way of shamanism. There are so few.$B$BYou have learned not to judge the flame for its outward appearance, just as you should not judge mine.$B$BYou are here because you are ready to create your fire totem.' WHERE `word_id` = 147459; -- locales_quest - offerrewardtext : entry=9555
UPDATE `trans_words` SET `content_loc11`='Greetings. You\'ve come learn some new ways to handle fire?' WHERE `word_id` = 154699; -- locales_quest - offerrewardtext : entry=11915
UPDATE `trans_words` SET `content_loc11`='Grelag wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south of Honor Hold.' WHERE `word_id` = 149503; -- locales_quest - objectives : entry=10061
UPDATE `trans_words` SET `content_loc11`='Grenka was powerful, even by troll standards. You should be proud of your accomplishment this day.$B$BDuring your test of faith you displayed strength of spirit, and now you have shown endurance in battle by taking on the Roguefeather harpies, but the time has come for a new test.' WHERE `word_id` = 134967; -- locales_quest - offerrewardtext : entry=1150
UPDATE `trans_words` SET `content_loc11`='Gretchen Fizzlespark wants to use my flying machine to look for survivors from her expedition. Apparently she thinks they\'re being held prisoner in the village to the north.$B$BThe only problem is I don\'t have a co-pilot. If you\'re willing to take it on, I\'d be more than happy to teach you a move or two.$B$BWhat do you say, $N?  Deal?' WHERE `word_id` = 162354; -- locales_quest - details : entry=13053
UPDATE `trans_words` SET `content_loc11`='Gretta the Arbiter, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears.' WHERE `word_id` = 163843; -- locales_quest - objectives : entry=13424
UPDATE `trans_words` SET `content_loc11`='Greymane wants to save Crowley?  Has he gone mad?' WHERE `word_id` = 173424; -- locales_quest - offerrewardtext : entry=14157
UPDATE `trans_words` SET `content_loc11`='Greymane\'s right. These beasts do not give a damn about our politics. Gilneas needs to stand together.' WHERE `word_id` = 189413; -- locales_quest - offerrewardtext : entry=28850
UPDATE `trans_words` SET `content_loc11`='Greymist Murloc Home Built' WHERE `word_id` = 172782; -- locales_quest - ObjectiveText1 : entry=13910
UPDATE `trans_words` SET `content_loc11`='Grezz Ragefist told me to expect you. Those materials will make a fine sword. Always use it for the glory of the Horde.' WHERE `word_id` = 184240; -- locales_quest - offerrewardtext : entry=27365
UPDATE `trans_words` SET `content_loc11`='Griftah wants you to take Griftah\'s Note to Budd in the Ghostlands, just outside of Zul\'Aman.' WHERE `word_id` = 153748; -- locales_quest - objectives : entry=11130
UPDATE `trans_words` SET `content_loc11`='Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it. His lost eye burns deep in some hellish pit, now a demon\'s trinket... and the patch that covers his betrayal holds its own dark secrets.$B$BBring me Grillok\'s eyepatch, $N, and I will reward you greatly for your service...' WHERE `word_id` = 152530; -- locales_quest - details : entry=10834
UPDATE `trans_words` SET `content_loc11`='Grim Batol entrance secured' WHERE `word_id` = 186859; -- locales_quest - ObjectiveText1 : entry=28093
UPDATE `trans_words` SET `content_loc11`='Grim business, but well done all the same. Thank you, $N.' WHERE `word_id` = 189453; -- locales_quest - offerrewardtext : entry=28863
UPDATE `trans_words` SET `content_loc11`='Grim business, that. No pun intended.' WHERE `word_id` = 179046; -- locales_quest - offerrewardtext : entry=25869
UPDATE `trans_words` SET `content_loc11`='Grim news, lad. Those Iron Dwarves seem to be increasing in numbers... we\'ve been seeing them all over the mountains. I smell war coming.$B$BThank you for dealing with this bunch... a little more time bought.' WHERE `word_id` = 161622; -- locales_quest - offerrewardtext : entry=12876
UPDATE `trans_words` SET `content_loc11`='Grim tidings, $N. My people are in danger and must be warned. These sea faring aberrations will take no mercy upon the Kalu\'ak.' WHERE `word_id` = 156861; -- locales_quest - offerrewardtext : entry=11568
UPDATE `trans_words` SET `content_loc11`='Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.' WHERE `word_id` = 130329; -- locales_quest - objectives : entry=49
UPDATE `trans_words` SET `content_loc11`='Grimbooze Thunderbrew wants Truesilver.' WHERE `word_id` = 130332; -- locales_quest - objectives : entry=50
UPDATE `trans_words` SET `content_loc11`='Grimfeather Mounted' WHERE `word_id` = 174062; -- locales_quest - ObjectiveText1 : entry=14346
UPDATE `trans_words` SET `content_loc11`='Grimscale naga slain.' WHERE `word_id` = 189598; -- locales_quest - ObjectiveText1 : entry=28936
UPDATE `trans_words` SET `content_loc11`='Grimtotem Armed' WHERE `word_id` = 178944; -- locales_quest - ObjectiveText1 : entry=25847
UPDATE `trans_words` SET `content_loc11`='Grimtotem need weapons! The Horde, empowered by their Warchief and with the help of their new goblin allies, have amassed powerful weaponry. Our armaments are simply no match for their firepower. Supply the Grimtotem with strong weapons and we will work together to destroy the Horde!$B$BThese are our demands! Supply the Grimtotem and we will fight for the Alliance!' WHERE `word_id` = 178931; -- locales_quest - details : entry=25845
UPDATE `trans_words` SET `content_loc11`='Grimtotem on Darkcloud Pinnacle slain' WHERE `word_id` = 184061; -- locales_quest - ObjectiveText1 : entry=27312
UPDATE `trans_words` SET `content_loc11`='Grind Corn Kernels' WHERE `word_id` = 190377; -- locales_quest - ObjectiveText1 : entry=29364
UPDATE `trans_words` SET `content_loc11`='Griswold defeated' WHERE `word_id` = 176902; -- locales_quest - ObjectiveText1 : entry=25258
UPDATE `trans_words` SET `content_loc11`='Grizzled Thistle Bear Protected' WHERE `word_id` = 172704; -- locales_quest - ObjectiveText1 : entry=13885
UPDATE `trans_words` SET `content_loc11`='Grizzly Hills Giants Rallied' WHERE `word_id` = 158395; -- locales_quest - ObjectiveText1 : entry=12070
UPDATE `trans_words` SET `content_loc11`='Grok said that I am wise?  I don\'t know about that.$B$BPerhaps it is because I am the only one in my clan that is truly trying to save us from annihilation by the Bladespire clan, and Gruul and his sons, who are backing them.$B$BI hope that you have come to deliver us from certain doom, $C.' WHERE `word_id` = 153178; -- locales_quest - offerrewardtext : entry=10983
UPDATE `trans_words` SET `content_loc11`='Grom\'s full name - Grommash - means "The Giant\'s Heart"; it took that and more to stand alone against Mannoroth. I think the Warchief said it best when the curse of the orcs began and ended with Grom. Fitting that Grom\'s sacrifice - and perhaps redemption - would be the wellspring from which the Horde flows today.$B$BThank you, $N. You\'ve paid tribute to a great hero today, honoring his spirit and the spirit of the Harvest Festival.' WHERE `word_id` = 334852; -- locales_quest - offerrewardtext : entry=8150
UPDATE `trans_words` SET `content_loc11`='Grom\'thar the Thunderbringer. Good. Let\'s end any threat these magnataur might pose here and now.' WHERE `word_id` = 158744; -- locales_quest - offerrewardtext : entry=12150
UPDATE `trans_words` SET `content_loc11`='Groovy! You\'re my kind of $R.' WHERE `word_id` = 161429; -- locales_quest - offerrewardtext : entry=12836
UPDATE `trans_words` SET `content_loc11`='Ground Commander Koup at the edge of the glacier east of Ymirheim has ordered you to use the Skybreaker Suppression Turret to keep the Skybreaker Troop Transport alive long enough to make all of its drops.' WHERE `word_id` = 275054; -- locales_quest - details : entry=13309
UPDATE `trans_words` SET `content_loc11`='Grow large enough to reach the clouds' WHERE `word_id` = 185499; -- locales_quest - ObjectiveText1 : entry=27714
UPDATE `trans_words` SET `content_loc11`='Grrr. I knew it! He\'s sooooo over-protective! This is just embarassing.$B$BNot that I\'m not happy to see you... I am! We all are. We can use your help!' WHERE `word_id` = 155437; -- locales_quest - offerrewardtext : entry=11175
UPDATE `trans_words` SET `content_loc11`='Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.' WHERE `word_id` = 133355; -- locales_quest - objectives : entry=750
UPDATE `trans_words` SET `content_loc11`='Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.' WHERE `word_id` = 133341; -- locales_quest - objectives : entry=747
UPDATE `trans_words` SET `content_loc11`='Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.' WHERE `word_id` = 133479; -- locales_quest - objectives : entry=780
UPDATE `trans_words` SET `content_loc11`='Grundig Darkcloud is dead! $N, I will always be grateful for what you\'ve done here today.' WHERE `word_id` = 141580; -- locales_quest - offerrewardtext : entry=6629
UPDATE `trans_words` SET `content_loc11`='Grunt Grahk at the tunnel between Zangarmarsh and Blade\'s Edge Mountains wants you to kill 6 Cavern Crawlers and report to Tor\'chunk Two-claws in Thunderlord Stronghold.' WHERE `word_id` = 152957; -- locales_quest - objectives : entry=10928
UPDATE `trans_words` SET `content_loc11`='Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.' WHERE `word_id` = 130198; -- locales_quest - objectives : entry=14
UPDATE `trans_words` SET `content_loc11`='Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.' WHERE `word_id` = 130194; -- locales_quest - objectives : entry=13
UPDATE `trans_words` SET `content_loc11`='Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.' WHERE `word_id` = 130190; -- locales_quest - objectives : entry=12
UPDATE `trans_words` SET `content_loc11`='Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.' WHERE `word_id` = 130400; -- locales_quest - objectives : entry=65
UPDATE `trans_words` SET `content_loc11`='Gshaff wants you to gather 6 Fertile Spores from the various Zangarmarsh Spore Bats and Marsh Walkers. Return to Ghsaff at Sporeggar when you\'ve completed this task.' WHERE `word_id` = 148462; -- locales_quest - objectives : entry=9806
UPDATE `trans_words` SET `content_loc11`='Guardian Flag Visited' WHERE `word_id` = 177732; -- locales_quest - ObjectiveText1 : entry=25523
UPDATE `trans_words` SET `content_loc11`='Guardian Menerin wants you to deliver the Sealed Missive to Guardian Gurtar.' WHERE `word_id` = 172645; -- locales_quest - objectives : entry=13873
UPDATE `trans_words` SET `content_loc11`='Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.' WHERE `word_id` = 141486; -- locales_quest - objectives : entry=6584
UPDATE `trans_words` SET `content_loc11`='Guests served' WHERE `word_id` = 189705; -- locales_quest - ObjectiveText1 : entry=29060
UPDATE `trans_words` SET `content_loc11`='Gunpowder thrown at abomination' WHERE `word_id` = 174074; -- locales_quest - ObjectiveText1 : entry=14348
UPDATE `trans_words` SET `content_loc11`='Gunship destroyed' WHERE `word_id` = 182048; -- locales_quest - ObjectiveText1 : entry=26706
UPDATE `trans_words` SET `content_loc11`='Gurgthock told you he\'d make it worth your while, kid. Take your pick!' WHERE `word_id` = 149161; -- locales_quest - offerrewardtext : entry=9977
UPDATE `trans_words` SET `content_loc11`='Gurn Grubnosh\'s helm and a Bladespire banner?$B$BQuite clever of you and the vindicator to come up with that plan.$B$BBy keeping the attention of the Bloodmaul clan on Bladespire Hold, you\'ve relieved the pressure that they were beginning to assert upon us here.$B$BPlease, $N, accept a humble gift from Sylvanaar.' WHERE `word_id` = 151334; -- locales_quest - offerrewardtext : entry=10518
UPDATE `trans_words` SET `content_loc11`='GUROK! Gurok betrayed the elements!' WHERE `word_id` = 148658; -- locales_quest - offerrewardtext : entry=9849
UPDATE `trans_words` SET `content_loc11`='Gurrok Debriefed' WHERE `word_id` = 179571; -- locales_quest - ObjectiveText1 : entry=26007
UPDATE `trans_words` SET `content_loc11`='Guse\'s Location Discovered' WHERE `word_id` = 141977; -- locales_quest - ObjectiveText1 : entry=7302
UPDATE `trans_words` SET `content_loc11`='Guvan at Azure Watch wants you to find Tavara and heal her wounds.' WHERE `word_id` = 147586; -- locales_quest - objectives : entry=9586
UPDATE `trans_words` SET `content_loc11`='Gwen Armstead in Grimmburg wants you to bring her 3 Spiked Wolf Collars.' WHERE `word_id` = 173006; -- locales_quest - objectives : entry=13984
UPDATE `trans_words` SET `content_loc11`='Gwen Armstead in Grimmburg wants you to slay 8 Orc Scouts.' WHERE `word_id` = 172980; -- locales_quest - objectives : entry=13978
UPDATE `trans_words` SET `content_loc11`='Gwen Armstead wants you to investigate the Queen\'s Gate.' WHERE `word_id` = 173942; -- locales_quest - objectives : entry=14317
UPDATE `trans_words` SET `content_loc11`='Ha ha ha! I knew you\'d be back.$B$B<Willow mutters>$B$B...So easy to convince.$B$B...Will do anything for the right price. Heh heh heh...' WHERE `word_id` = 141780; -- locales_quest - offerrewardtext : entry=7028
UPDATE `trans_words` SET `content_loc11`='Ha ha!  I hope that they come back as zombies.' WHERE `word_id` = 182832; -- locales_quest - offerrewardtext : entry=26933
UPDATE `trans_words` SET `content_loc11`='Ha ha!  One of those meat slabs landed clear over here!  Nice work there!' WHERE `word_id` = 335830; -- locales_quest - offerrewardtext : entry=12049
UPDATE `trans_words` SET `content_loc11`='Ha ha! Good to see you\'re up for some dirty work.$B$BMuch appreciated there, $Gpal:lass;!' WHERE `word_id` = 161397; -- locales_quest - offerrewardtext : entry=12829
UPDATE `trans_words` SET `content_loc11`='Ha ha! Perfect! Let me toss this together really fast. The Archmage is sure to be taken in by my style!' WHERE `word_id` = 173669; -- locales_quest - offerrewardtext : entry=14249
UPDATE `trans_words` SET `content_loc11`='Ha ha! These are them! Thank you kindly. I hope you didn\'t have too much trouble traversing the field.' WHERE `word_id` = 161348; -- locales_quest - offerrewardtext : entry=12819
UPDATE `trans_words` SET `content_loc11`='Ha ha! Well, done indeed.$B$BWho would have ever guessed that I, Zenn Foulhoof, would have a $R to do my bidding? Certainly not me! But so it goes... this beloved world of ours is full of surprises.$B$BThree cheers for the naive and gullible!' WHERE `word_id` = 132234; -- locales_quest - offerrewardtext : entry=488
UPDATE `trans_words` SET `content_loc11`='Ha hah! What a ride, eh $C?$B$BIf we can\'t control the resources here, then no one can!$B$BWhen will those puny Alliance pests realize that they are no match for the might of the Horde?' WHERE `word_id` = 159660; -- locales_quest - offerrewardtext : entry=12432
UPDATE `trans_words` SET `content_loc11`='Ha! <cough cough>$B$BAh knew you\'d find me amulet, $N.$B$B<weeze> Well done indeed, $N. <cough>' WHERE `word_id` = 133238; -- locales_quest - offerrewardtext : entry=722
UPDATE `trans_words` SET `content_loc11`='Ha! Grand tale lad... perhaps ye have a bit of frostborn blood in ye, eh? Yer not just talk anyway, and that\'s what I needed to hear.' WHERE `word_id` = 161613; -- locales_quest - offerrewardtext : entry=12874
UPDATE `trans_words` SET `content_loc11`='Ha! That ichor you\'re covered in actually makes you prettier, $N! It certainly does make you reek at the same time though. Don\'t stand too close to the kodo; you\'ll either start a stampede or cause them to go into heat.$B$BI think my companions would agree that your smell alone is proof you\'ve done your part to help us against those insect creatures. Thank you, $N.' WHERE `word_id` = 134952; -- locales_quest - offerrewardtext : entry=1147
UPDATE `trans_words` SET `content_loc11`='HA! Well done, $N! Very well done... I wasn\'t sure you were up to the task, but you\'ve proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well.' WHERE `word_id` = 133833; -- locales_quest - offerrewardtext : entry=876
UPDATE `trans_words` SET `content_loc11`='HA! You did it! The soldiers at the Wrathgate are indebted to you, $N! This\'ll surely buy a few of them another day above ground.' WHERE `word_id` = 158520; -- locales_quest - offerrewardtext : entry=12097
UPDATE `trans_words` SET `content_loc11`='Ha! You\'ve done it! Thrall will be so pleased.$B$BI will ensure this heart is taken care of properly.$B$BFor now though, you must celebrate your victory. I will inform Thrall of your success.$B$BThank you for your aid, $C.' WHERE `word_id` = 140685; -- locales_quest - offerrewardtext : entry=5761
UPDATE `trans_words` SET `content_loc11`='HA!$B$B<Lotwil grabs the gyrochronatom from you.>$B$BPerfect... just about done. No, really. I AM almost done now. This project is my top priority... at the moment. Let me pop this into place, and you can see for yourself what you\'ve helped me create. It\'ll just take me a few more minutes... maybe... possibly longer. Well, maybe a lot longer. We\'ll see...' WHERE `word_id` = 133201; -- locales_quest - offerrewardtext : entry=714
UPDATE `trans_words` SET `content_loc11`='Ha, we finally got Largo!  Nice one, $N.' WHERE `word_id` = 186518; -- locales_quest - offerrewardtext : entry=27991
UPDATE `trans_words` SET `content_loc11`='Had I not witnessed what you did with my own eyes I would not have believed it, $N. Now, with the Ambermill magi on our side, there is but one thing left to do before we retake Gilneas and send those Alliance dogs running for Stormwind.' WHERE `word_id` = 184792; -- locales_quest - offerrewardtext : entry=27518
UPDATE `trans_words` SET `content_loc11`='Had I saved every flower that dolt, Jannok, had sent me, I would have had the means to open a shop. Regardless, it seems as if Jannok\'s latest courier may prove to be useful.Interested in some work, $C?' WHERE `word_id` = 136705; -- locales_quest - offerrewardtext : entry=2241
UPDATE `trans_words` SET `content_loc11`='Had your fill already?$B$B<Reavij laughs.>$B$BThere\'s a reason why our visitors don\'t stay long.$B$BIf I had a choice, I\'d find a more agreeable spot for the post, but I\'ll take marshfangs over Denjai\'s temper any day.' WHERE `word_id` = 148290; -- locales_quest - offerrewardtext : entry=9770
UPDATE `trans_words` SET `content_loc11`='Hadrius\' taste test' WHERE `word_id` = 160599; -- locales_quest - ObjectiveText2 : entry=12645
UPDATE `trans_words` SET `content_loc11`='Hae I introduced ye tae me pet, Squirky? I\'m teachin\' him tae fish all proper-like. Fer now, I\'ve been feedin\' him minnows fished from the pool in this cavern.$B$BMaybe ye\'d like tae give it a try? Just cast yer lure in the pool over there and feed Squirky any minnows ye happen tae fish up. He\'ll love ye ferever!' WHERE `word_id` = 190274; -- locales_quest - details : entry=29344
UPDATE `trans_words` SET `content_loc11`='Hah - you caught him! You\'ve done Elwynn a great service, and earned a nice bounty!' WHERE `word_id` = 130162; -- locales_quest - offerrewardtext : entry=6
UPDATE `trans_words` SET `content_loc11`='Hah hah! A fresh $R from the mainland! Well don\'t worry - Shatter Point might make you queasy but she doesn\'t stray far!$B$BAnd I\'ve only seen her flip upside down once... or twice.' WHERE `word_id` = 150700; -- locales_quest - offerrewardtext : entry=10340
UPDATE `trans_words` SET `content_loc11`='Hah hah! Brilliant. Right fine job there, boy.' WHERE `word_id` = 174577; -- locales_quest - offerrewardtext : entry=24437
UPDATE `trans_words` SET `content_loc11`='Hah!  So you did meet the bonechewers, our depraved cousins. Well done, $N. My only regret is that more of them could not lay down their lives and spill their blood, to cool my outrage!' WHERE `word_id` = 151106; -- locales_quest - offerrewardtext : entry=10450
UPDATE `trans_words` SET `content_loc11`='Hah!  That Cromula cracks me up. Oh, right, Stranglethorn. You\'re really going?' WHERE `word_id` = 181057; -- locales_quest - offerrewardtext : entry=26416
UPDATE `trans_words` SET `content_loc11`='Hah!  That\'s quite a load!  Your back feeling alright?' WHERE `word_id` = 158278; -- locales_quest - offerrewardtext : entry=12044
UPDATE `trans_words` SET `content_loc11`='Hah!  You Nethergarde nincompoops are always two steps behind me, and I\'m nowhere near as fast as I used to be. I don\'t need Mahar\'s note to know what\'s going on. Why do you think I\'m cooped up in the back of this cave?  What I do need, however, is a strong $R like you.' WHERE `word_id` = 180101; -- locales_quest - offerrewardtext : entry=26157
UPDATE `trans_words` SET `content_loc11`='Hah! Beautiful work, $N. Those Alliance cretins will never trace this back to me. Meanwhile, it\'s back to business as usual: smuggling, double-dealing, price-gouging... I\'ve got a lot of work to catch up on. Here, I\'ll let you in on a cut of my future profits. Enjoy!' WHERE `word_id` = 173171; -- locales_quest - offerrewardtext : entry=14042
UPDATE `trans_words` SET `content_loc11`='Hah! Did you see the Admiral giving me dirty looks and decide to throw some sympathy my way? I\'ve pretty much lost hope of making him understand that these ruins offers us some opportunity to salvage some usefulness out of this whole  mess.$B$BI\'d actually hoped that you might turn up again - you seem like the only one I can rely on. I\'ve seen a few tablets like this one spread about the nearby ruins and I put together a rubbing kit for transcribing them. Up to the task?' WHERE `word_id` = 178610; -- locales_quest - details : entry=25750
UPDATE `trans_words` SET `content_loc11`='Hah! Did you see the Captain giving me dirty looks and decide you\'d throw some sympathy my way? I\'ve pretty much lost hope of making him understand that these ruins offers us some opportunity to salvage some usefulness out of this whole  mess.$B$BI\'d actually hoped that you might turn up again - you seem like the only one I can rely on. I\'ve seen a few tablets like this one spread about the nearby ruins and I put together a rubbing kit for transcribing them. Up to the task?' WHERE `word_id` = 179421; -- locales_quest - details : entry=25961
UPDATE `trans_words` SET `content_loc11`='Hah! I could see the smoke and flames of Zeth\'Gor from here! May the Bleeding Hollow fiends burn to ash and drift far from the sight of any true orc!$B$BThank you, $N. You helped burn away an afront to every orc\'s spirit.' WHERE `word_id` = 152352; -- locales_quest - offerrewardtext : entry=10792
UPDATE `trans_words` SET `content_loc11`='Hah! I guess she liked it! Nothing brings red to a lady\'s cheeks like a big, juicy steak!$B$BThank you, $N. You\'ve done me a great service. Here is some money for your trouble, and don\'t be surprised if I invite you to my wedding!' WHERE `word_id` = 141271; -- locales_quest - offerrewardtext : entry=6386
UPDATE `trans_words` SET `content_loc11`='Hah! I heard it from here! I wish I could\'ve been there to see it!' WHERE `word_id` = 187993; -- locales_quest - offerrewardtext : entry=28367
UPDATE `trans_words` SET `content_loc11`='Hah! I\'m sure Twilight\'s Hammer wanted to number those ogres among their ranks. Now they\'ll probably have to fight them off instead. This is good, $N. With one well-placed $C we managed to do the work of a small army. I\'ll let Warlord Krogg know of your work here!' WHERE `word_id` = 187094; -- locales_quest - offerrewardtext : entry=28151
UPDATE `trans_words` SET `content_loc11`='Hah! Is this some sort of joke?$B$BI barely have any use for books I can actually understand.' WHERE `word_id` = 159626; -- locales_quest - offerrewardtext : entry=12423
UPDATE `trans_words` SET `content_loc11`='Hah! It seems you were right. That broken trident is serving you just fine. I suppose I don\'t get to see you claw anything to death today after all.' WHERE `word_id` = 178056; -- locales_quest - offerrewardtext : entry=25619
UPDATE `trans_words` SET `content_loc11`='Hah! It\'s not often you run into a complete stranger in the middle of the jungle.$B$BYou one those druid lackeys sent to "stop me and my evil ways?" Yeah, good luck with that one!$B$B<Hemet lets out a hearty laugh and pats his gun.>$B$BDidn\'t think so! You\'re more than welcome to join us in the hunt, soon as we\'ve dealt with those Venture Company dogs. There\'ll be plenty to go around.' WHERE `word_id` = 159901; -- locales_quest - offerrewardtext : entry=12489
UPDATE `trans_words` SET `content_loc11`='Hah! Looks like their raid went mighty well then. I\'ll have to buy ol\' Forgehammer a round once we finish with this mess.' WHERE `word_id` = 185876; -- locales_quest - offerrewardtext : entry=27815
UPDATE `trans_words` SET `content_loc11`='Hah! Nice to see those addlebrained mountaineers knew to hand the ale off to a real man to get the job done. Welcome to my survey. If you\'re of the mind to help Ironforge by takin\' over the intended jobs of some useless, lazy sods that call themselves dwarves, you\'re in the right place!' WHERE `word_id` = 178700; -- locales_quest - offerrewardtext : entry=25770
UPDATE `trans_words` SET `content_loc11`='Hah! She\'ll think twice before making fun of my ideas again!$B$BThanks for your help, $N. I couldn\'t have had so much fun without you!' WHERE `word_id` = 189093; -- locales_quest - offerrewardtext : entry=28722
UPDATE `trans_words` SET `content_loc11`='Hah! So you heard of my challenge, did you?$B$BWell sit down and listen. Have a drink, and savor it... because it might be your last.' WHERE `word_id` = 136145; -- locales_quest - offerrewardtext : entry=10371
UPDATE `trans_words` SET `content_loc11`='Hah! So you really sent some heads rolling, did you? It was said during the War of the Ancients that Lo\'Gosh fought demons for ten days solid. Hopefully you weren\'t fighting that long...' WHERE `word_id` = 176974; -- locales_quest - offerrewardtext : entry=25277
UPDATE `trans_words` SET `content_loc11`='Hah! The fool didn\'t destroy these orders.$B$BLet\'s see what we can learn...' WHERE `word_id` = 175136; -- locales_quest - offerrewardtext : entry=24634
UPDATE `trans_words` SET `content_loc11`='Hah! They\'ll think twice before making fun of my ideas again!$B$BThanks for your help, $N. I couldn\'t have had so much fun without you!' WHERE `word_id` = 139988; -- locales_quest - offerrewardtext : entry=5163
UPDATE `trans_words` SET `content_loc11`='Hah! Think they got a kick out of seeing how low they were on our list of threat assessments! This document was admittedly a bit out of date, but none the less amusing. Of course, we\'ll offer you some money as a reward for returning this anyway - your efforts are appreciated!' WHERE `word_id` = 172477; -- locales_quest - offerrewardtext : entry=13659
UPDATE `trans_words` SET `content_loc11`='HAH! Those naga have some balls on them! To think that they could take Southshore from us in our own territory! Such a preposterous notion.$B$B<Helcular laughs.>$B$BYou have done well to thwart their attack - though I do wonder if they could have survived for even a minute in the blight.' WHERE `word_id` = 187949; -- locales_quest - offerrewardtext : entry=28356
UPDATE `trans_words` SET `content_loc11`='Hah! We lost another one, eh? Those harpies are becoming a real nuisance.$B$BNo matter! There\'s work to be done. Lend a hand around here, will ya?' WHERE `word_id` = 159811; -- locales_quest - offerrewardtext : entry=12469
UPDATE `trans_words` SET `content_loc11`='Hah! Well done! I was starting to think no one would take down that monster!$B$BHere you are, $N. And thanks - that Gnoll was giving me a headache the size of Blackrock Spire!' WHERE `word_id` = 130883; -- locales_quest - offerrewardtext : entry=176
UPDATE `trans_words` SET `content_loc11`='Hah! Well, this is excellent news! I was starting to think that he would never be brought to justice!$B$BHere you are, $N... and thanks. News of Anrak\'s foul deeds boiled my blood!' WHERE `word_id` = 139921; -- locales_quest - offerrewardtext : entry=5147
UPDATE `trans_words` SET `content_loc11`='Hah! You did it, $N! The Twilight\'s Hammer will soon be crushed!' WHERE `word_id` = 143398; -- locales_quest - offerrewardtext : entry=8361
UPDATE `trans_words` SET `content_loc11`='Hah, you got them! How did you like the bomber? I hope you got the hang of it, because I have more missions for you...' WHERE `word_id` = 163707; -- locales_quest - offerrewardtext : entry=13373
UPDATE `trans_words` SET `content_loc11`='Hah, you got them! I could hear their scourge parts clatter off the mountain walls. Good work. We\'ll have more for you soon...' WHERE `word_id` = 163794; -- locales_quest - offerrewardtext : entry=13406
UPDATE `trans_words` SET `content_loc11`='Haha! Done! The shackles are done!$B$BIt\'s time, Lucien. It\'s time, Servo!$B$BAre you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, $N?$B$BI shall summon forth a powerful elemental now. This is a groundbreaking day for all of us.' WHERE `word_id` = 133471; -- locales_quest - details : entry=778
UPDATE `trans_words` SET `content_loc11`='Haha! Hah - HA! Night elf "mages" fleeing their own arcane creation. Your actions have made my month, $N. That\'s why we blood elves don\'t use arcane constructs anymore - they\'ve been outlawed for, oh, 1500 years. It\'s amusing to me to watch our foes repeat the mistakes of the past. "Mages." Indeed.' WHERE `word_id` = 174349; -- locales_quest - offerrewardtext : entry=14430
UPDATE `trans_words` SET `content_loc11`='Haha! I knew you couldn\'t resist some of this brew. Come back again anytime you want some more, $N. Just bring me more of the ingredients I had you collect.' WHERE `word_id` = 133602; -- locales_quest - offerrewardtext : entry=822
UPDATE `trans_words` SET `content_loc11`='HAHA! Look at you now, pathetic woman! I spit on your remains!$B$BThank you, $N. Thank you from the bottom of my heart! This is indeed a great day!$B$BI would give you a kingdom if it were in my power! But perhaps you will settle for this.$B$BHaha! Stupid blood elf, look at you now... in a burlap sack and missing your body! You should never have betrayed Belgrom!' WHERE `word_id` = 167481; -- locales_quest - offerrewardtext : entry=3507
UPDATE `trans_words` SET `content_loc11`='Haha! Off to Stormwind with you, $N. High Priestess Laurena wants you there to be tested again. Head to the Cathedral of Light and don\'t dally. There\'s a lot to do and more and more pressure\'s gonna fall on your shoulders the more powerful you get. It\'s the nature of our order--people start to look to you more often the more you prove yourself worthy.$B$BThe Light\'s with ya, you don\'t need me to tell you that.' WHERE `word_id` = 171416; -- locales_quest - details : entry=5699
UPDATE `trans_words` SET `content_loc11`='Haha! Thank you, $N! This will help us greatly. You\'re a boon to the Crossroads and to the Horde. If there is anything I can do for you, please, let me know.' WHERE `word_id` = 139686; -- locales_quest - offerrewardtext : entry=5041
UPDATE `trans_words` SET `content_loc11`='Haha! Thank you, $N! You\'ve done it! My father\'s spirit can now rest and I can live in peace.$B$BThank you again. If there is anything I can do for you, please, just ask.' WHERE `word_id` = 141284; -- locales_quest - offerrewardtext : entry=6389
UPDATE `trans_words` SET `content_loc11`='Haha! That\'ll teach those brutes to waste our time. From this day forth, green skin will strike fear into the hearts of all magnataur!' WHERE `word_id` = 161365; -- locales_quest - offerrewardtext : entry=12822
UPDATE `trans_words` SET `content_loc11`='Haha! Wonderful!$B$BI\'ll be sure to find out what this is for and why Magus Rimtori--she\'s the cow that hired me--wanted it. Hah! I got you now, stinkin\' Blood elves! Kim\'jael! Ha! I\'ll teach them who the rats are!$B$BYa did good, $N. Thanks a bundle. Here, take this coin and be off with ya--I\'ve got some things to figure out.' WHERE `word_id` = 140453; -- locales_quest - offerrewardtext : entry=5534
UPDATE `trans_words` SET `content_loc11`='Haha! You got them good, didn\'t you?!$B$BThis is great! That\'ll teach those Blood elves to betray their partners... especially someone as loyal as a goblin merchant! Bah, Blood elves...!$B$BWell, the least I can do for you is pay you for your time... just like I said I would.$B$BHere you go... those should be useful.' WHERE `word_id` = 138330; -- locales_quest - offerrewardtext : entry=3601
UPDATE `trans_words` SET `content_loc11`='Haha! You\'re doing very well for yourself, young $C.$B$BGiven time, infernals and dreadlords will bow before you!$B$BBut until that time comes, you must still rely on weapons forged by the hands of the mortal races.$B$BYou seem prepared for another such creation, and if you are willing, Menara Voidrender would speak with you! She is near Strahad\'s tower overlooking the port town of Ratchet. Go there when you are ready.' WHERE `word_id` = 139601; -- locales_quest - details : entry=4969
UPDATE `trans_words` SET `content_loc11`='Haha! You\'ve done it! Ya saved Narm, and ya found the proof me wife needs to take to the council. Yer a blessin\' o\' the Light if I ever saw one... not includin\' me wife o\' course.$B$BThank ya again, $N.' WHERE `word_id` = 136254; -- locales_quest - offerrewardtext : entry=1784
UPDATE `trans_words` SET `content_loc11`='Haha, good! Gahk like darkrunes! You take crystalforged darkrune dat Gahk make earlier.$B$B$N remember, control da degrader, den use hammer to smash da magic shield on Shartuul\'s transporter. Let out da other demon and fight him so you control him, too! Den smash and control more demons until no more come!$B$BDen you save Ogri\'la!' WHERE `word_id` = 153366; -- locales_quest - offerrewardtext : entry=11027
UPDATE `trans_words` SET `content_loc11`='Haha, I knew my note would not dissuade you from your path. So, you\'re prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?$B$BI will not lie, $N, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful.' WHERE `word_id` = 275814; -- locales_quest - offerrewardtext : entry=3104
UPDATE `trans_words` SET `content_loc11`='Haha... I never thought I\'d make more of this stuff ever again.$B$BYou\'ve stirred in me a great sense of nostalgia, $N. Kind of reminds me of the last time I blacked out from too much trogg ale. Thank you. The memories warm my stomach.' WHERE `word_id` = 133598; -- locales_quest - offerrewardtext : entry=821
UPDATE `trans_words` SET `content_loc11`='Hahah! It\'s HUGE! We\'ll have you take it back to Uncle Bedlam as soon as everything\'s cleaned up here and you\'re ready to go.' WHERE `word_id` = 174527; -- locales_quest - offerrewardtext : entry=14487
UPDATE `trans_words` SET `content_loc11`='Hahah! Sweet deal. I\'ll get the ball rolling on this. All I need now is to find a buyer and get the go-ahead from Uncle Bedlam. Here are your wages for your work here. Excellent work, soldier.' WHERE `word_id` = 174625; -- locales_quest - offerrewardtext : entry=24452
UPDATE `trans_words` SET `content_loc11`='Hahah! Wonderful show. That should be a proper welcome to the highlands.' WHERE `word_id` = 188694; -- locales_quest - offerrewardtext : entry=28592
UPDATE `trans_words` SET `content_loc11`='Hahaha, $N. Back for more? Good, I like to hear that.$B$BThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.$B$BMake sure they die painfully, $N. We want those harpy wenches to know the idiocy of picking fights with the Horde.' WHERE `word_id` = 133827; -- locales_quest - details : entry=875
UPDATE `trans_words` SET `content_loc11`='Hahaha, revenge is sweet!$B$BBut, T\'chali can see you be interested in moving on now that you help him get his revenge. I hear you, mon... life is for the living.$B$BTell you what, T\'chali got lots of goodies still left here in his grave. You pick the one you like best!' WHERE `word_id` = 151410; -- locales_quest - offerrewardtext : entry=10544
UPDATE `trans_words` SET `content_loc11`='Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!$B$BI don\'t care if you know Gaxim or not... I\'ll give you the stuff just to see you or them explode into itty bitty pieces.$B$BThere\'s a problem though: I\'m all out.$B$BBut I\'ll tell you what, you bring me the correct potions, and I\'ll make some up for you right away.$B$BThe least you can do is prove you\'ve got some skill as an alchemist before I just give you a sample of my greatest creation.' WHERE `word_id` = 134627; -- locales_quest - details : entry=1073
UPDATE `trans_words` SET `content_loc11`='Hah-har! So ol\' Gazzy ain\'t given up on his goods yet, has he? Well, looks like that ol\' floppy-eared goldgrubbler jes\' gave me somethin\' ta bargain with.' WHERE `word_id` = 173176; -- locales_quest - offerrewardtext : entry=14045
UPDATE `trans_words` SET `content_loc11`='Hail, $C!  I can tell by your demeanor that you\'ve seen and done much in this world. Yet I\'m willing to wager you haven\'t seen a piece of armor like this.$B$BPerform a small favor for me and I\'ll be willing to trade it to you for an ordinary set of bracers.$B$BI\'m in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus. Bring this to me along with a few gold coins and I\'ll perform the exchange.' WHERE `word_id` = 144539; -- locales_quest - details : entry=10493
UPDATE `trans_words` SET `content_loc11`='Hail, $C. I am charged to patrol this stretch of road. Although the road is safe for now, I\'ve seen gnoll encampments to the north and east of here.$B$BLakeshire must know of the gathering gnoll force!  Report to Deputy Feldon in Lakeshire and tell him of the gnolls. Do this, and I\'m sure Feldon will offer you a scout\'s wage.$B$BFeldon\'s usually inspecting the area south of the bridge to Lakeshire.' WHERE `word_id` = 131171; -- locales_quest - details : entry=244
UPDATE `trans_words` SET `content_loc11`='Hail, $C. I am Jin\'rokh the Breaker, troll of Mugamba. We of the Zandalar tribe recognize your accomplishments. We salute your tenacity and strength of will.$B$BWear this talisman around your neck, $C. Let the strength of Mount Mugamba flow through your being. Be empowered as you strike down our enemies!' WHERE `word_id` = 142733; -- locales_quest - offerrewardtext : entry=8041
UPDATE `trans_words` SET `content_loc11`='Hail, $C. Perhaps you\'ve seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn\'t enough manpower to spare so far from Darkshire.$B$BI hate to ask this of you, but you seem like you might be able to handle them. I can\'t promise you anything of great value, but I can reward you if you can help root out the filthy bugs.$B$BOh, and a word of advice, you\'ll want to avoid their venom if you can.' WHERE `word_id` = 131175; -- locales_quest - details : entry=245
UPDATE `trans_words` SET `content_loc11`='Hail, $N! It is good to see a $C like yourself, eager to do his part for the Horde. Speak with me again, for I have vital tasks for you...' WHERE `word_id` = 141879; -- locales_quest - offerrewardtext : entry=7123
UPDATE `trans_words` SET `content_loc11`='Hail, $N. I am pleased to see you, but regret that our meeting is not under more pleasant conditions.$B$BListen close, for I have a vital task for you...' WHERE `word_id` = 142120; -- locales_quest - offerrewardtext : entry=7494
UPDATE `trans_words` SET `content_loc11`='Hail, $N. Nadun spoke highly of you. Are you here to aid us?' WHERE `word_id` = 189481; -- locales_quest - offerrewardtext : entry=28870
UPDATE `trans_words` SET `content_loc11`='Hail, $N. Praise to you, for my call for aid is now answered. Let us hope you are up to the task...' WHERE `word_id` = 136425; -- locales_quest - offerrewardtext : entry=1883
UPDATE `trans_words` SET `content_loc11`='Hail, $N. Thassarian mentioned you\'d be dropping by. Any friend of Thassarian\'s is my friend. Well, any living friend of Thassarian, that is... He does keep odd company.' WHERE `word_id` = 163758; -- locales_quest - offerrewardtext : entry=13386
UPDATE `trans_words` SET `content_loc11`='Hail, $N. There is much we need to talk about.$B$BI hope your mind is an open one. The decisions I make are not understood by many. Only my closest collaborators have understanding of the portents I see and the signs I await.$B$BWhen I joined forces with Illidan it was based on visions foretelling that otherwise my race would have been destroyed. I\'ve waited patiently for other signs and visions to come to pass... Velen\'s exodus... the opening of the Dark Portal... and now... your arrival.' WHERE `word_id` = 151769; -- locales_quest - offerrewardtext : entry=10628
UPDATE `trans_words` SET `content_loc11`='Hail, and well met, $N. I lead a group of adventurers investigating odd happenings in this area.$B$BMy cousin in Hillsbrad recently put down his dog Stanley because the animal mystically grew to an immense size and savagely attacked anyone who came near him.$B$BI believe the undead are involved, and we\'re looking for signs to prove as much.$B$BTwo of my companions, Quae and Kinelory, headed to the Go\'Shek Farm in the Arathi Highlands, and haven\'t checked in for days. Find them for me? I grow concerned.' WHERE `word_id` = 132958; -- locales_quest - details : entry=659
UPDATE `trans_words` SET `content_loc11`='Hail, death knight. I am the blood lord, Keleseth, ruler of the southeastern reaches of Northrend. The Lich King has sought to utilize my talents in ending this mortal affront to the Scourge. As with all things the Lich King asks of me, I am happy to oblige. Of course, a sea of endless souls to sate my thirst certainly sweetened the deal, don\'t you think?' WHERE `word_id` = 336062; -- locales_quest - offerrewardtext : entry=12715
UPDATE `trans_words` SET `content_loc11`='Hail, young $C. I see you found your way to my doorstep.' WHERE `word_id` = 133462; -- locales_quest - offerrewardtext : entry=775
UPDATE `trans_words` SET `content_loc11`='Hail, young $R. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.$B$BTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.$B$BIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.' WHERE `word_id` = 134208; -- locales_quest - details : entry=965
UPDATE `trans_words` SET `content_loc11`='Hair Samples Collected' WHERE `word_id` = 160526; -- locales_quest - ObjectiveText1 : entry=12630
UPDATE `trans_words` SET `content_loc11`='Hall of Masks found' WHERE `word_id` = 185462; -- locales_quest - EndText : entry=27704
UPDATE `trans_words` SET `content_loc11`='Hameya\'s chest is opened!!' WHERE `word_id` = 140868; -- locales_quest - offerrewardtext : entry=6024
UPDATE `trans_words` SET `content_loc11`='Hammertoe\'s alive?! This is amazin\', $N!' WHERE `word_id` = 133231; -- locales_quest - offerrewardtext : entry=720
UPDATE `trans_words` SET `content_loc11`='Hammertoe\'s amulet? I think my spirits were higher when I thought he was dead. Knowin\' fer sure only makes the pain worse. This amulet was his life\'s work. I can\'t let his death be in vain.' WHERE `word_id` = 133243; -- locales_quest - offerrewardtext : entry=723
UPDATE `trans_words` SET `content_loc11`='Hand them over. I will sift through the useless ones and if there\'s anything actionable, I will call upon you.$B$BEither way, return tomorrow. It is well known that they change their plans on a daily basis.' WHERE `word_id` = 161436; -- locales_quest - offerrewardtext : entry=12838
UPDATE `trans_words` SET `content_loc11`='Handmaiden Of Elune Visited' WHERE `word_id` = 174079; -- locales_quest - ObjectiveText1 : entry=14354
UPDATE `trans_words` SET `content_loc11`='Hanging from beneath its fronds of this glowing plant is a large, round fruit.$B$BDenalan would want to study this fruit, you are certain.' WHERE `word_id` = 134062; -- locales_quest - details : entry=930
UPDATE `trans_words` SET `content_loc11`='Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.$B$BReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.' WHERE `word_id` = 142383; -- locales_quest - objectives : entry=7724
UPDATE `trans_words` SET `content_loc11`='Hansel Heavyhands wants you to kill 20 Heavy War Golems.$B$BThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you\'ve killed enough, return to Hansel in Searing Gorge.' WHERE `word_id` = 142378; -- locales_quest - objectives : entry=7723
UPDATE `trans_words` SET `content_loc11`='Hansel Heavyhands wants you to kill 20 Incendosaurs.$B$BYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.$B$BReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.' WHERE `word_id` = 142398; -- locales_quest - objectives : entry=7727
UPDATE `trans_words` SET `content_loc11`='Har har, that sounds like quite a heap you built there. Did they take to it? Good, good! Let\'s see if my plan comes to fruition. What have I done?' WHERE `word_id` = 172780; -- locales_quest - offerrewardtext : entry=13910
UPDATE `trans_words` SET `content_loc11`='Har! My men could learn a lot by watching you work. Well done.' WHERE `word_id` = 188041; -- locales_quest - offerrewardtext : entry=28379
UPDATE `trans_words` SET `content_loc11`='Har\'koa wants you to speak with Tol\'mar at Dubra\'jin.' WHERE `word_id` = 162539; -- locales_quest - objectives : entry=13097
UPDATE `trans_words` SET `content_loc11`='Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun\'s Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate\'s corpse.' WHERE `word_id` = 154527; -- locales_quest - objectives : entry=11538
UPDATE `trans_words` SET `content_loc11`='Harbingers of doom are nothing new on the streets of Stormwind, but I\'m worried about the most recent ones. They\'ve set up shop all over Old Town and they seem well coordinated.$B$BI\'ve thought about rounding them up or otherwise disrupting their activities, but that will just drive them underground. We need to find out as much as we can about them. Would you go to Old Town, hear what idea these doomsayers are spreading, and see if you can collect any of their leaflets?' WHERE `word_id` = 171805; -- locales_quest - details : entry=25253
UPDATE `trans_words` SET `content_loc11`='Hard work is something I have great respect for, $N. Now we can move forward with our plans for Winterspring.' WHERE `word_id` = 139281; -- locales_quest - offerrewardtext : entry=4721
UPDATE `trans_words` SET `content_loc11`='Harmless pumpkins, right?  Or so it would seem. If we are to defeat Arthas\'s advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath.$B$BWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady. This pumpkin, laced with my latest formula, will prove to be quite a treat.$B$BYet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow\'s End Tavern. Take this pumpkin to the fool.' WHERE `word_id` = 131864; -- locales_quest - details : entry=407
UPDATE `trans_words` SET `content_loc11`='Harness 5 Children.' WHERE `word_id` = 189662; -- locales_quest - objectives : entry=29044
UPDATE `trans_words` SET `content_loc11`='Harrison has escorted you to safety.' WHERE `word_id` = 158452; -- locales_quest - EndText : entry=12082
UPDATE `trans_words` SET `content_loc11`='Harrison is thinking...' WHERE `word_id` = 187480; -- locales_quest - ObjectiveText1 : entry=28240
UPDATE `trans_words` SET `content_loc11`='Harrison sent you, hmm? How fortunate!' WHERE `word_id` = 187696; -- locales_quest - offerrewardtext : entry=28295
UPDATE `trans_words` SET `content_loc11`='Harvest Collector Rewired' WHERE `word_id` = 158241; -- locales_quest - ObjectiveText1 : entry=12035
UPDATE `trans_words` SET `content_loc11`='Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.' WHERE `word_id` = 142250; -- locales_quest - objectives : entry=7634
UPDATE `trans_words` SET `content_loc11`='Hatchlings Redeemed' WHERE `word_id` = 152666; -- locales_quest - ObjectiveText1 : entry=10861
UPDATE `trans_words` SET `content_loc11`='Hatecrest Naga killed' WHERE `word_id` = 177051; -- locales_quest - ObjectiveText1 : entry=25305
UPDATE `trans_words` SET `content_loc11`='Haughty Modiste wants you to collect 20 Southsea Pirate Hats and return them to her at Steamwheedle Port in Tanaris.' WHERE `word_id` = 143411; -- locales_quest - objectives : entry=8365
UPDATE `trans_words` SET `content_loc11`='Haunted? Ye could say that!' WHERE `word_id` = 188874; -- locales_quest - offerrewardtext : entry=28635
UPDATE `trans_words` SET `content_loc11`='Have a joyous Feast of Great-Winter from your friends at Smokeywood Pastures.' WHERE `word_id` = 144276; -- locales_quest - offerrewardtext : entry=8769
UPDATE `trans_words` SET `content_loc11`='Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who\'s currently in Orgrimmar!  If you\'ve been nice this year, you\'ll receive wondrous treats on the day of the Feast of Winter Veil. Be sure to tell him what you hope to get this year!$B$BAlso, be sure to stock up on treats to give those who\'ve been nice this year. We have a great selection to choose from. Fresh from our farm to your plate - it\'s Smokywood Pastures wholesome goodness!' WHERE `word_id` = 141760; -- locales_quest - details : entry=7021
UPDATE `trans_words` SET `content_loc11`='Have Daranelle analyze the Kaliri aura' WHERE `word_id` = 151457; -- locales_quest - ObjectiveText1 : entry=10556
UPDATE `trans_words` SET `content_loc11`='Have Grek Test Olemba Oil' WHERE `word_id` = 150058; -- locales_quest - ObjectiveText1 : entry=10201
UPDATE `trans_words` SET `content_loc11`='Have our leaders finally heard my pleas? We\'re down to just a handful of pilots and mountaineers to defend Loch Modan.' WHERE `word_id` = 188607; -- locales_quest - offerrewardtext : entry=28567
UPDATE `trans_words` SET `content_loc11`='Have the first look at my new invention, $N. All you need to do is target whatever it is you\'d like to take a picture of, and push the button.$B$BWhat was that creature from the Hinterlands that you mentioned? Gammerita? Well, good luck finding her. I\'m sure Daryn will be quite pleased with the snapshot you return to her.$B$BIn any case, here\'s the Super Snapper. Have fun!' WHERE `word_id` = 137508; -- locales_quest - details : entry=2944
UPDATE `trans_words` SET `content_loc11`='Have we run so low on able soldiers that Nefarian is sending me whelps? You will never pass my tests, broodling.' WHERE `word_id` = 141466; -- locales_quest - offerrewardtext : entry=6570
UPDATE `trans_words` SET `content_loc11`='Have you been in contact with a druid of the talon recently, $C? I can feel the lingering presence of one.' WHERE `word_id` = 183579; -- locales_quest - offerrewardtext : entry=27129
UPDATE `trans_words` SET `content_loc11`='Have you brought the Ingredients for the draught? <Morthis considers you somewhat skeptically.>$B$BI have long searched for an apprentice to pass my knowledge to. Though the Druids of the Talon are no longer a formal group, I shall remain one to the last of my days.$B$BI accept you as my apprentice from this moment forward. For my part, I will teach you the secrets of the stormcrow. For your part, you must be prepared to do all I ask. Do you understand?' WHERE `word_id` = 153059; -- locales_quest - offerrewardtext : entry=10955
UPDATE `trans_words` SET `content_loc11`='Have you brought the Ingredients for the draught? Take care not to get pollen on me, please. I sneeze uncontrollably in its presence.$B$B<Morthis sniffs at the indignity represented by a sneeze.>$B$B<Morthis accepts the herbs from you, inspecting them. Producing a vial, he begins mixing the potion.>$B$BThis will only take a moment, $N. Then, you must travel to Moonglade.' WHERE `word_id` = 153083; -- locales_quest - offerrewardtext : entry=10961
UPDATE `trans_words` SET `content_loc11`='Have you come here to spy on me? No?$B$BPerhaps you have an appreciation for fine cuisine, then? Good, you can help!' WHERE `word_id` = 154093; -- locales_quest - offerrewardtext : entry=11225
UPDATE `trans_words` SET `content_loc11`='Have you come to assist me with my work? My claws are quite dexterous, but I must reluctantly confess that my arms are debilitatingly short.' WHERE `word_id` = 174375; -- locales_quest - offerrewardtext : entry=14442
UPDATE `trans_words` SET `content_loc11`='Have you come to free me?' WHERE `word_id` = 132697; -- locales_quest - offerrewardtext : entry=26603
UPDATE `trans_words` SET `content_loc11`='Have you come to help us against the Wildhammers? The Warchief knows that what happens here will be important to the Horde\'s future.' WHERE `word_id` = 188624; -- locales_quest - offerrewardtext : entry=28574
UPDATE `trans_words` SET `content_loc11`='Have you come to help us fight back against the forces of the Horde? Every blade and spell will be needed!' WHERE `word_id` = 188335; -- locales_quest - offerrewardtext : entry=28492
UPDATE `trans_words` SET `content_loc11`='Have you come with news of Dogran? He was to have returned days ago, and I have heard nothing...' WHERE `word_id` = 135849; -- locales_quest - offerrewardtext : entry=1508
UPDATE `trans_words` SET `content_loc11`='Have you considered a career in science, $N?  If you ever get tired of this $C nonsense, come see me!  I could use an assistant with your devotion to experimentation and the scientific method.' WHERE `word_id` = 179926; -- locales_quest - offerrewardtext : entry=26106
UPDATE `trans_words` SET `content_loc11`='Have you done that before? Your skill with my machete seemed practiced.$B$B<The brave looks at you warily.>$B$BI\'ll take it back from you now, $C.' WHERE `word_id` = 155174; -- locales_quest - offerrewardtext : entry=11257
UPDATE `trans_words` SET `content_loc11`='Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.$B$BIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.' WHERE `word_id` = 275977; -- locales_quest - details : entry=6541
UPDATE `trans_words` SET `content_loc11`='Have you ever heard the saying "survival of the fittest?" What you\'re doing conflicts with natural law, $G buddy:lady;! This idiot should have died in the mines. There\'s no telling what kind of harm he\'ll cause to himself or another person now that you\'ve saved him from his inevitable demise.$B$BAnd you know who\'s fault that\'ll be, right?' WHERE `word_id` = 187115; -- locales_quest - offerrewardtext : entry=28156
UPDATE `trans_words` SET `content_loc11`='Have you ever noticed the behavior of the Lost Ones in Tuurem? They wander the ruins, searching for surviving scraps of anything made by the draenei.$B$BTheir Broken masters know better. They\'ve left their former lives and identities behind and become something completely different.$B$BI believe we can use the Lost Ones\' compulsion to our benefit and gather old draenei relics from them. Why risk life and limb battling the Broken, when we can profit from picking our targets wisely?' WHERE `word_id` = 169972; -- locales_quest - details : entry=10032
UPDATE `trans_words` SET `content_loc11`='Have you ever seen a helboar fly? They don\'t even need wings!$B$B<Watch Commander Krunk laughs.>$B$BThe fight against the Legion camps to the north has depleted our supplies, including catapult ammunition. This is the perfect opportunity to try something new.$B$BInstead of using boulders, I want to try igniting the corpses of the starving helboars I\'ve seen around the eastern ruins and use them to bombard the Legion\'s camps.$B$BAre you going to volunteer, or do I have to order you?' WHERE `word_id` = 146695; -- locales_quest - details : entry=9346
UPDATE `trans_words` SET `content_loc11`='Have you ever seen Dreadnaught armor, $C? No, of course you haven\'t. You\'re still a $G boy:girl; - a tyke. Let me tell you, it is glorious.$B$BYou\'re probably asking yourself what any of this has to do with you, right? I\'ll tell you what, scrub; I need Dark Iron scraps and I\'m willing to pay to get my hands on as many as possible.$B$BI need the scraps to put together sets of Dreadnaught for our champions. Bring me scraps and get paid.' WHERE `word_id` = 145071; -- locales_quest - details : entry=9131
UPDATE `trans_words` SET `content_loc11`='Have you ever seen Thistleshrub Valley? It\'s a mighty dangerous place, $N.$B$BThose strange beasts there, I don\'t trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that\'s what I think they were called...$B$BAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there\'s no way I\'m going back there. But here\'s where you come in -- if you clear some of them out, I just might think about going back. What do you think, $N? Help me out?' WHERE `word_id` = 137982; -- locales_quest - details : entry=3362
UPDATE `trans_words` SET `content_loc11`='Have you ever watched them in battle, $N? The scorpoks, I mean. Have you ever seen the grace and agility with which they move? The decisiveness of their strikes?$B$BIf only we could somehow isolate that agility and encapsulate it, we would be wealthy beyond our... I mean... it would be a boon for the scientific community.$B$BAssist me, $N, and I shall allow you a sampling of the assay.$B$BIn order to create a stable sample, I will need three scorpok pincers, two vulture gizzards, and one blasted boar lung.' WHERE `word_id` = 136950; -- locales_quest - details : entry=2585
UPDATE `trans_words` SET `content_loc11`='Have you felt the cold chill? Perhaps what you thought was a hand on your shoulder? That was not your mind playing tricks on you, $R. The land is haunted. Ghosts litter the landscape, stuck here for all eternity.$B$BWould you like to see them? Are you sure about that? These types of things tend to change a person - and not for the better.$B$BVery well, I will need you to collect for me the ever-burning ash that is found near any of the fel lava pools of western Shadowmoon. Anywhere near green lava...' WHERE `word_id` = 273304; -- locales_quest - details : entry=10624
UPDATE `trans_words` SET `content_loc11`='Have you heard enough? Are you a $G man:woman; of action?$B$BThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol\'thar. With the Prince\'s power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.' WHERE `word_id` = 142056; -- locales_quest - details : entry=7461
UPDATE `trans_words` SET `content_loc11`='Have you heard enough? Are you prepared to act?' WHERE `word_id` = 138078; -- locales_quest - offerrewardtext : entry=3441
UPDATE `trans_words` SET `content_loc11`='Have you heard of the bloodcurse, landlubber? No, of course you haven\'t. The bloodcurse is what sunk all these ships. The spoiled, desecrated part of the water here is known as Bloodcursed Reef - a part of the world you never want to visit. I\'ve been here myself for 20 years.$B$BScurvy my foot! I died on these wild shores as food for the dragons... Ah, but that\'s another story for another time. Right now, we have to help the poor souls that are trapped in that reef.' WHERE `word_id` = 335126; -- locales_quest - offerrewardtext : entry=9672
UPDATE `trans_words` SET `content_loc11`='Have you heard of the Un\'Goro Crater, $N? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.$B$BIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.$B$BI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.' WHERE `word_id` = 139026; -- locales_quest - details : entry=4294
UPDATE `trans_words` SET `content_loc11`='Have you heard? The General never made it! Killed in the field, like some kind of dog!' WHERE `word_id` = 176248; -- locales_quest - offerrewardtext : entry=25074
UPDATE `trans_words` SET `content_loc11`='Have you mastered the use of Arcane Missiles already? You are a quick study in the arcane arts and you have a promising future ahead. Don\'t forget to return to me for training as you grow in power.' WHERE `word_id` = 182760; -- locales_quest - offerrewardtext : entry=26916
UPDATE `trans_words` SET `content_loc11`='Have you met Sister Aquinne? She and I grew up together in Dolanaar, and she recently came to the city to study at the Temple of the Moon. We decided to go for a boat ride, but the clumsy oarsman managed to capsize the craft!$B$BWhen we got back to the shore, Aquinne\'s moon pendant was missing. The lakes in Darnassus are full of giant catfish who will gobble up anything shiny!$B$BI\'ve been catching them nonstop, hoping to find the one with her pendant. I don\'t suppose you want to help?' WHERE `word_id` = 190238; -- locales_quest - details : entry=29324
UPDATE `trans_words` SET `content_loc11`='Have you met the Brassbolts brothers?  They\'re over in the Shimmering Flats, in Kalimdor, racing their rocket car against the goblins. They usually win which is no surprise--the goblin car blows up so much it barely ever crosses the finish line!$B$BBut even then, the Brassbolts brothers are always looking for new ways to make their car go faster, and Wizzle told me he needs a very rare component for his next experiment.$B$BHe probably needs help getting that part. Speak to him and find out.' WHERE `word_id` = 137166; -- locales_quest - details : entry=2769
UPDATE `trans_words` SET `content_loc11`='Have you noticed the abandoned camp to the south of here? It looks like the wildkin went crazy and destroyed just about everything they could find!$B$BI heard a rumor that one of the survivors of the attack is resting at Starfall Village, west of here. I\'m sure curious about what happened... aren\'t you?' WHERE `word_id` = 141507; -- locales_quest - details : entry=6604
UPDATE `trans_words` SET `content_loc11`='Have you seen the swamp gas?  Isn\'t it just shiny?$B$BIt takes a Zapthrottle Mote Extractor to suck \'em dry though. I could give you the plans to make one, but I really need some spare parts to fix stuff \'round here.$B$BLast time I checked, there were plenty of parts laying around near the steam pump at the Dead Mire to the northeast. I think the withered giants broke the pump out there.$B$BShall we help each other out?' WHERE `word_id` = 147789; -- locales_quest - details : entry=9636
UPDATE `trans_words` SET `content_loc11`='Have you spent many days in the Badlands, $C?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It\'s time you did.$B$BCrag coyotes are a tough breed. Tough, and bold enough to creep into Kargath and steal from our food supplies. Help rid the outpost of these thieves!$B$BHunt crag coyotes, $N. Hunt them and bring me their jawbones. Bring me enough, and maybe I\'ll believe it when you say you know the Badlands.' WHERE `word_id` = 135528; -- locales_quest - details : entry=1419
UPDATE `trans_words` SET `content_loc11`='Have you tried the cranberry chutney yet? It\'s made with fresh tangy Southfury cranberries. Just pick some up from the Pilgrim\'s Bounty vendor if you want to try your hand at making chutney.$B$BThe recipe should be in your bountiful cookbook.$B$BIf you\'ve got some extra time on your hands, would you mind making some of the chutney and bringing it to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff.' WHERE `word_id` = 164630; -- locales_quest - details : entry=14041
UPDATE `trans_words` SET `content_loc11`='Have Zamek create a diversion, then steal Rizzle\'s plans for Pozzik on the Shimmering Flats.' WHERE `word_id` = 135097; -- locales_quest - objectives : entry=1190
UPDATE `trans_words` SET `content_loc11`='Havenshire is ours! A thousand corpses litter the ground, patiently awaiting rebirth. We strike now at our enemy with the awakened strength of the Scourge!$B$BThe ghouls have already begun their assault upon New Avalon. Our forces have moved in behind them and taken the Crypt of Remembrance.' WHERE `word_id` = 160936; -- locales_quest - offerrewardtext : entry=12714
UPDATE `trans_words` SET `content_loc11`='Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest. Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron.' WHERE `word_id` = 131515; -- locales_quest - details : entry=324
UPDATE `trans_words` SET `content_loc11`='Hazlek rescued' WHERE `word_id` = 190129; -- locales_quest - ObjectiveText1 : entry=29217
UPDATE `trans_words` SET `content_loc11`='Hazzali Silithid slain' WHERE `word_id` = 175682; -- locales_quest - ObjectiveText1 : entry=24932
UPDATE `trans_words` SET `content_loc11`='He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.' WHERE `word_id` = 154028; -- locales_quest - offerrewardtext : entry=11204
UPDATE `trans_words` SET `content_loc11`='He can only drink so much. The rest might be used for washing his body, after...' WHERE `word_id` = 186189; -- locales_quest - offerrewardtext : entry=27909
UPDATE `trans_words` SET `content_loc11`='He got just what he deserved. There, there, don\'t cry. You\'ll find someone else that\'ll treat you right. Here, let me take that... we wouldn\'t want people to think that you\'re crazy.' WHERE `word_id` = 176715; -- locales_quest - offerrewardtext : entry=25202
UPDATE `trans_words` SET `content_loc11`='He has escaped! I should have known it would not be so easy. The path is clear, $N. It is time to return.' WHERE `word_id` = 185716; -- locales_quest - offerrewardtext : entry=27773
UPDATE `trans_words` SET `content_loc11`='He is dead! Khan Hratha is dead! And now the Maraudine will fall! When the Gelkis rule this land, $N, we will remember you. And the spirits of the earth will sing your name for all time.' WHERE `word_id` = 135453; -- locales_quest - offerrewardtext : entry=1380
UPDATE `trans_words` SET `content_loc11`='He is dead, then? Your justice was swift, $N. I pray to the Light that I never become your quarry!$B$B<He laughs and claps you on the shoulder.>$B$BI mean no criticism, $N. How could I, being the master of all assassins? But in truth, you have done the people of Stormwind a great service, and for that, I thank you.' WHERE `word_id` = 131820; -- locales_quest - offerrewardtext : entry=394
UPDATE `trans_words` SET `content_loc11`='He is gone. He is right. I must be strong for him...' WHERE `word_id` = 186199; -- locales_quest - offerrewardtext : entry=27911
UPDATE `trans_words` SET `content_loc11`='He is redeemed, $N. He now returns to the Dream to right what he alone has done wrong. Eranikus will be a powerful ally to Malfurion and my father.$B$BThese armaments are for you, $N; given to me by Ysera herself. You would do well to make use of them in your battles against the Qiraji.' WHERE `word_id` = 144209; -- locales_quest - offerrewardtext : entry=8736
UPDATE `trans_words` SET `content_loc11`='He musta really been off his rocker when he wrote this! Omarion and I - we were thick as thieves!$B$BAnyhow, this certainly opens up some new possibilities, $N. I am now able to craft more items - for a small fee and material charges, of course.' WHERE `word_id` = 145238; -- locales_quest - offerrewardtext : entry=9233
UPDATE `trans_words` SET `content_loc11`='He really said all of that? Wow, I can\'t believe he\'s going to call off the spectral assassins and stalkers, even if he did hint at causing my living companions further harm in the future.$B$BThis is a great day, $N! You\'ve accomplished what few ever could, and absolved us, at least in part, of some of our past sins.$B$BThank you! As a sign of appreciation, I\'d like to give you this. You can use it to summon forth spirits at the same haunted locations that you already have, and a few others, too.' WHERE `word_id` = 144772; -- locales_quest - offerrewardtext : entry=8996
UPDATE `trans_words` SET `content_loc11`='He teleported away? Mentioned Darkblaze? What the hell is going on here. Looks like it\'s time to strap in and finish this nonsense.' WHERE `word_id` = 182003; -- locales_quest - offerrewardtext : entry=26694
UPDATE `trans_words` SET `content_loc11`='He was a good goblin, young Scrimshank. Let\'s hope that his demise was not in vain by what he was able to record with his surveying equipment.$B$BIt seems as though we have quite the situation on our hands here with these bugs. They\'re way too cunning for their own good, and the research we\'ve done so far is shaping up to indicate that they might even be under the controlling influence of a third party!  If this is the case, then it bodes ill for not only Gadgetzan, but the whole desert!' WHERE `word_id` = 130182; -- locales_quest - offerrewardtext : entry=10
UPDATE `trans_words` SET `content_loc11`='He was a good soldier.' WHERE `word_id` = 191263; -- locales_quest - offerrewardtext : entry=29649
UPDATE `trans_words` SET `content_loc11`='He was a hero among heroes, Uther was. I can\'t even begin to imagine the anguish of what he felt when Arthas - his greatest student and someone whom Uther loved like his own son - betrayed all of humanity. Still, he rose to try and stop Arthas, and for that he will be forever remembered as a true paladin. His fight was to the end, thinking only of those he might save.$B$BThank you, $N. You\'ve paid tribute to a great hero today, honoring his spirit and the spirit of the Harvest Festival.' WHERE `word_id` = 276031; -- locales_quest - offerrewardtext : entry=8149
UPDATE `trans_words` SET `content_loc11`='He was controlling a sea giant? Fascinating. If we\'d managed to investigate further... Oh, I mean, wow, that\'s totally crazy! But thank goodness he\'s gone, hooray! Mister Noggenfogger will be so pleased. Here\'s a nice big reward, you!' WHERE `word_id` = 176568; -- locales_quest - offerrewardtext : entry=25166
UPDATE `trans_words` SET `content_loc11`='He was killed by this weapon?  It can\'t be!$B$BHave we... found them?' WHERE `word_id` = 146865; -- locales_quest - offerrewardtext : entry=9401
UPDATE `trans_words` SET `content_loc11`='He was stationed at Camp Taurajo, where we\'ve been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.$B$BThey sent a message here, requesting a healing draught from the trolls at the Malaka\'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven\'t returned yet.' WHERE `word_id` = 135854; -- locales_quest - details : entry=1510
UPDATE `trans_words` SET `content_loc11`='He wasn\'t the first of those sissy spell casters to betray us, and he certainly won\'t be the last. Damned shame, too... He was one of our best mages. He\'d summon a buffet that would make your mouth water and your heart jump for joy...$B$BBAH!' WHERE `word_id` = 335841; -- locales_quest - offerrewardtext : entry=12089
UPDATE `trans_words` SET `content_loc11`='He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.$B$BBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.$B$BOh, and check the north wing.' WHERE `word_id` = 142084; -- locales_quest - details : entry=7485
UPDATE `trans_words` SET `content_loc11`='He will be back, but for now the Legion\'s war against Lord Illidan is weakened. He shall know of your deeds, captain.' WHERE `word_id` = 153630; -- locales_quest - offerrewardtext : entry=11090
UPDATE `trans_words` SET `content_loc11`='He, uh... he said what? THEY\'RE GONNA GO AFTER AREA 52?!$B$BOh, this is not good... not good!' WHERE `word_id` = 150207; -- locales_quest - offerrewardtext : entry=10235
UPDATE `trans_words` SET `content_loc11`='He\'s a fine specimen and will serve us well.$B$BNow, we have to make sure to use him properly to trap Vardmadra!' WHERE `word_id` = 162711; -- locales_quest - offerrewardtext : entry=13133
UPDATE `trans_words` SET `content_loc11`='He\'s dead! Thank the Makers...$B$BI don\'t like the looks of them, lad. The Dark Iron I\'ve tussled with were never this crazy. Something\'s getting to these sods...' WHERE `word_id` = 178735; -- locales_quest - offerrewardtext : entry=25780
UPDATE `trans_words` SET `content_loc11`='He\'s done it this time! Bad enough that Gelriz\'s muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!$B$BRevilgaz won\'t have it, and he\'s told me to take care of the problem in my own way.$B$BMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don\'t care what you have to do to get them.' WHERE `word_id` = 131046; -- locales_quest - details : entry=213
UPDATE `trans_words` SET `content_loc11`='He\'s gone mad, apparently.$B$B<Maxwell lowers his head in mourning.>$B$BIt is unfortunate that a once proud and noble warrior would be turned into a blithering head case. I GUESS we\'ve reached a dead end...$B$BI must reward you for your efforts thus far, $N.' WHERE `word_id` = 138914; -- locales_quest - offerrewardtext : entry=4242
UPDATE `trans_words` SET `content_loc11`='He\'s gone? Did he have the sword? Nah...don\'t tell me. Don\'t matter no more. Mazoga don\'t care. I\'m off now, mon. De consequences of my actions await me. Take whatever I was holdin\'... I don\'t need it where I\'m goin\'...' WHERE `word_id` = 183365; -- locales_quest - offerrewardtext : entry=27068
UPDATE `trans_words` SET `content_loc11`='Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin\' learned more soon. That should please him greatly.' WHERE `word_id` = 135072; -- locales_quest - details : entry=1184
UPDATE `trans_words` SET `content_loc11`='Head out to where King Oremantle buried the second World Pillar fragment.' WHERE `word_id` = 182547; -- locales_quest - objectives : entry=26848
UPDATE `trans_words` SET `content_loc11`='Head to Bambala in Northern Stranglethorn Vale.' WHERE `word_id` = 190137; -- locales_quest - EndText : entry=29220
UPDATE `trans_words` SET `content_loc11`='Head to Fort Livingston in Northern Stranglethorn Vale.' WHERE `word_id` = 189795; -- locales_quest - EndText : entry=29102
UPDATE `trans_words` SET `content_loc11`='Head to Nesingwary\'s Expedition.' WHERE `word_id` = 189810; -- locales_quest - EndText : entry=29105
UPDATE `trans_words` SET `content_loc11`='Headhunters healed' WHERE `word_id` = 190141; -- locales_quest - ObjectiveText2 : entry=29221
UPDATE `trans_words` SET `content_loc11`='Heal and fortify Deathguard Kel' WHERE `word_id` = 140591; -- locales_quest - ObjectiveText1 : entry=5650
UPDATE `trans_words` SET `content_loc11`='Heal and fortify Grunt Kor\'ja' WHERE `word_id` = 140581; -- locales_quest - ObjectiveText1 : entry=5648
UPDATE `trans_words` SET `content_loc11`='Heal and fortify Guard Roberts' WHERE `word_id` = 140533; -- locales_quest - ObjectiveText1 : entry=5624
UPDATE `trans_words` SET `content_loc11`='Heal and fortify Mountaineer Dolf' WHERE `word_id` = 140537; -- locales_quest - ObjectiveText1 : entry=5625
UPDATE `trans_words` SET `content_loc11`='Heal and fortify Sentinel Shaya' WHERE `word_id` = 140519; -- locales_quest - ObjectiveText1 : entry=5621
UPDATE `trans_words` SET `content_loc11`='Heal Injured Draenei' WHERE `word_id` = 182982; -- locales_quest - ObjectiveText1 : entry=26970
UPDATE `trans_words` SET `content_loc11`='Heal Tavara' WHERE `word_id` = 147589; -- locales_quest - ObjectiveText1 : entry=9586
UPDATE `trans_words` SET `content_loc11`='Heal Wounded Brave' WHERE `word_id` = 183360; -- locales_quest - ObjectiveText1 : entry=27066
UPDATE `trans_words` SET `content_loc11`='Heal Wounded Outrunners' WHERE `word_id` = 169936; -- locales_quest - ObjectiveText1 : entry=10072
UPDATE `trans_words` SET `content_loc11`='Heal Wounded Sentinels' WHERE `word_id` = 182894; -- locales_quest - ObjectiveText1 : entry=26949
UPDATE `trans_words` SET `content_loc11`='Heal Wounded Trainee' WHERE `word_id` = 182772; -- locales_quest - ObjectiveText1 : entry=26919
UPDATE `trans_words` SET `content_loc11`='Heaped within this boat is a pile of wrapped corpses. And looking east across Lordamere Lake, an opposing dock on Fenris Isle can be seen.$B$BThe fate of the corpses must lie on Fenris Isle.' WHERE `word_id` = 132008; -- locales_quest - offerrewardtext : entry=438
UPDATE `trans_words` SET `content_loc11`='Hear about the World Pillar' WHERE `word_id` = 180386; -- locales_quest - ObjectiveText1 : entry=26243
UPDATE `trans_words` SET `content_loc11`='Hear my story, $R.' WHERE `word_id` = 137200; -- locales_quest - details : entry=2784
UPDATE `trans_words` SET `content_loc11`='Hear my tale, adventurer.' WHERE `word_id` = 138076; -- locales_quest - details : entry=3441
UPDATE `trans_words` SET `content_loc11`='Hear the Tale of the Blademaster' WHERE `word_id` = 149676; -- locales_quest - EndText : entry=10107
UPDATE `trans_words` SET `content_loc11`='Hear ye, hear ye!  All heroes are called upon to heed these words!$B$BA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!$B$BHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!' WHERE `word_id` = 139779; -- locales_quest - details : entry=10373
UPDATE `trans_words` SET `content_loc11`='Heard Westfall was in some deep doody. Well, we got our own set of problems here. See them gnolls out there? Looks like they\'re actin\' up again. I don\'t like it. Don\'t like it one bit.' WHERE `word_id` = 180852; -- locales_quest - offerrewardtext : entry=26365
UPDATE `trans_words` SET `content_loc11`='Hearing their screams... watching the last life fade from their wretched bodies... it\'s invigorating, is it not?$B$BI relish it.' WHERE `word_id` = 159260; -- locales_quest - offerrewardtext : entry=12264
UPDATE `trans_words` SET `content_loc11`='Heart of Arkkoroc identified' WHERE `word_id` = 174626; -- locales_quest - EndText : entry=24452
UPDATE `trans_words` SET `content_loc11`='Hearthglen Trainee challenged and defeated' WHERE `word_id` = 183670; -- locales_quest - ObjectiveText1 : entry=27156
UPDATE `trans_words` SET `content_loc11`='Heartrazor released' WHERE `word_id` = 186835; -- locales_quest - ObjectiveText1 : entry=28088
UPDATE `trans_words` SET `content_loc11`='Heartwood by nature is resistant to disease, rot and plague. This heartwood, however, goes so far as to repel such things! The masonry, affected by the fallout of the Unbound Thicket, will work in much the same way.$B$BSoon we will break ground.' WHERE `word_id` = 162696; -- locales_quest - offerrewardtext : entry=13130
UPDATE `trans_words` SET `content_loc11`='Heavens no!  Poor Rustlocke. \'Tis quite a tragedy indeed.$B$BWe must not let his death pass in vain. This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands.$B$BIf those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, $N!  Return to me when your mission is complete.$B$BYou\'re our only hope.' WHERE `word_id` = 132850; -- locales_quest - details : entry=633
UPDATE `trans_words` SET `content_loc11`='Heavy words, $N. If it were somebody else saying them, I\'d be likely to judge them insane.' WHERE `word_id` = 163675; -- locales_quest - offerrewardtext : entry=13363
UPDATE `trans_words` SET `content_loc11`='Heb\'Drakkar trolls scalped' WHERE `word_id` = 160664; -- locales_quest - ObjectiveText1 : entry=12659
UPDATE `trans_words` SET `content_loc11`='Heed me well, $N. For the banner to work in the desired way, you will need to step into the Ring of the Law in Blackrock Depths. Allow yourself to be sentenced by High Justice Grimstone and place the banner firmly on the ground in a sign of defiance.$B$BYour victim will not be able to restrain himself and shall enter the fray filled with a desire to fight you. Once you obtain that which you seek, go back to Anthion.' WHERE `word_id` = 144812; -- locales_quest - details : entry=9015
UPDATE `trans_words` SET `content_loc11`='Heed my words, young one - there is a taint about this island, and it is far more potent than the remnants of the Scourge.$B$BI believe there is a true demonic presence on the isle.$B$BWest of here are the spires of Falthrien Academy. The arcane wraiths that infest it are a window to the source of demonic power. You are to bring me the essences of tainted and untainted wraiths.$B$BIn exchange for your obedience, I\'ll teach you how to summon an imp companion - your first of many as a warlock.' WHERE `word_id` = 145954; -- locales_quest - details : entry=8344
UPDATE `trans_words` SET `content_loc11`='Heh heh, well done! And when you showed Shaky those giblets, how hard did he shake?$B$BHah! He\'s so easy to read, when I play cards with him I can\'t help but win!$B$BThanks for your help, $N. Now it\'s your turn to get paid...' WHERE `word_id` = 132753; -- locales_quest - offerrewardtext : entry=26594
UPDATE `trans_words` SET `content_loc11`='Heh heh, with all the races they\'re running here, it\'s no surprise that a few mishaps happen along the way. If you look around the Shimmering Flats then you\'ll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!$B$BAnd those parts are worth money to the gnomes and goblins. They\'re always looking for more contraptions to slap onto their cars.$B$BSo go out and get me parts. Bring me a heap and I\'ll pay you well.' WHERE `word_id` = 134791; -- locales_quest - details : entry=1110
UPDATE `trans_words` SET `content_loc11`='Heh, so old Verner needs some shoes, does he!?!' WHERE `word_id` = 130626; -- locales_quest - offerrewardtext : entry=118
UPDATE `trans_words` SET `content_loc11`='Heh, you\'re kidding, right? The Burning Legion is blaming us for all of that?$B$BBut YOU\'RE the one that did it!$B$BOy, I have a headache and it\'s as big as this rocket. Okay, okay, this calls for a change of plans.$B$BIf the Burning Legion thinks that it\'s going to come here, destroy our town and ruin my dream of cruising through the Twisted Nether, they are sadly mistaken.$B$BAnd I know just the goblin to help us out.' WHERE `word_id` = 150217; -- locales_quest - offerrewardtext : entry=10237
UPDATE `trans_words` SET `content_loc11`='Hehe, ethereal suckers!$B$BThanks for getting us these parts, $C. I bet we can just hook these babies right up inside the rocket. I wonder what they do?  Should be fun finding out!$B$BHmm, let me see if I can dig up some pocket change to throw your way.' WHERE `word_id` = 150085; -- locales_quest - offerrewardtext : entry=10206
UPDATE `trans_words` SET `content_loc11`='Hehe, oh yes... of course, the Carevins.$B$BNo, nothing\'s wrong but it is hard for me to go into town now. The roads are dangerous and I\'m not getting any younger. Maybe you can do an old man some favors?' WHERE `word_id` = 130834; -- locales_quest - offerrewardtext : entry=165
UPDATE `trans_words` SET `content_loc11`='Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.$B$BYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!$B$BAnd $N, be on the lookout for any information that might be laying about inside the room where Amarion resides.' WHERE `word_id` = 274489; -- locales_quest - details : entry=12311
UPDATE `trans_words` SET `content_loc11`='Helgrum wants a report, eh? I sent an outrunner to Stonard not three days past. Did he fail his mission? If Stonard does not have my report, then it appears he did fail.$B$BLet\'s hope the next runner I send has more skill, or more luck.' WHERE `word_id` = 135526; -- locales_quest - offerrewardtext : entry=1418
UPDATE `trans_words` SET `content_loc11`='Helix is the one responsible for the gnoll attacks? He\'s inside. He\'s been there for days. I\'ve just been waiting for an excuse to bust him.' WHERE `word_id` = 180554; -- locales_quest - offerrewardtext : entry=26289
UPDATE `trans_words` SET `content_loc11`='Helix? I\'ve heard that name before. Recently as a matter of fact, but who is this admiral?' WHERE `word_id` = 180542; -- locales_quest - offerrewardtext : entry=26286
UPDATE `trans_words` SET `content_loc11`='Helix\'s Secret Revealed' WHERE `word_id` = 180559; -- locales_quest - EndText : entry=26290
UPDATE `trans_words` SET `content_loc11`='Hell-Hoot is slain, and her meat is just as succulent as you\'d expect.$B$BToday, we eat a legend. Thank you, $N.' WHERE `word_id` = 189256; -- locales_quest - offerrewardtext : entry=28782
UPDATE `trans_words` SET `content_loc11`='Hellions & Wind Riders shot down' WHERE `word_id` = 172603; -- locales_quest - ObjectiveText1 : entry=13853
UPDATE `trans_words` SET `content_loc11`='Hello $N. Checking in on your Fire Lasher?$B$BHe seems quite hungry, but no mixture of fertilizer or plant growth seems to interest him.$B$BSome plants are carnivorous, and I\'d like to test this rather unconventional theory.$B$BWould you retrieve some Lava Burster Hearts for me? The Lava Bursters frequent the fields to the north.' WHERE `word_id` = 190531; -- locales_quest - details : entry=29256
UPDATE `trans_words` SET `content_loc11`='Hello $N. I have heard of your deeds from Darsok. You are a valuable $C of the Horde, indeed.' WHERE `word_id` = 189773; -- locales_quest - offerrewardtext : entry=29095
UPDATE `trans_words` SET `content_loc11`='Hello $N. You\'re here about the task I have, eh? It\'s good to see a young $R like yourself whose blood burns at the prospect of adventure!' WHERE `word_id` = 132138; -- locales_quest - offerrewardtext : entry=467
UPDATE `trans_words` SET `content_loc11`='Hello again, $C.$B$BI felt L\'ghorek die. A shame that such a magnificent being is gone.$B$BIf we do not assist Neptulon, we will all meet the same fate.' WHERE `word_id` = 180168; -- locales_quest - offerrewardtext : entry=26181
UPDATE `trans_words` SET `content_loc11`='Hello again, $N. How goes your studies of the Tome of Divinity?$B$BThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.$B$BBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.' WHERE `word_id` = 136008; -- locales_quest - offerrewardtext : entry=1642
UPDATE `trans_words` SET `content_loc11`='Hello again, $N. I know you\'ve been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you\'ve caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.' WHERE `word_id` = 140547; -- locales_quest - details : entry=5629
UPDATE `trans_words` SET `content_loc11`='Hello again, $R. I hear you were instrumental in our push toward Grim Batol - thank you! Alexstrasza has sanctified this ground in the hopes of luring Deathwing here. She\'ll perform a ceremony to lure him out... and then destroy him within this sacred circle. Let\'s hope her plan works.' WHERE `word_id` = 189060; -- locales_quest - offerrewardtext : entry=28712
UPDATE `trans_words` SET `content_loc11`='Hello again, Abyssmal. I am glad that you wish to speak to me once more concerning our neverending need for peacebloom. The war effort continues, and with it our production of potions and elixirs to aid in the battles to come. Will you help us again, $C? I am in need of the same amount of peacebloom as before, so if you can gather it up and return it to me here I would be most grateful. Of course, if you already have it on your person, I will be more than happy to accept it from you now' WHERE `word_id` = 143856; -- locales_quest - details : entry=8550
UPDATE `trans_words` SET `content_loc11`='Hello again, young $Gpriest:priestess;. The time has come for you to learn more about our religion. After you\'ve completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.' WHERE `word_id` = 140525; -- locales_quest - details : entry=5623
UPDATE `trans_words` SET `content_loc11`='Hello child.$B$BI understand Tirion\'s request and trust in his judgment, we will see what we can do for this Crusader Bridenbrad. What you ask is no simple task - the scourge are not of this world, and many have failed in attempting to strip their corruption over the years.$B$BIn a being of nobility and light, all is not without hope.' WHERE `word_id` = 162435; -- locales_quest - offerrewardtext : entry=13073
UPDATE `trans_words` SET `content_loc11`='Hello hello!  The Scourge to the south are digging up some ancient dragon thing. I could care less why they\'re doing it, but they\'re pulling cartloads of composite ore in the process.$B$BGo lift me a bunch of that ore. That stuff should yield a pretty penny for all the weapons the Horde are crafting.' WHERE `word_id` = 158276; -- locales_quest - details : entry=12044
UPDATE `trans_words` SET `content_loc11`='Hello hello, $N. Captain told me you\'re going after Negolash, eh?' WHERE `word_id` = 132785; -- locales_quest - offerrewardtext : entry=615
UPDATE `trans_words` SET `content_loc11`='Hello there - Lord Shadowbreaker sent me word ahead of time that you\'d be coming around this way to see me. I\'m willing to make the barding you need, but it won\'t be either cheap or easy; let\'s get that out in the open first and foremost.$B$BI will say this much, and Grayson will back me up when I make this claim... you\'ll not find better barding made anywhere in all of Azeroth than right here.' WHERE `word_id` = 142284; -- locales_quest - offerrewardtext : entry=7641
UPDATE `trans_words` SET `content_loc11`='Hello there! A new friend! So glad to meet you. My name is Ergll. The g is silent.' WHERE `word_id` = 173373; -- locales_quest - offerrewardtext : entry=14130
UPDATE `trans_words` SET `content_loc11`='Hello there, $G laddy:lass;! The mountaineers sent you over, eh? I do suspect we might have just the sort of work you\'re looking for. Welcome to the Farstrider Lodge!' WHERE `word_id` = 172437; -- locales_quest - offerrewardtext : entry=13647
UPDATE `trans_words` SET `content_loc11`='Hello there, $Gladdy:lassy;. Good to see you travelin\' far and wide to distant lands. No offense meant, but a lot o\' your kind don\'t take well to these cold climates usually. Glad to see you\'re made of tougher stuff.$B$BNot too long ago one of your priestesses was in here lookin\' for you--said somethin\' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.' WHERE `word_id` = 140548; -- locales_quest - details : entry=5630
UPDATE `trans_words` SET `content_loc11`='Hello there, $N. I\'ve heard much about your exploits, and must say I\'m honored to meet you. I don\'t suppose you\'ve heard the story of Ol\' Kelt? Ah, well, Ol\' Kelt--Kelt Thomasin, that is--was once considered one of the finest hunters in all the realm. There wasn\'t much he hadn\'t done, but then, one day, he became obsessed with an ancient story... a myth, really. Well, as the stories go, a huge threshadon lives in the waters of the lake. Hogwash, if you ask me. If you\'re interested, you might talk to Kelt.' WHERE `word_id` = 171287; -- locales_quest - details : entry=259
UPDATE `trans_words` SET `content_loc11`='Hello there. Am I dead? I think I am, because I\'m hovering over my body!$B$BOh, what an unfortunate turn of events. I was about to propose to Irena when the Scourge descended on us.$B$BI know that she\'s still alive... I can feel her in my heart.$B$B$C, do you think you might safely get me to her? The Scourge can still see my ghost, and no doubt can do horrible things to me.$B$BI\'d like to look upon her beautiful face one last time. You can tell her that I love her for me.' WHERE `word_id` = 155415; -- locales_quest - details : entry=11189
UPDATE `trans_words` SET `content_loc11`='Hello there. You must be... $N?' WHERE `word_id` = 175802; -- locales_quest - offerrewardtext : entry=24959
UPDATE `trans_words` SET `content_loc11`='Hello!  It\'s me. Hope you don\'t mind a little home-brewed magic to allow me to communicate with you in the field. It\'ll save us both some time. We\'re going to incorporate that living rot into a mixture that\'ll ruin their next batch of plague. That\'ll show them!' WHERE `word_id` = 184498; -- locales_quest - offerrewardtext : entry=27451
UPDATE `trans_words` SET `content_loc11`='Hello!$B$BOh, you spoke to my cousin Krazek?  How is he?  I hope Booty Bay is treating him well...$B$BScarab shells, you say?  Well... let me tell you a story...' WHERE `word_id` = 137318; -- locales_quest - offerrewardtext : entry=2864
UPDATE `trans_words` SET `content_loc11`='Hello, $C! Keegan Firebeard here has told me all about your heroics down south. Thank you for all of your efforts on behalf of the Wildhammer. I see Colin Thundermar is right behind you. The summit is ready to begin! Please stay and let\'s see how things unfold...' WHERE `word_id` = 187692; -- locales_quest - offerrewardtext : entry=28294
UPDATE `trans_words` SET `content_loc11`='Hello, $C! You\'re here for the scouting mission, are you? Very good!$B$BI hope your gear is in good condition, because this "scouting" mission has changed into something more messy...' WHERE `word_id` = 132142; -- locales_quest - offerrewardtext : entry=468
UPDATE `trans_words` SET `content_loc11`='Hello, $C. Is there something I can help you with?' WHERE `word_id` = 138645; -- locales_quest - offerrewardtext : entry=3942
UPDATE `trans_words` SET `content_loc11`='Hello, $C. What\'s that? You say that Shyela sent you? Very well, let\'s get started.' WHERE `word_id` = 172343; -- locales_quest - offerrewardtext : entry=13617
UPDATE `trans_words` SET `content_loc11`='Hello, $C.$B$BYou\'ll be escorting me to the excavation site? That\'s good to hear... After Saean and his cronies, who knows what else the Dark Irons might have up their sleeves?$B$BAnyways, let me just make some final checks. Talk to me again when you\'re ready to go.' WHERE `word_id` = 132082; -- locales_quest - offerrewardtext : entry=454
UPDATE `trans_words` SET `content_loc11`='Hello, $G sonny:lass;! You seem to have found one of our stolen documents, eh?$B$BThank you kindly for bringing it back to us. We\'ll gladly lend some coin as thanks for its return.' WHERE `word_id` = 172468; -- locales_quest - offerrewardtext : entry=13656
UPDATE `trans_words` SET `content_loc11`='Hello, $Ggood sir:my lady;!  Do you have a moment?$B$BMy brother and I run an apothecary in Stormwind, and I\'m here to gather large candles for their wax. Can you help me?$B$BYou can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines ... the Fargodeep mine to the south and Jasperlode Mine to the east. I suggest looking for candles in one of those places.' WHERE `word_id` = 130373; -- locales_quest - details : entry=60
UPDATE `trans_words` SET `content_loc11`='Hello, $N!  Glad to see you\'ve rejoined the caravan! Tarenar and Gidwin arrived here before you. Tarenar\'s just right there, and Gidwin\'s... well... he\'s in a little bit of a mood right now. I think he\'s in the tower.' WHERE `word_id` = 184568; -- locales_quest - offerrewardtext : entry=27466
UPDATE `trans_words` SET `content_loc11`='Hello, $N, I have been expecting you. I trust this day finds you well?' WHERE `word_id` = 147098; -- locales_quest - offerrewardtext : entry=9461
UPDATE `trans_words` SET `content_loc11`='Hello, $N. I am Bishop DeLavey.$B$BNo doubt if you\'re asking me about my business here in the keep then young Thomas has succeeded in requisitioning you to help our kingdom. He has always been adept at following my requests.$B$BI\'m afraid I don\'t have time to elaborate much, so allow me to be blunt... and please, try to keep this from becoming common knowledge.' WHERE `word_id` = 135305; -- locales_quest - offerrewardtext : entry=1274
UPDATE `trans_words` SET `content_loc11`='Hello, $N. I have indeed heard your name before, and although you are still full of youth, I am pleased to see the path you have set for yourself.$B$BYou would do me a great honor if you would accept this as a gift of appreciation.' WHERE `word_id` = 134667; -- locales_quest - offerrewardtext : entry=1081
UPDATE `trans_words` SET `content_loc11`='Hello, $N. I know you\'re busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She\'s the one the younger dwarven paladins go to when it is time they learn more about the Light and what\'s expected of all of us.$B$BYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.' WHERE `word_id` = 137702; -- locales_quest - details : entry=3000
UPDATE `trans_words` SET `content_loc11`='Hello, $N. I know you\'re busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She\'s the one the younger paladins go to when it\'s time they learn more about the Light and what\'s expected of ya.' WHERE `word_id` = 137700; -- locales_quest - details : entry=2999
UPDATE `trans_words` SET `content_loc11`='Hello, $N. I know you\'re busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She\'s the one the younger paladins go to when it\'s time they learn more about the Light and what\'s expected of ya.$B$BYou can find her upstairs in the Hall of Mysteries. If you\'ve never been there, it\'s in the Mystic Ward. Good luck to ya, $N.' WHERE `word_id` = 137696; -- locales_quest - details : entry=2997
UPDATE `trans_words` SET `content_loc11`='Hello, $N. I\'m assuming by all that armor and weapon of yours, you\'re either here to try and take my land, or the Church finally sent someone to help protect me while my Jordan\'s gone.$B$B Well, let me introduce myself: I\'m Daphne Stilwell. It\'s a pleasure.$B$BNow, you\'re not too late... I\'ve only killed a half dozen of the scum since last sun up. They\'ve been a little slow getting \'round the bend up there, but they probably saw you coming, which means they\'ll probably be here any minute.' WHERE `word_id` = 136031; -- locales_quest - offerrewardtext : entry=1650
UPDATE `trans_words` SET `content_loc11`='Hello, $N. It\'s good to see you again.$B$BYou needn\'t worry. We\'ve settled in quite well. I\'ve dispatched several of my wardens to assist in hunting down the Druids of the Flame, and I\'ve drawn assault plans for the Forlorn Spire. When the time is right, perhaps you will join us there.' WHERE `word_id` = 190464; -- locales_quest - offerrewardtext : entry=29215
UPDATE `trans_words` SET `content_loc11`='Hello, $N. It\'s good to see you made it to Fray Island. I hope you find it to your liking...' WHERE `word_id` = 136215; -- locales_quest - offerrewardtext : entry=1718
UPDATE `trans_words` SET `content_loc11`='Hello, $N. You\'d like information about a specific member of the Theramore guard? Reethe, was it?$B$BJust give me a moment to find the right book.' WHERE `word_id` = 135258; -- locales_quest - offerrewardtext : entry=1259
UPDATE `trans_words` SET `content_loc11`='Hello, $N.$B$BYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.$B$BRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what\'s happening to the land, but I have yet to hear word back from her. I\'m even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.$B$BWould you find her and report back to me?' WHERE `word_id` = 134614; -- locales_quest - details : entry=1070
UPDATE `trans_words` SET `content_loc11`='Hello, $R. I am Baron Sablemane. A friend of Rexxar\'s is a friend of mine.' WHERE `word_id` = 152317; -- locales_quest - offerrewardtext : entry=10783
UPDATE `trans_words` SET `content_loc11`='Hello, $R.$B$BYou don\'t happen to be available for a recovery mission of some importance?' WHERE `word_id` = 150339; -- locales_quest - offerrewardtext : entry=10263
UPDATE `trans_words` SET `content_loc11`='Hello, citizen. This is a dangerous place to be wandering about. I wouldn\'t hang around too long if you value your life.$B$BIf you keep your questions short, I\'ll see if I can help you. Just keep your eyes open for any of those filthy ogres. Rumor has it there\'s a Horde base somewhere in the swamps. The infiltrators are doing what they can to find it, but the process has been slow going and we\'ve had little progress.' WHERE `word_id` = 135281; -- locales_quest - offerrewardtext : entry=1266
UPDATE `trans_words` SET `content_loc11`='Hello, fancy $Gboy:girl;! What\'s a prissy thing like you doing in the Pig and Whistle? Be careful, or you might break a nail...' WHERE `word_id` = 135999; -- locales_quest - offerrewardtext : entry=1639
UPDATE `trans_words` SET `content_loc11`='Hello, fire juggler!  Are you having fun and making fiery mayhem?  That\'s what I like to hear!  Now, do you think you\'re an expert at torch tossing?  Then I have a test for you...$B$BYou know the rules: toss torches at the marked braziers. This time, however, you have a little more time and a LOT more braizers to hit.$B$BReady?' WHERE `word_id` = 154715; -- locales_quest - details : entry=11926
UPDATE `trans_words` SET `content_loc11`='Hello, little $R. Bastia is fast, no? We have something very important that needs doing. Can you help us?' WHERE `word_id` = 173629; -- locales_quest - offerrewardtext : entry=14240
UPDATE `trans_words` SET `content_loc11`='Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.$B$BYou can find Muren at the Hall of Arms in the Military Ward of Ironforge. Talk to him when you\'re ready to learn what it is to be a warrior.' WHERE `word_id` = 136084; -- locales_quest - details : entry=1679
UPDATE `trans_words` SET `content_loc11`='Hello, what is your business in a place like this? I\'m sorry, who sent you? I\'m afraid I\'ve never heard of such a dwarf.' WHERE `word_id` = 184584; -- locales_quest - offerrewardtext : entry=27469
UPDATE `trans_words` SET `content_loc11`='Hello, what is your business in a place like this? So Overseer Oilfist sent you? Listen carefully, we have much to discuss in little time.' WHERE `word_id` = 184587; -- locales_quest - offerrewardtext : entry=27470
UPDATE `trans_words` SET `content_loc11`='Hello, what is your business in a place like this? So you come at the will of Miss Brightwing, do you? Very interesting indeed.' WHERE `word_id` = 184590; -- locales_quest - offerrewardtext : entry=27471
UPDATE `trans_words` SET `content_loc11`='Hello, yes? What? You? Oh, you\'re one of the ones I sent after the Eye of Twilight, aren\'t you? Good work, very good. I suppose that\'s a valuable lesson: Never to take orders from a big purple ball.' WHERE `word_id` = 177072; -- locales_quest - offerrewardtext : entry=25312
UPDATE `trans_words` SET `content_loc11`='Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.' WHERE `word_id` = 271662; -- locales_quest - details : entry=6071
UPDATE `trans_words` SET `content_loc11`='Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.' WHERE `word_id` = 140948; -- locales_quest - details : entry=6074
UPDATE `trans_words` SET `content_loc11`='Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.' WHERE `word_id` = 152297; -- locales_quest - details : entry=10779
UPDATE `trans_words` SET `content_loc11`='Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.' WHERE `word_id` = 140942; -- locales_quest - details : entry=6068
UPDATE `trans_words` SET `content_loc11`='Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.' WHERE `word_id` = 140939; -- locales_quest - details : entry=6065
UPDATE `trans_words` SET `content_loc11`='Hello, young one. Here for some instruction, are you?' WHERE `word_id` = 135838; -- locales_quest - offerrewardtext : entry=1505
UPDATE `trans_words` SET `content_loc11`='Hello. Do you have business with me?' WHERE `word_id` = 143862; -- locales_quest - offerrewardtext : entry=620
UPDATE `trans_words` SET `content_loc11`='Hello. Hello, hello hello hello hello HELLO!$B$BI\'m sorry - wait, no I\'m not! Don\'t be rude!$B$BOh no...that was crazy talk.$B$BBut...sometimes being crazy is my only solace.' WHERE `word_id` = 133082; -- locales_quest - offerrewardtext : entry=687
UPDATE `trans_words` SET `content_loc11`='Hello. I\'m Pamela, what\'s your name?' WHERE `word_id` = 139905; -- locales_quest - offerrewardtext : entry=27383
UPDATE `trans_words` SET `content_loc11`='Hello. You should find out about those wabbits.' WHERE `word_id` = 150812; -- locales_quest - details : entry=10383
UPDATE `trans_words` SET `content_loc11`='Hellscream shall know of your deeds here, $N. Without you, things here would be far worse. Lok\'tar ogar, my friend!' WHERE `word_id` = 189390; -- locales_quest - offerrewardtext : entry=28843
UPDATE `trans_words` SET `content_loc11`='Help Akama and Maiev enter the Black Temple.' WHERE `word_id` = 153188; -- locales_quest - EndText : entry=10985
