UPDATE `trans_words` SET `content_loc11`='klajsdklajlsd' WHERE `word_id` = 158170; -- locales_quest - details : entry=12015
UPDATE `trans_words` SET `content_loc11`='Kneel, champion. I place this helm upon your head to complete your terrifying visage. Any that dare look upon your dark countenance will know that death comes. Let none stand so boldly against your king so as to face your merciless wrath, $N.$B$BThere remains only one final task...$B$B<The Lich King looks west.>$B$BLight\'s Hope Chapel.' WHERE `word_id` = 161197; -- locales_quest - offerrewardtext : entry=12779
UPDATE `trans_words` SET `content_loc11`='Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Antoine Brack, an Argent Dawn prisoner inside the nearby prison house.' WHERE `word_id` = 161091; -- locales_quest - objectives : entry=12750
