UPDATE `trans_words` SET `content_loc11`='Large Festival rockets light up the sky brilliantly - only the cluster rockets rival their magnificence!$B$BBring me coins of ancestry, $N, and I shall share the knowledge of their creation.' WHERE `word_id` = 272155; -- locales_quest - details : entry=8879
