UPDATE `trans_words` SET `content_loc11`='Locate Assistant Greely at the Southern Rocketway Terminus. The Goblin Rocketway can be used to quickly move around Azshara.' WHERE `word_id` = 337714; -- locales_quest - CompletedText : entry=14424
