UPDATE `trans_words` SET `content_loc11`='Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.$B$BGive the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands.' WHERE `word_id` = 139723; -- locales_quest - objectives : entry=5051
