UPDATE `trans_words` SET `content_loc11`='Mark Location of South Sinkhole' WHERE `word_id` = 157361; -- locales_quest - ObjectiveText1 : entry=11684
UPDATE `trans_words` SET `content_loc11`='Mark of Lore' WHERE `word_id` = 148361; -- locales_quest - ObjectiveText1 : entry=9785
UPDATE `trans_words` SET `content_loc11`='Mark of the Wild learned' WHERE `word_id` = 174665; -- locales_quest - ObjectiveText1 : entry=24465
UPDATE `trans_words` SET `content_loc11`='Mark of War' WHERE `word_id` = 148362; -- locales_quest - ObjectiveText2 : entry=9785
UPDATE `trans_words` SET `content_loc11`='Market Homes Evacuated' WHERE `word_id` = 173284; -- locales_quest - ObjectiveText1 : entry=14098
UPDATE `trans_words` SET `content_loc11`='Marnal draws close... and Shadra even closer. Prepare for bloodshed.' WHERE `word_id` = 181496; -- locales_quest - offerrewardtext : entry=26558
UPDATE `trans_words` SET `content_loc11`='Marrah has informed us of the superiority of the Vrykul\'s weaponry. We\'ll have a look at these and see if there\'s anything to learn.$B$BTake this for your trouble, $C.' WHERE `word_id` = 163037; -- locales_quest - offerrewardtext : entry=13206
UPDATE `trans_words` SET `content_loc11`='Marsh Fire Extinguished' WHERE `word_id` = 179351; -- locales_quest - ObjectiveText1 : entry=25939
UPDATE `trans_words` SET `content_loc11`='Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.' WHERE `word_id` = 130432; -- locales_quest - objectives : entry=75
UPDATE `trans_words` SET `content_loc11`='Marshall Dughan sent you, eh? Well you\'re not from the army, but if Dughan sent you then that\'s good enough for me!$B$BOur situation is, to say the least, a stressed one. I hope you can give us a hand.' WHERE `word_id` = 131160; -- locales_quest - offerrewardtext : entry=239
UPDATE `trans_words` SET `content_loc11`='Marshlight Lake Controls Disabled' WHERE `word_id` = 148100; -- locales_quest - ObjectiveText2 : entry=9720
UPDATE `trans_words` SET `content_loc11`='Martie Jainrose of Lakeshire wants you to kill Bellygrub. Bring her his tusk as proof.' WHERE `word_id` = 130282; -- locales_quest - objectives : entry=34
UPDATE `trans_words` SET `content_loc11`='Maruut said when all dis started dat he would gladly give his life ta see our task done. He would be proud of dis success... of dis death. Da rift be closed on dis side. Deepholm should calm down a bit. It\'ll be takin\' time for Thrall to mend da wound in Azeroth, and we\'ll be needin\' to remain until he finishes. Thank you for all ya\'ve done. I don\'t tink we could have been accomplishin\' dis so soon without you.' WHERE `word_id` = 182985; -- locales_quest - offerrewardtext : entry=26971
UPDATE `trans_words` SET `content_loc11`='Marvelous! I\'ll smelt this down into a delicious soup. An angry soup. Of molten metal.' WHERE `word_id` = 187357; -- locales_quest - offerrewardtext : entry=28212
UPDATE `trans_words` SET `content_loc11`='Marvelous. To think the shapers of our world crafted these...' WHERE `word_id` = 176226; -- locales_quest - offerrewardtext : entry=25068
UPDATE `trans_words` SET `content_loc11`='Marvelously executed, $N. My men and I can handle the rest. With Kurzen out of the picture, we may be able to continue our original expedition here in Stranglethorn, which was... ahh... No matter. Please, feel free to peruse our armor stores. You may find something that fits you well.' WHERE `word_id` = 182177; -- locales_quest - offerrewardtext : entry=26737
UPDATE `trans_words` SET `content_loc11`='Marvels of modernized goblin destructivity, eh? I love these babies.' WHERE `word_id` = 188690; -- locales_quest - offerrewardtext : entry=28591
UPDATE `trans_words` SET `content_loc11`='Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz\'ridian Ornaments.' WHERE `word_id` = 137933; -- locales_quest - objectives : entry=3161
UPDATE `trans_words` SET `content_loc11`='Marvon\'s been gone quite a long time now, $N. He went off to Tanaris to study some of the ancient troll ruins.$B$BNow, what was it that you said you needed?' WHERE `word_id` = 138864; -- locales_quest - offerrewardtext : entry=4147
UPDATE `trans_words` SET `content_loc11`='Massive Wave Defeated' WHERE `word_id` = 189192; -- locales_quest - ObjectiveText2 : entry=28751
UPDATE `trans_words` SET `content_loc11`='Massive Wave Survived' WHERE `word_id` = 188803; -- locales_quest - ObjectiveText2 : entry=28617
UPDATE `trans_words` SET `content_loc11`='Massive Waves Survived' WHERE `word_id` = 189195; -- locales_quest - ObjectiveText2 : entry=28752
UPDATE `trans_words` SET `content_loc11`='Master $N, the raptor slayer!$B$BHas a nice ring to it, eh?' WHERE `word_id` = 130975; -- locales_quest - offerrewardtext : entry=197
UPDATE `trans_words` SET `content_loc11`='Master always said "after killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature." This is dangerous stuff. Thanks for helping me with my studies.' WHERE `word_id` = 177156; -- locales_quest - offerrewardtext : entry=25337
UPDATE `trans_words` SET `content_loc11`='Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.' WHERE `word_id` = 134806; -- locales_quest - objectives : entry=1113
UPDATE `trans_words` SET `content_loc11`='Master Engineer Zinfizzlex wants you to bring him the following:$B$B*30 Thorium Bars.$B$B*50 Mithril Bars.$B$B*75 Iron bars.$B$B*1 Steamsaw.' WHERE `word_id` = 271669; -- locales_quest - objectives : entry=6861
UPDATE `trans_words` SET `content_loc11`='Master Fordring will be glad beyond measure to see this painting again.' WHERE `word_id` = 184046; -- locales_quest - offerrewardtext : entry=27305
UPDATE `trans_words` SET `content_loc11`='Master Harris may have been right. I would have been better to leave the past behind. I\'ve got a new life now. Whether it\'s that of a monster or a man is up to me. As for you, I cannot thank you enough for your assistance, regardless of the outcome. Please, take this with my thanks.' WHERE `word_id` = 181945; -- locales_quest - offerrewardtext : entry=26674
UPDATE `trans_words` SET `content_loc11`='Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him. To make matters worse they buried his corpse in the Southshore cemetery.$B$BSuch disregard for the great wizard is unacceptable. As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.$B$BWe will need Helcular\'s Rod first. Yeti overtook his ritual lair. Undoubtedly one of the beasts has it.' WHERE `word_id` = 132501; -- locales_quest - details : entry=552
UPDATE `trans_words` SET `content_loc11`='Master Kariel Winthalus Found' WHERE `word_id` = 142074; -- locales_quest - EndText : entry=7481
UPDATE `trans_words` SET `content_loc11`='Master Mazen\'s directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep.$B$BBut I had never been to the Blasted Lands before! The journey was frightening!$B$BWhen I got to the Swamp of Sorrows, I made a wrong turn and ended up surrounded by horrible plant-like swamp creatures. They lurched as if to attack me so I ran. But in my haste I dropped the essay. One of the beasts took it I am sure.$B$BCould you please try to retrieve it and deliver it to Mahar Ba?' WHERE `word_id` = 135399; -- locales_quest - details : entry=1364
UPDATE `trans_words` SET `content_loc11`='Master Mechanic Castpipe in Ironforge has need of adventurers!  He\'s organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.$B$BCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he\'s still a smart gnome so if he thinks it\'s important, then by my calculations there\'s an eighty-four percent probability that it really is important!$B$BThose are good odds!' WHERE `word_id` = 137448; -- locales_quest - details : entry=2931
UPDATE `trans_words` SET `content_loc11`='Master Nesingwary will be so upset if he finds out!$B$BHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn. Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!$B$BI was able to gather most of the pages but many are still strewn about the jungle. Collect the pages to complete each of the four chapters.$B$BI will help you organize them. Return the chapters to me once you have all four.' WHERE `word_id` = 131570; -- locales_quest - details : entry=338
UPDATE `trans_words` SET `content_loc11`='Master Rhonsus taught me everything I know about my trade. I will honor his memory by using my skills to serve the people of Kirin\'Var.' WHERE `word_id` = 150659; -- locales_quest - offerrewardtext : entry=10332
UPDATE `trans_words` SET `content_loc11`='Master Ryson\'s All Seeing Eye Recovered' WHERE `word_id` = 141682; -- locales_quest - EndText : entry=6847
UPDATE `trans_words` SET `content_loc11`='Master says give gift to $N. Zggi wants to keep nice gift but Zggi knows better than to betray Master.' WHERE `word_id` = 131833; -- locales_quest - offerrewardtext : entry=397
UPDATE `trans_words` SET `content_loc11`='Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.$B$BWhen you have gloom weed you take to Master Holland in Brill graveyard.' WHERE `word_id` = 275927; -- locales_quest - details : entry=5481
UPDATE `trans_words` SET `content_loc11`='Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.$B$BWhen you have gloom weed you take to Master Holland in Brill.' WHERE `word_id` = 275307; -- locales_quest - details : entry=25038
UPDATE `trans_words` SET `content_loc11`='Master Winthalus lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...$B$BRegardless, if you are interested, you will need to present the Libram along with some basic reagents.$B$BHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!$B$B<Lydros shrugs.>' WHERE `word_id` = 142076; -- locales_quest - details : entry=7483
UPDATE `trans_words` SET `content_loc11`='Master\'s Glaive surveillance' WHERE `word_id` = 172893; -- locales_quest - ObjectiveText1 : entry=13948
UPDATE `trans_words` SET `content_loc11`='Master\'s Touch' WHERE `word_id` = 148597; -- locales_quest - EndText : entry=9836
UPDATE `trans_words` SET `content_loc11`='Masters\' Gate investigated' WHERE `word_id` = 183127; -- locales_quest - ObjectiveText1 : entry=27006
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands wants 10 Insignia of the Crusade and 30 gold.' WHERE `word_id` = 145189; -- locales_quest - objectives : entry=9211
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make a Plagueheart Belt if you bring him the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth.' WHERE `word_id` = 145018; -- locales_quest - objectives : entry=9109
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make a Plagueheart Circlet if you bring him the following: 1 Desecrated Circlet, 15 Wartorn Cloth Scraps, 3 Mooncloth and 3 Nexus Crystals.' WHERE `word_id` = 145010; -- locales_quest - objectives : entry=9105
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make a Plagueheart Robe if you bring him the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.' WHERE `word_id` = 145006; -- locales_quest - objectives : entry=9103
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make Plagueheart Bindings if you bring him the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal.' WHERE `word_id` = 145020; -- locales_quest - objectives : entry=9110
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make Plagueheart Gloves if you bring him the following: 1 Desecrated Gloves, 8 Wartorn Cloth Scraps and 4 Mooncloth.' WHERE `word_id` = 145016; -- locales_quest - objectives : entry=9108
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make Plagueheart Leggings if you bring him the following: 1 Desecrated Leggings, 20 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.' WHERE `word_id` = 145008; -- locales_quest - objectives : entry=9104
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make Plagueheart Sandals if you bring him the following: 1 Desecrated Sandals, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides.' WHERE `word_id` = 145014; -- locales_quest - objectives : entry=9107
UPDATE `trans_words` SET `content_loc11`='Mataus the Wrathcaster at Light\'s Hope Chapel in the Eastern Plaguelands will make Plagueheart Shoulderpads if you bring him the following: 1 Desecrated Shoulderpads, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides.' WHERE `word_id` = 145012; -- locales_quest - objectives : entry=9106
UPDATE `trans_words` SET `content_loc11`='Matching the lines on the face of Trollbane\'s tomb with the glowing lines of the Sigil of Ignaeus, a flash of light consumes the Sigil, and the legendary sword Trol\'kalar is released from the stone hands\' grip.' WHERE `word_id` = 132901; -- locales_quest - offerrewardtext : entry=645
UPDATE `trans_words` SET `content_loc11`='Mathias finally sent another agent to back me up, eh? Well I hope he\'s ready to hear some bad news.' WHERE `word_id` = 136805; -- locales_quest - offerrewardtext : entry=2360
UPDATE `trans_words` SET `content_loc11`='Matis the Cruel Captured' WHERE `word_id` = 148060; -- locales_quest - EndText : entry=9711
UPDATE `trans_words` SET `content_loc11`='Matis will be brought to justice, $N; and I want you to be the one to find him and bring him back to the Triumvirate.$B$BScour the island for this bastard. Should you find him, use this flare gun. When my trackers see the flare, they\'ll come and assist in capturing Matis. Return to me after he\'s been captured.' WHERE `word_id` = 148057; -- locales_quest - details : entry=9711
UPDATE `trans_words` SET `content_loc11`='Matron Varah has given you a list of ingredients for the making of her two favorite dishes, which includes the collection of 3 Raptor Ribs and 3 Serpent Flesh. Bring them to her at Mok\'Nathal Village in the Blade\'s Edge Mountains.' WHERE `word_id` = 152658; -- locales_quest - objectives : entry=10860
UPDATE `trans_words` SET `content_loc11`='Mature Netherwing Drake fed' WHERE `word_id` = 152411; -- locales_quest - ObjectiveText1 : entry=10804
UPDATE `trans_words` SET `content_loc11`='Mau\'ari can derive da juju for $N... Use da Cache of Mau\'ari to cast dis upon yourself or your allies.' WHERE `word_id` = 139443; -- locales_quest - offerrewardtext : entry=4801
UPDATE `trans_words` SET `content_loc11`='Maurin wants you to deliver Maurin\'s Concoction to Karnum at Karnum\'s Grove.' WHERE `word_id` = 174047; -- locales_quest - objectives : entry=14343
UPDATE `trans_words` SET `content_loc11`='May - for someone as exalted among the Zandalar as you are, I have something very special for you. Direct from our home in the South Seas... the Signets of the Zandalar! These signets are used to enhance any shoulder item you may possess. Should you seek might, mojo, or serenity - I have what you need!' WHERE `word_id` = 271928; -- locales_quest - details : entry=8246
UPDATE `trans_words` SET `content_loc11`='May fire burn within your heart, $N.$B$BThe elements await you.' WHERE `word_id` = 135696; -- locales_quest - offerrewardtext : entry=1464
UPDATE `trans_words` SET `content_loc11`='May my leaves provide your arrows protection from harm. May your arrows strike true. May the enemies of our world be smitten.' WHERE `word_id` = 142251; -- locales_quest - offerrewardtext : entry=7634
UPDATE `trans_words` SET `content_loc11`='May my pile never stop growing.' WHERE `word_id` = 184883; -- locales_quest - offerrewardtext : entry=27539
UPDATE `trans_words` SET `content_loc11`='May the Dark Lady watch over you, $N.' WHERE `word_id` = 188925; -- locales_quest - offerrewardtext : entry=28651
UPDATE `trans_words` SET `content_loc11`='May the disgusting monster stay dead this time! I\'ll head down there and scatter his remains to ash myself, $N. You\'ve done a great thing; perhaps in time Duskwood can return to its former peaceful state.' WHERE `word_id` = 182232; -- locales_quest - offerrewardtext : entry=26754
UPDATE `trans_words` SET `content_loc11`='May the Earthmother watch over you! Bless you, young one.' WHERE `word_id` = 184522; -- locales_quest - offerrewardtext : entry=27456
UPDATE `trans_words` SET `content_loc11`='May the heavens bless you, $N. You\'ve done more for Randis than most would ever think of doing for him. Thank you - you\'re a shining star in the skies of the Alliance.$B$BPlease - if you can spare the time, come back and visit us. I know that Randis would like that, as would I.' WHERE `word_id` = 130861; -- locales_quest - offerrewardtext : entry=171
UPDATE `trans_words` SET `content_loc11`='May the Light watch over you! Bless you, young one.' WHERE `word_id` = 140487; -- locales_quest - offerrewardtext : entry=5544
UPDATE `trans_words` SET `content_loc11`='May the power of the Light shine upon you in these dark times, $C. I am pleased to serve as your coordinator for our plan to sabotage the Scourge\'s cauldrons.$B$BOur goal will be to change the composition of the plague that the cauldrons create into something that negatively affects the Scourge. In order to affect this change, you will need to secure access to each of the four cauldrons present in the Western Plaguelands.$B$BStand ready hero, for a glorious battle against the vile Scourge awaits you!' WHERE `word_id` = 140078; -- locales_quest - offerrewardtext : entry=5215
UPDATE `trans_words` SET `content_loc11`='May the spirits bless you, $N. The Mag\'har are in your debt.' WHERE `word_id` = 147043; -- locales_quest - offerrewardtext : entry=9447
UPDATE `trans_words` SET `content_loc11`='May the spirits bless you, $N. You\'ve done more for Grunth than most would ever think of doing for him. Thank you - you\'re the epitome of what it means to be a hero of the Horde.$B$BPlease - if you can spare the time, come back and visit us. I know that Grunth would like that, as would I.' WHERE `word_id` = 140383; -- locales_quest - offerrewardtext : entry=5502
UPDATE `trans_words` SET `content_loc11`='May the Winterfall never threaten the Timbermaw again. Thank you, $N.' WHERE `word_id` = 188792; -- locales_quest - offerrewardtext : entry=28615
UPDATE `trans_words` SET `content_loc11`='May their blood water our tree. You fight well, $N.' WHERE `word_id` = 188054; -- locales_quest - offerrewardtext : entry=28382
UPDATE `trans_words` SET `content_loc11`='May their souls rest in peace.' WHERE `word_id` = 186345; -- locales_quest - offerrewardtext : entry=27949
UPDATE `trans_words` SET `content_loc11`='May these knives find a place in someone\'s heart.$B$BLiterally.' WHERE `word_id` = 143099; -- locales_quest - offerrewardtext : entry=8249
UPDATE `trans_words` SET `content_loc11`='May you bash in many a brain, $N!' WHERE `word_id` = 140256; -- locales_quest - offerrewardtext : entry=5305
UPDATE `trans_words` SET `content_loc11`='May you be protected in your crusade. May the Master bless your efforts.' WHERE `word_id` = 142467; -- locales_quest - offerrewardtext : entry=7785
UPDATE `trans_words` SET `content_loc11`='May you find what you\'re looking for, $Gbrother:sister;.' WHERE `word_id` = 165196; -- locales_quest - offerrewardtext : entry=24819
UPDATE `trans_words` SET `content_loc11`='May you slay many humanoids and take their cloth.' WHERE `word_id` = 163305; -- locales_quest - offerrewardtext : entry=13265
UPDATE `trans_words` SET `content_loc11`='May your aim be unerring, and the mark of your weapon be true, $R.$B$BAgamaggan\'s spirit is with you. Return <snort> to me if you wish. Mangletooth will bless you again if the great boar god deems me worthy. <snort>' WHERE `word_id` = 139692; -- locales_quest - offerrewardtext : entry=5043
UPDATE `trans_words` SET `content_loc11`='May your sense of honor and duty serve Azeroth well, $C.' WHERE `word_id` = 189264; -- locales_quest - offerrewardtext : entry=28790
UPDATE `trans_words` SET `content_loc11`='Maybe if I got a pie, I could tell you who has that necklace. And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... $B$BMaybe if you gave her some chunks of boar meat from the boars that hang around our farms, and told her what it was for, she\'d bake up a pie for you.' WHERE `word_id` = 130483; -- locales_quest - details : entry=86
UPDATE `trans_words` SET `content_loc11`='Maybe this sounds strange coming from an imp, but I\'d like a pet of my own. I really would. It\'s just not fair that Niby gets me and I get nothing!$B$BIn fact, it doesn\'t even need to be a living pet. I\'d need something to start making it with, like some felcloth. The satyrs here in Felwood sometimes have felcloth, so you\'d just have to kill enough of them until you find some. That doesn\'t sound so bad, does it?' WHERE `word_id` = 143530; -- locales_quest - details : entry=8420
UPDATE `trans_words` SET `content_loc11`='Maybe you heard or maybe you haven\'t... my crew and I was out fishing near Ranazjar Isle, north of the wrecked ship off the coast up north. We used to fish there all the time; now all I do is think of a way to seek revenge for my fallen comrades.$B$BThe naga attacked us one morning, killing everyone except me.$B$BMe conscience can\'t handle the guilt, $C; I need you to go and fry them naga for me. I\'ll make the effort worth your while; you think you can help me with that?' WHERE `word_id` = 141078; -- locales_quest - details : entry=6143
UPDATE `trans_words` SET `content_loc11`='Maziel\'s journal appears to be undamaged by the mercury.' WHERE `word_id` = 183500; -- locales_quest - offerrewardtext : entry=27101
UPDATE `trans_words` SET `content_loc11`='Mazoga? He\'s taken the sword? That filthy... At least you escaped with your life. The Lasher\'s bite is a vicious one.' WHERE `word_id` = 176086; -- locales_quest - offerrewardtext : entry=25032
UPDATE `trans_words` SET `content_loc11`='Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.$B$BWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.$B$BDurnholde is just southeast of here, across the river. Drull and Tog\'thar are being held there, you must go and rescue them.' WHERE `word_id` = 132268; -- locales_quest - details : entry=498
UPDATE `trans_words` SET `content_loc11`='Me brother Bahrum has gone missing!$B$BHe was one of the first scouts in the area. All the others have returned safely, but there be no sign of him. Da says he\'s just dawdling somewhere, but he\'s me only brother, and I promised me mum that I would keep him safe. Will you please find him?' WHERE `word_id` = 187463; -- locales_quest - details : entry=28236
UPDATE `trans_words` SET `content_loc11`='Me brother sent you? Good! I could use a $C. Can ya hold yer own in a fight?' WHERE `word_id` = 188001; -- locales_quest - offerrewardtext : entry=28369
UPDATE `trans_words` SET `content_loc11`='Me hunters be dead or frozen, $N. Just you and whatever allies you bring wit ya is all da help you get. You still want to do dis? Just say da word and me call for da dragon once more.$B$BIf ya kill it, take da beast\'s frozen heart back to Agmar\'s Hammer and present it to Gort. He sure to reward you good, mon.' WHERE `word_id` = 158518; -- locales_quest - details : entry=12097
UPDATE `trans_words` SET `content_loc11`='Me like fishy head!$B$BMe no eat you now.' WHERE `word_id` = 135048; -- locales_quest - offerrewardtext : entry=1177
UPDATE `trans_words` SET `content_loc11`='Meat - and lots of it! Well done. This will keep bellies full as we build our arsenal.' WHERE `word_id` = 173317; -- locales_quest - offerrewardtext : entry=14118
UPDATE `trans_words` SET `content_loc11`='Medical supplies? Thank you! Not exactly sure what to do with them to be honest, but I\'m sure they\'ll be useful.$B$BIt\'s good to meet you... there\'s such a colorful variety among your peoples. We\'re not used to having visitors up this way very often - it\'s good to have some fresh company.' WHERE `word_id` = 161562; -- locales_quest - offerrewardtext : entry=12863
UPDATE `trans_words` SET `content_loc11`='Medicine Man Persuaded' WHERE `word_id` = 181415; -- locales_quest - ObjectiveText1 : entry=26538
UPDATE `trans_words` SET `content_loc11`='Meet Andalar Shadevale at Jaedenar in Felwood.' WHERE `word_id` = 337728; -- locales_quest - CompletedText : entry=28121
