UPDATE `trans_words` SET `content_loc11`='Place the Relic Bundle at the Darrowshire town square.$B$BPrevent Davil Lightfire\'s death until the death of Horgus.$B$BPrevent Captain Redpath\'s death until Redpath the Corrupted appears.$B$BDefeat Redpath the Corrupted.$B$BSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.' WHERE `word_id` = 140630; -- locales_quest - objectives : entry=5721
