UPDATE `trans_words` SET `content_loc11`='Placeholder, $N! This is a placeholder lumberjack quest. You? Grab that lumberjack. And do something ... placeholder-y with him.$B$BYou heard me.' WHERE `word_id` = 175562; -- locales_quest - details : entry=24867
UPDATE `trans_words` SET `content_loc11`='Placing the sprouts in front of her, Dadanga seems pleased.$B$BShe nudges a small brown-wrapped package towards you, in exchange for the treat!' WHERE `word_id` = 139929; -- locales_quest - offerrewardtext : entry=5150
