UPDATE `trans_words` SET `content_loc11`='Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.' WHERE `word_id` = 141251; -- locales_quest - objectives : entry=6381
