UPDATE `trans_words` SET `content_loc11`='Ready to go, $N?$B$BFirst, we need to get this powder to Ironband. It\'ll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me.$B$BI\'ll feel a lot better with you coming along.' WHERE `word_id` = 131447; -- locales_quest - details : entry=309
UPDATE `trans_words` SET `content_loc11`='Ready to return to Orgrimmar with those reports? I can arrange a flight for you right away.' WHERE `word_id` = 182395; -- locales_quest - offerrewardtext : entry=26806
UPDATE `trans_words` SET `content_loc11`='Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.' WHERE `word_id` = 163792; -- locales_quest - details : entry=13406
UPDATE `trans_words` SET `content_loc11`='Really, $C?$B$BNothing notable to report?$B$BI beg to differ...' WHERE `word_id` = 163170; -- locales_quest - offerrewardtext : entry=13237
UPDATE `trans_words` SET `content_loc11`='Really? You want a reward for killing an orc? As in fame and riches and noble steeds?$B$BBack in my day killing orcs WAS the reward!' WHERE `word_id` = 191116; -- locales_quest - offerrewardtext : entry=29540
UPDATE `trans_words` SET `content_loc11`='Rebel arsenals?  In my own city? What in the bloody hell was Crowley up to?' WHERE `word_id` = 180004; -- locales_quest - offerrewardtext : entry=26129
