UPDATE `trans_words` SET `content_loc11`='Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.' WHERE `word_id` = 140062; -- locales_quest - objectives : entry=5212
UPDATE `trans_words` SET `content_loc11`='Recover a box of Fras Siabi\'s Premium Tobacco.' WHERE `word_id` = 275368; -- locales_quest - details : entry=27192
UPDATE `trans_words` SET `content_loc11`='Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B* The sapphire has been claimed by Grimlok, the trogg leader.' WHERE `word_id` = 136777; -- locales_quest - objectives : entry=2339
UPDATE `trans_words` SET `content_loc11`='Recover Artruis\'s Phylactery within the Sundered Shard.' WHERE `word_id` = 337746; -- locales_quest - CompletedText : entry=12581
UPDATE `trans_words` SET `content_loc11`='Recover Dellylah\'s Stolen Beans, Dellylah\'s Stolen Water, and Dellylah\'s Stolen Bags.' WHERE `word_id` = 166148; -- locales_quest - objectives : entry=459
UPDATE `trans_words` SET `content_loc11`='Recover Egalin\'s Grimoire and bring it to Carendin Halgar in the Temple of the Damned.' WHERE `word_id` = 135730; -- locales_quest - objectives : entry=1473
