UPDATE `trans_words` SET `content_loc11`='Recover Sha\'ni\'s Nose-Ring from Krom\'Grul and return it to Thal\'trak in Kargath. Search the various caves and mines in Dreadmaul Rock.' WHERE `word_id` = 270977; -- locales_quest - objectives : entry=3822
UPDATE `trans_words` SET `content_loc11`='Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.' WHERE `word_id` = 144049; -- locales_quest - objectives : entry=8620
