UPDATE `trans_words` SET `content_loc11`='Recover the Silver Dawning\'s Lockbox and the Mist Veil\'s Lockbox for Gorbold Steelhand in Auberdine. Both items should be found aboard the wreckage of the ships to the north of the village.' WHERE `word_id` = 134281; -- locales_quest - objectives : entry=982
