UPDATE `trans_words` SET `content_loc11`='Shatterskull\'s not personable by anyone\'s standards, but he certainly gets the job done. Let\'s put you to work.' WHERE `word_id` = 191120; -- locales_quest - offerrewardtext : entry=29542
