UPDATE `trans_words` SET `content_loc11`='Stay back! Don\'t make me... Is it you?  By the Light!  It\'s you, $N!' WHERE `word_id` = 174278; -- locales_quest - offerrewardtext : entry=14406
UPDATE `trans_words` SET `content_loc11`='Stay where you are for just a moment... I am testing out a new combination of crystals...' WHERE `word_id` = 138641; -- locales_quest - offerrewardtext : entry=3941
UPDATE `trans_words` SET `content_loc11`='Stay your hand!  Please, I beg you!$B$BI\'m only here because of a girl. Her words were so sweet... but now I realize the madness behind them.$B$BTake this envelope. It has information that\'ll score you some points with your superiors.$B$BThe guards are distracted... I can make a run for it. Please. I don\'t want to die!' WHERE `word_id` = 177074; -- locales_quest - details : entry=25313
