UPDATE `trans_words` SET `content_loc11`='Take this draught, $N. After you drink it, your physical strength against the Scourge will receive a boost. If you need more than this sample bring me more hearts.' WHERE `word_id` = 146495; -- locales_quest - offerrewardtext : entry=9216
