UPDATE `trans_words` SET `content_loc11`='Tormek? Oh yes, I do remember him. He had quite a nice beard and smile underneath.$B$BAh, I can\'t believe he remembered me!' WHERE `word_id` = 144503; -- locales_quest - offerrewardtext : entry=8898
