UPDATE `trans_words` SET `content_loc11`='Training against the other valiants will sharpen your claws and hone your battle insticts. When the competition begins, you will be ready.' WHERE `word_id` = 164268; -- locales_quest - offerrewardtext : entry=13767
UPDATE `trans_words` SET `content_loc11`='Traitors to the Horde and traitors to their own people... I guess they\'re not all bad. They\'ll make fine drinking flasks.' WHERE `word_id` = 177224; -- locales_quest - offerrewardtext : entry=25362
UPDATE `trans_words` SET `content_loc11`='Traitors, all of them!$B$BGood work, $C! If you find your way back down there again, I\'m always looking to add to my collection of their insignia!' WHERE `word_id` = 150546; -- locales_quest - offerrewardtext : entry=10308
UPDATE `trans_words` SET `content_loc11`='Tran\'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.' WHERE `word_id` = 137983; -- locales_quest - objectives : entry=3362
