UPDATE `trans_words` SET `content_loc11`='Twilight Totems destroyed' WHERE `word_id` = 189717; -- locales_quest - ObjectiveText1 : entry=29065
UPDATE `trans_words` SET `content_loc11`='Twilight\'s Hammer Minion slain' WHERE `word_id` = 189420; -- locales_quest - ObjectiveText1 : entry=28852
UPDATE `trans_words` SET `content_loc11`='Twilight\'s Hammer slain' WHERE `word_id` = 189586; -- locales_quest - ObjectiveText1 : entry=28900
