UPDATE `trans_words` SET `content_loc11`='Uprooted Lashers Slain' WHERE `word_id` = 173892; -- locales_quest - ObjectiveText1 : entry=14306
UPDATE `trans_words` SET `content_loc11`='Urrgh... Injured and dying and confronted with the enemy.$B$BNo doubt you\'ll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don\'t they?--I\'ll tell you what you want to know.' WHERE `word_id` = 132427; -- locales_quest - details : entry=535
UPDATE `trans_words` SET `content_loc11`='Ursius is... not delicious. He tastes like a combination of pinecones and curdled milk, only... oilier.$B$BAre you sure this is Ursius?  The big bear?  In the cave?$B$BThis is horrible. It honestly tastes like his meat has been steeped in urine.$B$BI don\'t feel like I\'m getting any stronger.$B$BUgh. It\'s really bad. Do you want to try some?' WHERE `word_id` = 188889; -- locales_quest - offerrewardtext : entry=28639
UPDATE `trans_words` SET `content_loc11`='Ursoc Cleansed' WHERE `word_id` = 159127; -- locales_quest - ObjectiveText1 : entry=12236
UPDATE `trans_words` SET `content_loc11`='Ursoc\'s children are wise. Their words explain much of what we\'ve seen so far.' WHERE `word_id` = 159101; -- locales_quest - offerrewardtext : entry=12231
