UPDATE `trans_words` SET `content_loc11`='Vicious little grell! They\'ve been stealing from our foodstores again.$B$BIf you wouldn\'t mind lending a hand, whatever they\'ve stolen is sure to be scattered through grell camps to the west. I would be glad to reward you if you can bring it all back to me.' WHERE `word_id` = 166147; -- locales_quest - details : entry=459
